quests[10575] = { id = 10575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kerker des Wächters", description = "Die Fragmente, die Ihr besorgt habt, sind nur eine Hälfte des Amuletts. Der Anführer der Aschenzungen, Akama, muss die andere Hälfte haben.\n\nIch wage es fast nicht, Euch darum zu bitten, da Akama sowohl böse als auch gerissen ist.\n\nEr und die Todeshörigen der Aschenzungen, die bösartigsten und grausamsten der Zerschlagenen, sollen irgendwo im Kerker des Wächters eine Folterkammer betreiben.\n\nIch möchte, dass Ihr dieses gefürchtete Gefängnis findet und Akamas Aufenthaltsort bestimmt. Sein Stellvertreter vor Ort ist ein Zerschlagener namens Sanoru. Befragt ihn, wenn Ihr müsst.", sourceObjective = "Anachoret Ceyla möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru befragt, um Akamas Aufenthaltsort herauszufinden.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Seher.", completion = "Wir haben Euch erwartet, {name}. Akama sagte, dass Ihr früher oder später kommen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10576] = { id = 10576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwürfigkeit in Schattenmond", description = "<Borak mustert Euch.>\n\nEs wird schwierig, aber ich glaube, es könnte klappen.\n\nIch kann Euch als einen von Illidans Blutelfen verkleiden, {name}. Aber zuerst benötige ich dazu einige Teile ihrer Rüstung. Sie muss unbedingt sauber sein. Keine Blutflecken! Wir wollen schließlich keinen Verdacht erwecken.\n\nBringt mir die Ausrüstung und ich kümmere mich um den Rest der Verkleidung.\n\nSobald die Verkleidung fertig ist, werdet Ihr dem Großkommandanten die Nachricht überbringen - persönlich!", sourceObjective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr 6 Teile der Rüstung der Mondfinsternis besorgt.", progress = "Das ist viel zu kompliziert, {race}. Ihr würdet es nicht verstehen.", completion = "Gut gemacht, {name}. Ich hoffe, Ihr seid ein guter Schauspieler. Der nächste Schritt erfordert etwas Theatralik!", sourceObjectiveStatus = "unverified-source-field" }
quests[10577] = { id = 10577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Illidan will, soll Illidan bekommen...", description = "Nehmt diese Verkleidung und begebt Euch zur Stätte der Mondfinsternis. Wenn Ihr dort seid, benutzt die Verkleidung, um Euch zu tarnen. Die Blutelfen der Mondfinsternis werden Eure Verkleidung nicht durchschauen können. Daher habt Ihr freie Bahn, bis Ihr zu Großkommandant Ruusk gelangt.\n\nSobald Ihr Ruusk gefunden habt, sagt ihm Bescheid, wo das Wort als Nächstes versteckt werden soll. Ihr müsst schauspielern, was das Zeug hält, {name}. Gebt vor, ein Untergebener zu sein, der eine Nachricht seines Fürsten überbringt. Das sollte funktionieren.\n\nAber gebt auf die Drachenfalken Acht. Sie können Eure Verkleidung durchschauen.", sourceObjective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr Großkommandant Ruusk in der Stätte der Mondfinsternis Illidans Nachricht überbringt.", completion = "Jetzt müsst Ihr nur noch die Litanei besorgen. Einfach, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[10578] = { id = 10578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Boraks Angriff", description = "Zuluhed wird diesen Teil der Litanei niemals bekommen. Ihr werdet Ruul dem Verfinsterer und seinem Transportgut auflauern, bevor er eine Chance hat, es abzuliefern.\n\nDie Festung des Drachenmals liegt direkt östlich von hier, jenseits der Netherschwingenfelder. Ihr findet Ruul irgendwo zwischen der Feste des Drachenmals und dem Sanktum der Sterne. Schlagt schnell und hart zu! Und seid vorsichtig, {name}. Ruul scheint eine harte Nuss zu sein.\n\nBringt die Litanei zu mir zurück, wenn Ihr erfolgreich wart.", sourceObjective = "Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr den dritten Teil der Litanei der Verdammnis von Ruul dem Verfinsterer besorgt.\n\nFür diesen Auftrag werdet Ihr eine Gruppe benötigen.", progress = "Ihr müsst schnell handeln!", completion = "Endlich! Das Fragment der Litanei gehört uns!\n\n<Borak verstaut das Fragment in einer Schließkassette.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10579] = { id = 10579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis - Dritter Teil", description = "Bringt diese Kassette zu meinem Vater. Er wohnt immer noch bei Oronoks Hof weit im Norden, über der Zisterne der Echsennarbe. Wenn alle drei Teile zusammengefügt sind, wird die alte Litanei auf ein Neues bekannt sein.\n\nViel Glück, {name}. Sagt meinem Vater, dass ich bald nach Hause komme.", sourceObjective = "Bringt Boraks Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal.", completion = "Sobald alle drei Teile der Litanei zusammengefügt sind, wird es wieder bekannt.\n\nDieses Dokument zu besorgen war zweifellos eine große Herausforderung. Für einen solchen Heldenmut müsst Ihr belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10580] = { id = 10580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind diese verdammten Gnome hin?", description = "Trotz all der guten Dinge, die wir hier getan haben, fühle ich mich wegen einer Sache schlecht: Wir haben Toshley und seine Gnomenfreunde vertrieben.\n\nWir hatten keine andere Wahl; sie haben mit all ihrer Technologie und ihren Experimenten unsere Bemühungen im Hain zunichtegemacht.\n\nIch wäre Euch sehr dankbar, wenn Ihr herausfinden könntet, was aus ihnen geworden ist. Unseren letzten Informationen zufolge sind sie nach Osten über die Brücke gegangen. Ich bin mir sicher, dass sie dann nach Süden von der Donnerfeste weg gezogen sind.\n\nHaltet im südlichen Zackengrat nach Spuren von ihnen Ausschau.", sourceObjective = "Sucht im südlichen Teil des Zackengrats im Schergrat nach Hinweisen auf den Verbleib von Toshley und seinen Gnomenfreunden.", completion = "SYLVANAAR? KOMMANDANT HIMMELSSCHATTEN?\n\nKEIN DATENBANKEINTRAG!\n\nTRETET ZURÜCK, BEVOR ICH MICH GEZWUNGEN SEHE, EUCH MIT LAUTEN GERÄUSCHEN ZU QUÄLEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[10581] = { id = 10581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folget den Brotkrumen", description = "HIERMIT WARNE ICH EUCH, DASS IHR AUF DEM GRAT NICHTS FINDEN WERDET.\n\nFOLGT AUF KEINEN FALL DEN ERSATZTEILEN, DIE ZU TOSHLEYS STATION FÜHREN! IHR WERDET DORT WEDER TOSHLEY NOCH EINEN ANDEREN GNOM VORFINDEN!", sourceObjective = "Folgt der Spur aus Ersatzteilen den Weg hinauf zum Messergrat und sprecht mit Toshley in Toshleys Station im Schergrat.", completion = "In Ordnung, wollt Ihr Euch nützlich machen? Gut, ich habe genau die richtige Aufgabe, mit der Ihr Euch beweisen könnt.\n\nIch glaube, Ihr werdet sie mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10582] = { id = 10582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener des Schattenrats", description = "<Ewan hört Eure Erzählung der Ereignisse in der Feste der Legion an und nickt.>\n\nJetzt geben unsere Beobachtungen einen Sinn. Wir haben gesehen, wie sie Höllenbestien zur Feste der Legion geschafft haben, aber mehr konnten wir nicht herausfinden.\n\nDer Schattenrat hat die Todesschmiede besser versiegelt als ein Fass Donnerbräu! Als erstes müsst Ihr ein paar Köpfe einschlagen, damit Ihr dort eindringen könnt. Fangt damit an, die Mitglieder des Schattenrats, die den Eingang zur Todesschmiede bewachen, zu vernichten!", sourceObjective = "Sturmrufer Ewan Wildschwinge beim Turm der Todesschmiede möchte, dass Ihr 10 Wächter der Todesschmiede und 5 Beschwörer der Todesschmiede tötet.", completion = "Ich wünschte, ich hätte mit Euch gehen können! Ich brenne schon die ganze Zeit darauf, meinen Hammer benutzen zu können, aber mein Auftrag ist es, zu beobachten, nicht zu töten.\n\nJetzt, da Ihr ein Loch in ihre Verteidigung geschlagen habt, lasst uns die Produktion in der Todesschmiede zum Stillstand bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10583] = { id = 10583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flanis' Schicksal", description = "Schwadronskommandant Nuainn hat ursprünglich drei von uns hierher geschickt, um die Todesschmiede zu beobachten und Informationen zu sammeln. Flanis Flinkschwinge hat sich freiwillig gemeldet, um sich in die Todesschmiede einzuschleichen, aber wir haben schon seit Tagen nichts mehr von ihm gehört.\n\nIch fürchte das Schlimmste, {name}. Flanis ist ein guter Späher, aber wir haben keine Ahnung, ob ihm die Sache über den Kopf gewachsen ist. Durchsucht die Todesschmiede nach ihm und beschafft sämtliche Informationen oder Gegenstände, die er gesammelt haben könnte.", sourceObjective = "Sturmrufer Ewan Wildschwinge beim Turm der Todesschmiede möchte, dass Ihr die Todesschmiede nach Flanis Flinkschwinge absucht und Flanis' Beutel zurückholt.", progress = "Habt Ihr ein Zeichen von Flanis in der Todesschmiede finden können?", completion = "<Ewan schüttelt den Kopf und nimmt Euch den Beutel ab.>\n\nIch glaube nicht, dass Flanis sich im Klaren darüber war, wie schwer die Todesschmiede bewacht ist. Jetzt, da wir wissen, was tatsächlich dort vor sich geht, mache ich ihnen keinen Vorwurf. Ich wünschte nur, dass Flanis es gewusst hätte, als er dort hinein gegangen ist.\n\nIch kann nur hoffen, dass irgendetwas in diesem Beutel uns dabei helfen kann, die Todesschmiede ein für allemal auszuschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10584] = { id = 10584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Stromwandler besorgen", description = "Diese dummen Oger am Außenposten der Speerspießer im Norden haben unsere Stromwandler gestohlen! Und Ihr werdet sie mir zurückbringen, oder so in der Art.\n\nDie Oger haben sie sicher mit ihren groben, ungeschickten Händen kaputt gemacht. Ich möchte, dass Ihr die in ihnen gespeicherte Energie freisetzt und das so entstehende Elektromentar mit diesem protovoltaischen Magnetsammler einfangt.\n\nEs wird sicher sauer auf Euch sein, Ihr müsst es also 'töten', während es im Magnetfeld gefangen ist.", sourceObjective = "Verwendet den protovoltaischen Magnetsammler, um 5 Elektromentare einzufangen.", progress = "Diese Forschungsreihe mit den Elektromentaren ist faszinierend! Stellt Euch nur vor... Eine intelligente Kreatur, die wir nach Belieben erschaffen können und die all unseren Anweisungen folgt!\n\nWas kann da schon schiefgehen?", completion = "Ausgezeichnet! Mit der ganzen Energie, die Ihr gesammelt habt, werden wir die Maschinerien für eine Weile am Laufen halten können.\n\nDas Zephyriumkapazitorium ist ein echter Schluckspecht, wenn es um den Energieverbrauch geht!\n\nIch hoffe, mit den Elektromentaren fertig zu werden war nicht allzu schwierig. Ich habe noch eine andere Aufgabe für Euch. Ich fürchte, sie wird etwas schwerer werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10585] = { id = 10585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörungskammer", description = "Um mit der Konstruktion der Höllenbestien so schnell nachzukommen, muss der Schattenrat einen Bereich bestimmt haben, an dem die verderbten Elemente, die den Höllenbestien als Seele dienen, beschworen werden.\n\nDie Kammer der Beschwörung liegt wahrscheinlich unter der Erde in der Nähe eines Teichs mit fauligem Wasser oder Lava. Sucht die Beschwörungskammer in der Todesschmiede und unterbrecht ihr Beschwörungsritual! Vielleicht tragen die Mo'arg, die bei der Produktion der Höllenbestien teilhaben, ja ein Instrument dabei, mit dem Ihr die Magie der Beschwörer unterbrechen könnt.", sourceObjective = "Besorgt Euch eine Elementarsteuerung von einem Schmied der Todesschmiede oder einem Tüftler der Todesschmiede. Benutzt sie, um das Ritual in der Beschwörungskammer zu unterbrechen. Meldet Euch danach bei Sturmrufer Ewan Wildschwinge im Turm der Todesschmiede zurück.", progress = "Wir können nicht zulassen, dass sie weiter produzieren. Habt Ihr dem Beschwörungsritual ein Ende gesetzt?", completion = "Gut gemacht, {name}. Die Beschwörung des Schattenrats zu unterbrechen bringt uns einen Schritt näher an die Abschaltung der Todesschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[10586] = { id = 10586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Kriegshetzer!", description = "Wir haben große Fortschritte gegen die Operationen des Schattenrats bei der Todesschmiede erzielt. Wenn wir jedoch wirklich siegen wollen, müssen wir den Aufseher der Legion dort vernichten.\n\nIch habe unter den Gegenständen in Flanis Beutel einen Schlüssel gefunden. Ich bin mir sicher, dass er sich bei der Suche nach Kriegshetzer Razuun, den Ihr in der Feste der Legion beobachtet habt, als nützlich erweisen wird.\n\nNachdem Ihr Kriegshetzer Razuun aufgespürt und erschlagen habt, meldet Euch gleich bei Schwadronskommandant Nuainn. Er wird sofort davon erfahren wollen!", sourceObjective = "Besiegt Kriegshetzer Razuun, beschafft Razuuns Befehle und meldet Euch bei Schwadronskommandant Nuainn in der Wildhammerfeste.", progress = "Bringt Ihr Neuigkeiten aus der Todesschmiede?", completion = "<Ihr erstattet dem Schwadronskommandanten Bericht und übergebt die gefundenen Befehle.>\n\nKriegshetzer Razuun zu besiegen sollte eigentlich das Ende unserer Probleme mit der Legion bedeuten, aber in diesen Befehlen steht deutlich mehr, als ich befürchtet hatte. Ich glaube, wir haben noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10587] = { id = 10587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildungsgelände von Karabor", description = "Unsere Späher haben uns von einem massiven Zufluss von Blutelfenrekruten des Sonnenzorns in den Ruinen von Karabor berichtet. Normalerweise würden wir darin eine rein militärische Bedrohung sehen, doch wir glauben, dass hier noch mehr im Argen liegt.\n\nDie Beschreibungen ihrer Kleidung und ihres Kampfstils klingen verdächtig nach Illidan selbst. Ich will mich nicht ohne handfeste Beweise beunruhigen, daher möchte ich Euch bitten, dorthin zu gehen und mir ihre Waffen zu bringen. Dann werden wir sehen, ob meine Befürchtungen unbegründet sind oder nicht.", sourceObjective = "Exarch Onaala beim Altar der Sha'tar möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, südöstlich des Altars der Sha'tar, beschafft.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr die Aufgabe, die ich Euch gegeben habe, schon erledigt, {name}?", completion = "Wollen wir uns diese Waffen einmal genauer ansehen, {name}. Hmmm... das ist ziemlich beunruhigend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10588] = { id = 10588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis", description = "Wie oft wurde dieser Zauber in der Geschichte unserer Welten benutzt? Seine zerstörerische Macht ist mit Sicherheit einzigartig.\n\nIhr müsst die Litanei nun, da sie vollständig ist, zum Altar der Verdammnis bringen, wo Gul'dans Erinnerung steht, und daraus lesen.\n\nSobald die Worte gesprochen werden, werdet Ihr die Erinnerungen, die in das Land eingebrannt wurden, sehen. Bleibt standhaft und erwartet die Ankunft Cyrukhs.\n\nIhr müsst siegen, {name}. Dieses Land kann einer weiteren Zerschlagung nicht standhalten.", sourceObjective = "Benutzt die Litanei der Verdammnis am Altar der Verdammnis um Cyrukh den Feuerlord zu rufen.\n\nVernichtet Cyrukh den Feuerlord und sprecht danach mit Erdheiler Torlok, der sich ebenfalls am Altar der Verdammnis befindet.", progress = "Ist es vollbracht?", completion = "<Erdheiler Torlok nimmt Euch die Litanei der Verdammnis ab.>\n\nIhr habt getan, worum Euch die Elemente gebeten haben. Dafür sind wir sehr dankbar. Ihr werdet belohnt werden, doch der Ärger lauert noch immer auf uns. Die Geister des Feuers sind in Aufruhr. Es wurde eine Forderung vorgebracht. Ein weiterer kennt die Litanei der Verdammnis.\n\nIch weiß, das klingt sehr kryptisch, aber das ist alles, was die Geister mir mitgeteilt haben. Das und dieses Symbol...\n\n<Erdheiler Torlok dreht sich um und zeigt gen Himmel.>\n\nWas könnte das wohl bedeuten?", sourceObjectiveStatus = "unverified-source-field" }
quests[10589] = { id = 10589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang erlangen", description = "Laut Razuuns Befehlen wird der riesige Stützpunkt der Höllenbestien Invasionspunkt: Katastrophe genannt und befindet sich in den nördlichen Bergen. Die einzige Weise, auf die man dorthin gelangen kann, ist ein Teleporter, der sich in der Feste der Legion befindet.\n\nAusgewählte Mitglieder der Legion tragen Geräte bei sich, mit denen sie die Teleporter aktivieren können. Ihr müsst Euch eines dieser Geräte besorgen, um Zugang zu dem Teleporter zu erlangen. Tötet alle Dämonen, wenn Ihr es müsst, aber kommt auf keinen Fall mit leeren Händen zurück.", sourceObjective = "Bringt eine Teleportersteuerung der Legion zu Schwadronskommandant Nuainn in der Wildhammerfeste. Bekanntlich tragen die Waffenschmiede der Mo'arg in der Feste der Legion diese Geräte bei sich.", progress = "Wir müssen einen Weg finden, um diese Höllenbestien zu vernichten, {name}. Wir sind schon weit gekommen, aber ein Fehlschlag würde uns alles kosten.", completion = "Lasst mich schauen, ob ich herausfinden kann, wie das funktioniert...", sourceObjectiveStatus = "unverified-source-field" }
quests[10590] = { id = 10590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Euren Hass!", description = "Es ist an der Zeit, dass Ihr Euch an Vergangenes erinnert, das nicht vergessen werden sollte... das Abschlachten unseres Volkes durch Arthas und seine Armeen der Geißel.\n\nRache an der Geißel ist der einzige Weg, Euren Schmerz zu lindern. Es ist bedauerlich, dass sie keine Angst und keinen Schmerz empfinden können. Nur ihre Vernichtung kann Euch einen Hauch von Genugtuung bringen.\n\nSprecht mit Argentumoffizier Garush, um mehr über die Geißelsteine zu erfahren und wie man sie bekommt. Ich werde viele davon als Beweis für Euren Einsatz brauchen, bevor ich erneut mit Euch spreche.", sourceObjective = "Mehlar Dämmerklinge beim Bollwerk möchte, dass Ihr ihm 20 Geißelsteine des Dieners bringt.", progress = "Hat die Geißel Eure Waffe bereits zu spüren bekommen?", completion = "Sehr gut, {name}. Vielleicht genießt Ihr doch den süßen Geschmack der Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[10592] = { id = 10592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit der Bansheekönigin", description = "Die Geißelsteine sind schwach, wenn sie aus dem knochigen Griff, der sie einst umfasste, gerissen werden. Sie zerbröseln und zerbrechen schon, wenn ich sie einfach nur in der Hand halte.\n\n<Mehlar zerdrückt die Geißelsteine mit bloßer Hand.>\n\nBringt diese Fragmente zur Bansheekönigin Sylvanas Windläufer. Ihr Thron befindet sich in Unterstadt. Sie hütet das Geheimnis, wie man diese Überreste in eine Waffe gegen die Geißel verwandelt.", sourceObjective = "Bringt die Geißelsteinfragmente zu Fürstin Sylvanas Windläufer in Unterstadt.", progress = "Habt Ihr etwas für mich, {race}?", completion = "Diese Steine tragen einen Hauch der Verderbnis an sich, an den ich mich nicht erinnern möchte und den ich doch nicht vergessen kann. Dass Ihr sie zu mir bringt stellt meine Geduld auf eine harte Probe.\n\nUnd doch ist offensichtlich, dass Euer Herz sich nach derselben Rache sehnt wie meines, und ich werde Euch helfen, sie zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10593] = { id = 10593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das uralte Böse", description = "Wenn Ihr diese Steine in eine Waffe gegen die Geißel verwandeln wollt, müsst Ihr etwas ebenso Bösartiges besorgen, um sie zu verstärken.\n\nTief im Versunkenen Tempel in den Sümpfen des Elends schlummert eine uralte böse Präsenz. Befreit diese Kreatur und vernichtet sie. Bringt einen kleinen Teil ihres Körpers zu Mehlar Dämmerklinge. Meine Wachen werden ihm die Geißelsteinfragmente zukommen lassen.", sourceObjective = "Lüftet die Geheimnisse des Versunkenen Tempels und befreit Atal'alarion. Tötet ihn und schneidet die Fäulnisranke aus seinem Fleisch. Kehrt danach zu Mehlar beim Bollwerk zurück.", progress = "Da Ihr noch am Leben seid, nehme ich an, dass Fürstin Sylvanas Euch Weisheit anstatt des Todes geschenkt hat.", completion = "Die Bansheekönigin hat Euch einen guten Rat gegeben. Genau das brauchen wir, um die Fragmente zusammen zu fügen.\n\n<Mehlar beobachtet, wie die Ranke sich durch die Fragmente schlängelt und sie verbindet.>\n\nSchaut! Ich nenne es Geißelbann. Doch gebt Acht, wenn Ihr es benutzt, denn es dient Euch gegen seinen Willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10594] = { id = 10594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klangfrequenz messen", description = "Bringt diese Messgeräte zum Singenden Bergrücken. Wenn Ihr sie in einem Muster auf dem Boden auslegt, werden sich überlappende Felder erzeugt, die die Schwingungsweite der Kristalle messen. Es funktioniert aber nur, wenn Ihr in ihrer Mitte steht und von allen fünf Schwingungsfeldern berührt werdet.\n\nEure Messgeräte funktionieren auch mit den Messgeräten, die andere vor Euch dort abgelegt haben.\n\nOh, und es kann sein, dass dabei ein Riss entsteht. Ich habe jedoch keine Ahnung, was dadurch in unsere Welt gelangen könnte, aber macht Euch auf das Schlimmste gefasst.", sourceObjective = "Ordnet die oszillierenden Schwingungsmesser so an, dass Ihr, wenn Ihr in ihrer Mitte steht, von fünf sich überlappenden Schwingungsfeldern berührt werdet.", progress = "Nun, habt Ihr die Messungen der singenden Kristalle, um die ich Euch gebeten habe?", completion = "Oh, das ist außergewöhnlich! Ich hatte ja keine Ahnung... Es ist fast so, als wären die Kristalle lebendig!\n\nIch frage mich, ob eine Art symbiotische Beziehung zwischen ihnen und den Netherdrachen besteht.\n\nVielen Dank, vielen Dank! Ihr müsst etwas aus meiner Kuriositätensammlung nehmen, das ich nichtmal im Tode anziehen würde!\n\nAn Euch könnte etwas davon jedoch gut aussehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10595] = { id = 10595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagert!", description = "<Gulmok schaut zum Himmel auf.>\n\nUnsere Späher schlagen sich wacker, aber die Höllenbestien greifen immer wieder an.\n\nVon ihrer Basis in der Feste der Legion im Südwesten aus bombardieren sie uns gnadenlos. Sogar die Elitewachen der Kor'kron können sie nicht ewig aufhalten.\n\nIch rekrutiere jedes fähige Individuum, damit es seinen Teil zur Verteidigung Schattenmonds beiträgt. Das ist kein Spiel, {class}. Das Überleben des Dorfes ist in Gefahr. Tut Eure Pflicht gegenüber der Horde und schließt Euch dem Kampf an!", sourceObjective = "Blutwache Gulmok außerhalb von Schattenmond möchte, dass Ihr 10 angreifende Höllenbestien tötet.", completion = "Ich bin beeindruckt, dass Ihr dieses Gemetzel überlebt habt. Ihr seid vielleicht genau die Person, die wir für einen gefährlichen Auftrag brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10596] = { id = 10596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Feste der Legion", description = "Die Feste der Legion ist Euer Ziel. Ihr werdet keine Verstärkung erhalten, daher ist ein Frontalangriff unmöglich.\n\nDie wenigen Informationen, die wir sammeln konnten, weisen darauf hin, dass die Legion die Höllenbestien in der Feste lagert und vorbereitet. Ich möchte, dass Ihr die Feste in der Verkleidung, die ich Euch geben werde, nach detaillierten Informationen über die Pläne der Legion durchsucht.\n\nWir können nur hoffen, dass Ihr die Gespräche zwischen ihren Kommandanten abfangen oder belauschen könnt.", sourceObjective = "Begebt Euch zur Feste der Legion, findet ein Kommunikationsgerät der Legion und benutzt es, um mehr über die Pläne der Legion herauszufinden, während Ihr verkleidet seid. Kehrt danach zu Blutwache Gulmok in Schattenmond zurück.", progress = "Was habt Ihr herausgefunden?", completion = "<Blutwache Gulmok hört sich Euren Bericht an und wird mit jedem Satz nervöser.>\n\nWas meint Ihr mit sie wollen ihre Angriffe noch verstärken? Das können wir nicht zulassen. Kehrt dorthin zurück und kümmert Euch darum, solange in Schattenmond noch ein Stein auf dem anderen steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10597] = { id = 10597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bombe bauen", description = "Wir können der Legion nicht erlauben, uns auf ihrem Marsch zum Schwarzen Tempel zu zertrampeln.\n\nFindet einen Weg, um die Höllenbestien, die sie gegen uns einsetzen wollen, zu vernichten. Das ist keine Bitte, {name}, sondern ein Befehl.\n\nAm Fauligen Teich in der Nähe der Feste der Legion gibt es viele alte Teufelshäscherkraftkerne, die Ihr als Grundlage für eine Art Teufelsbombe verwenden könnt. Durchsucht die anderen Trümmer in der Nähe der Feste nach Rüstungsplatten. Daraus sollte man eine Bombe basteln können, die so stark ist, dass sie diese Höllenbestien vernichten und die Feste zum Beben bringen wird!", sourceObjective = "Besorgt Euch einen Teufelshäscherkraftkern und eine Teufelshäscherrüstungsplatte und bringt sie zu Blutwache Gulmok in Schattenmond.", progress = "<Ihr reicht Gulmok die Materialien.>", completion = "<Gulmok platziert den Kraftkern in dem Gehäuse und versiegelt es.>\n\nDas sollte funktionieren. Ich möchte nicht in der Feste sein, wenn das Ding hochgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10598] = { id = 10598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Höllenbestien in die Luft!", description = "Das Gerät, das wir zusammengebaut haben, würde keinen Schönheitspreis gewinnen, aber es sollte die Höllenbestien in der Feste der Legion zerstören können. Danach zu urteilen, was der Kraftkern des Teufelshäschers bei dem Fauligen Teich angerichtet hat, muss darin eine gehörige Explosionskraft stecken.\n\nWenn Ihr das Gerät in der Mitte der grünen Glyphe in der Feste platzieret, solltet Ihr alle Höllenbestien erwischen können.", sourceObjective = "Zündet die Teufelsbombe, während Ihr auf der grünen Glyphe in der Feste der Legion steht. Meldet Euch bei Blutwache Gulmok in Schattenmond zurück, wenn Ihr Euren Auftrag erledigt habt.", progress = "Habt Ihr einen Weg gefunden, um den Vorrat an Höllenbestien der Legion zu zerstören?", completion = "<Gulmok nickt grimmig.>\n\nWir haben keine Zeit zu feiern, {name}. Noch sind wir nicht aus der Schusslinie. Ich habe neue Befehle für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10599] = { id = 10599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todesschmiede", description = "Während Ihr Euch um die Höllenbestien bei der Feste der Legion gekümmert habt, bin ich Euren Bericht durchgegangen. Wir haben keinen Grund zu glauben, dass die Legion bezüglich der Geschehnisse in der Todesschmiede gelogen hat. Sie stellen dort wirklich Höllenbestien am Fließband her. Daher habe ich eine Gruppe von Spähern dorthin geschickt, um die Schmiede zu beobachten.\n\nWenn wir dem Treiben der Todesschmiede kein Ende setzen, werden sie die Schar an Höllenbestien, die Ihr in der Feste der Legion vernichtet habt, im Handumdrehen wieder aufgestockt haben.\n\nMeldet Euch bei Späher Zagran in der Schlackenwacht im Südosten, die die Todesschmiede überblickt.", sourceObjective = "Meldet Euch bei Späher Zagran in der Schlackenwacht.", completion = "<Der Orc nickt.>\n\nVerstärkung ist gut. Wir haben zwar schon grundlegende Informationen darüber gesammelt, was der Schattenrat dort drin vor hat, doch es ist Zeit zuzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10600] = { id = 10600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener des Schattenrats", description = "<Zagran hört Eure Erzählung der Ereignisse in der Feste der Legion an und nickt.>\n\nJetzt geben unsere Beobachtungen einen Sinn. Wir haben gesehen, wie sie Höllenbestien zur Feste der Legion geschafft haben, aber mehr konnten wir nicht herausfinden.\n\nDer Schattenrat hat die Todesschmiede ziemlich gut abgeriegelt. Sieht aus, als müsstet Ihr Euch den Weg hinein mit Gewalt freiräumen. Fangt damit an, die Mitglieder des Schattenrats, die den Eingang zur Todesschmiede bewachen, zu vernichten!", sourceObjective = "Späher Zagran in der Schlackenwacht möchte, dass Ihr 10 Wächter der Todesschmiede und 5 Beschwörer der Todesschmiede tötet.", completion = "Ich wäre ja selbst dorthin gegangen und hätte ein paar Schädel zertrümmert, aber ich habe strengste Anweisungen, mich nicht auf einen direkten Kampf mit dem Feind einzulassen.\n\n<Der Späher grummelt und imitiert Blutwache Gulmoks Stimme.>\n\nLasst uns die Produktion in der Schmiede zum Stillstand bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10601] = { id = 10601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kagroshs Schicksal", description = "Ursprünglich waren wir hier zu dritt. Unglücklicherweise musste Kagrosh unbedingt den Helden spielen.\n\nEr ist in die Todesschmiede gegangen. Seitdem haben wir nichts mehr von ihm gehört.\n\nAller Wahrscheinlichkeit nach ist der Dummkopf in seinen sicheren Tod gezogen. Die Mitglieder des Schattenrats sind nicht dumm und Kagrosh ist nicht gerade ein Ausbund an Subtilität, wenn Ihr versteht, was ich meine. Haltet in der Todesschmiede Ausschau nach ihm und beschafft sämtliche Informationen oder Gegenstände, die er gesammelt haben könnte.", sourceObjective = "Späher Zagran in der Schlackenwacht möchte, dass Ihr die Todesschmiede nach Kagrosh absucht und Kagroshs Beutel zurückholt.", progress = "Habt Ihr ein Zeichen von Kagrosh in der Todesschmiede finden können?", completion = "<Zagran schüttelt den Kopf und nimmt Euch den Beutel ab.>\n\nIch habe Euch doch gesagt, dass er ein Dummkopf ist. Ich hoffe, dass in diesem Beutel irgendetwas ist, die Zeit, die Ihr mit der Suche nach ihm verbracht habt, rechtfertigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10602] = { id = 10602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörungskammer", description = "Um mit der Konstruktion der Höllenbestien so schnell nachzukommen, muss der Schattenrat einen Bereich bestimmt haben, an dem die verderbten Elemente, die den Höllenbestien als Seele dienen, beschworen werden.\n\nDie Beschwörungskammer liegt wahrscheinlich unter der Erde in der Nähe eines Teichs mit fauligem Wasser oder Lava. Sucht die Beschwörungskammer in der Todesschmiede und unterbrecht ihr Beschwörungsritual! Vielleicht tragen die Mo'arg, die bei der Produktion der Höllenbestien teilhaben, ja ein Instrument dabei, mit dem Ihr die Magie der Beschwörer unterbrechen könnt.", sourceObjective = "Besorgt Euch eine Elementarsteuerung von einem Schmied der Todesschmiede oder einem Tüftler der Todesschmiede. Benutzt sie, um das Ritual in der Beschwörungskammer zu unterbrechen. Meldet Euch danach bei Späher Zagran in der Schlackenwacht zurück.", progress = "Wir können nicht zulassen, dass sie weiter produzieren. Habt Ihr dem Beschwörungsritual ein Ende gesetzt?", completion = "Gut. Wir machen Fortschritte. Das bringt uns einen Schritt näher an die Abschaltung diese Monstrosität. Bald können wir sicher nach Schattenmond zurückreisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10603] = { id = 10603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Kriegshetzer!", description = "Wir haben große Fortschritte gegen den Schattenrat bei der Todesschmiede erzielt, doch nun ist es an der Zeit, die Sache zu Ende zu bringen.\n\nIch habe unter den Gegenständen in Kagroshs Beutel einen Schlüssel gefunden. Wenigstens hat er das noch hinbekommen, bevor sie ihn erwischt haben.\n\nDer Schlüssel sollte Euch dabei helfen, Kriegshetzer Razuun, den Ihr in der Feste der Legion beobachtet habt, ausfindig zu machen.\n\nNachdem Ihr Kriegshetzer Razuun aufgespürt und erschlagen habt, meldet Euch gleich bei Blutwache Gulmok. Wir dürfen ihn nicht warten lassen.", sourceObjective = "Besiegt Kriegshetzer Razuun, beschafft Razuuns Befehle und meldet Euch bei Blutwache Gulmok in Schattenmond.", progress = "Bringt Ihr Neuigkeiten aus der Todesschmiede?", completion = "<Ihr erstattet der Blutwache Bericht und übergebt die gefundenen Befehle.>\n\nGute Arbeit, {name}, aber denkt nicht, dass Ihr dafür einen Orden verliehen bekommt. Die Nachtelfen mögen vielleicht ihre hübschen kleinen Uniformen dekorieren. Echte Krieger teilen jedoch ihre Geschichten von der Schlacht bei einem kühlen Krug Bier.", sourceObjectiveStatus = "unverified-source-field" }
quests[10604] = { id = 10604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang erlangen", description = "Laut Razuuns Befehlen wird der riesige Stützpunkt der Höllenbestien Invasionspunkt: Katastrophe genannt und befindet sich in den nördlichen Bergen. Die einzige Weise, auf die man dorthin gelangen kann, ist ein Teleporter, der sich in der Feste der Legion befindet.\n\nAusgewählte Mitglieder der Legion tragen Geräte bei sich, mit denen sie die Teleporter aktivieren können. Ihr müsst Euch eines dieser Geräte besorgen, um Zugang zu dem Teleporter zu erlangen. Tötet alle Dämonen, wenn Ihr es müsst, aber kommt auf keinen Fall mit leeren Händen zurück. Verschwendet keine Zeit; der Feind ist schon gefährlich nahe.", sourceObjective = "Bringt eine Teleportersteuerung der Legion zu Blutwache Gulmok in Schattenmond. Bekanntlich tragen die Waffenschmiede der Mo'arg in der Feste der Legion diese Geräte bei sich.", progress = "Die Anwesenheit der Legion in unserer Mitte ist nicht akzeptabel! Wir müssen einen Weg finden, damit fertig zu werden, bevor sie ihre Angriffe erneuern können.", completion = "Endlich haben wir ein Mittel, mit dem wir die Legion aus Schattenmond vertreiben können!", sourceObjectiveStatus = "unverified-source-field" }
quests[10605] = { id = 10605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carendin ruft", description = "Ihr habt einen hungrigen Ausdruck in den Augen, {name}. Vielleicht ist es an der Zeit, dass Ihr Eure Ausbildung fortsetzt.\n\nReist nach Unterstadt und sprecht mit Carendin Halgar. Der alte Knochenhaufen hat ein oder zwei Tricks auf Lager, die Euch interessieren dürften.", sourceObjective = "Sprecht mit Carendin Halgar in Unterstadt.", completion = "Ah, noch ein hungriger Initiand. Wunderbar!\n\nIhr wärt kein richtiger Hexenmeister, wenn es Euch nicht nach Rache dürstete, oder, Mädel? Dann mal los.", sourceObjectiveStatus = "unverified-source-field" }
quests[10606] = { id = 10606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Teufelshäscherwartung", description = "Der beste Weg, um die Vorräte der Legion zu zerstören, ist, ihre eigenen Waffen gegen sie zu verwenden. Ich habe eine Anlage gebaut, mit deren Hilfe Ihr eine dieser Schildwachen der Teufelshäscher dort unten steuern könnt.\n\nEs gibt jedoch noch einige Dinge, die ich zuerst herausfinden muss. Dafür benötige ich das Handbuch, das Doktor Gutrick in einer Truhe am Ende der Rampe verschlossen hält. Wahrscheinlich rückt er den Schlüssel dazu nicht ohne Kampf heraus. Bringt mir das Teufelshäscherhandbuch und ich erledige den Rest!", sourceObjective = "Tötet Doktor Gutrick und beschafft Euch den Schlüssel des Doktors. Benutzt den Schlüssel, um die Geldkassette des Doktors zu öffnen und 'Die Kunst der Teufelshäscherwartung' daraus zu entnehmen. Bringt das Buch zu Plexi beim Invasionspunkt: Katastrophe.", progress = "Habt Ihr das Handbuch?", completion = "Ah, genau was wir brauchen. Die Legion ist zwar nicht für Ihre Meisterwerke der Weltliteratur bekannt, aber es sollte seinen Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10607] = { id = 10607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Flüstern des Rabengottes", description = "In Grishnath können die Arakkoa mithilfe der Totems, die die Orakel des Raben aufgestellt haben, die Worte des Raben hören. Leider sind wir der Sprache der Arakkoa nicht mächtig.\n\nMit dem Anhänger des Herolds können wir sie verstehen. Ihr könnt die Seele der Arakkoa aufnehmen und so ihrer Sprache mächtig werden. Begebt Euch zu den Totems, während ihr mit dem Geist der Arakkoa erfüllt seid, und hört Euch ihre Nachricht an.\n\nFindet es für uns heraus, {name}.", sourceObjective = "Tötet die Arakkoa der Grishna, um für 2 Minuten den Zauber 'Rabensprache verstehen' zu erhalten. Hört Euch die Prophezeiungen aller vier Schreine an, solange der Zauber aktiv ist.", completion = "Das ist wirklich beunruhigend. Die Arakkoa waren lange ein friedliebendes Volk. Dieser Rabenkult ist nichts als eine Versammlung von Außenseitern und Verrückten.\n\nAber wir können nicht leugnen, dass ihre Macht wächst. Vielleicht steckt hinter diesem Raben mehr, als wir vermuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10608] = { id = 10608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklar", description = "Diese verdammten Felsklauen halten mich von meinen Forschungen unten im Singenden Bergrücken ab! Sie graben bei den Kristallen und ruinieren so all meine Hoffnungen, die Harmonien der singenden Kristalle zu untersuchen.\n\nIhr seht aus, als könntet Ihr mir dabei helfen. Begebt Euch nach Süden und rottet diese Kristallfelsklauen aus!", sourceObjective = "Tötet 10 Kristallfelsklauen.", progress = "Habt Ihr die Kristallfelsklauen im singenden Bergrücken schon vernichtet? Sonst kann ich mit meinen Untersuchungen nicht beginnen.", completion = "Ein Glück, dass ich sie los bin! Verdammte Biester!\n\nWenn Ihr sicher seid, dass Ihr diese Nervensägen ausgelöscht habt, habe ich ein kleines Forschungsprojekt für Euch. Ihr werdet es sicher mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10609] = { id = 10609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was war zuerst da, der Drache oder das Ei?", description = "Ich habe einige Experimente zur Verwendungsweise der Drachenessenzen im Rahmen meiner Arbeit als Arzt durchgeführt. Ich bin mir sicher, dass diese Essenz ein Allheilmittel für Unmengen von Krankheiten sein kann!\n\nJetzt brauche ich nur noch jemanden, der für mich nach Süden zum Singenden Bergrücken geht und mir ein wenig davon besorgt.\n\nHabt Ihr Lust, meinen temporalen Phasenstrahler zu benutzen, um den Netherwelpen, die aus den Netherdracheneiern schlüpfen, ihre Essenz zu entziehen?\n\nIch muss Euch jedoch warnen: es handelt sich hierbei um ziemlich heikle und zeitverändernde Technologie. Ich habe keine Ahnung, in was sich die Netherwelpen verwandeln könnten.", sourceObjective = "Beschafft Euch 3 Essenzen eines Protonetherdrachen, 3 Essenzen eines heranwachsenden Netherdrachen und 3 Essenzen eines ausgewachsenen Netherdrachen.", progress = "Habt Ihr sie? Habt Ihr die Drachenessenzen, die ich so dringend brauche, um meine Experimente weiter zu führen?\n\nWusstet Ihr, dass diese Nethergroßdracheneier einmal Schwarzdracheneier waren? Es ist wahr! Aber als Draenor in tausend Stücke gesprengt wurde, wurden die Eier von dem herumwirbelnden Nether mutiert.", completion = "Ihr habt ja keine Ahnung, wie wichtig diese Experimente sein werden. Vielen Dank!\n\nEs wird aufregend werden, sich mit diesen Essenzen zu befassen. Ich bin besonders gespannt, ob der Nether, der die schwarzen Dracheneier zu Netherdracheneiern verwandelt hat vielleicht ein besonderer Segen für meine Studien ist.\n\nDa fällt mir gerade ein, dass Ihr die erste Person sein solltet, die die Vorzüge meines kleinen Gebräus genießen sollte. Hier, nehmt diese Proben und benutzt sie, wenn Ihr sie braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10611] = { id = 10611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Teufelshäscherwartung", description = "Der beste Weg, um die Vorräte der Legion zu zerstören, ist, ihre eigenen Waffen gegen sie zu verwenden. Ich habe eine Anlage gebaut, mit deren Hilfe Ihr eine dieser Schildwachen der Teufelshäscher dort unten steuern könnt.\n\nEs gibt jedoch noch einige Dinge, die ich zuerst herausfinden muss. Dafür benötige ich das Handbuch, das Doktor Maleficus in einer Truhe am Ende der Rampe verschlossen hält. Wahrscheinlich rückt er den Schlüssel dazu nicht ohne Kampf heraus. Bringt mir das Teufelshäscherhandbuch und ich erledige den Rest!", sourceObjective = "Tötet Doktor Maleficus und beschafft Euch den Schlüssel des Doktors. Benutzt den Schlüssel, um die Geldkassette des Doktors zu öffnen und 'Die Kunst der Teufelshäscherwartung' daraus zu entnehmen. Bringt das Buch zu Nakansi beim Invasionspunkt: Katastrophe.", progress = "Habt Ihr das Handbuch?", completion = "Das enthält alle nötigen Informationen. Nur noch ein paar Handgriffe, und Ihr habt in null Komma nichts die Kontrolle über einen Teufelshäscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[10612] = { id = 10612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelshäscherdrift", description = "<Plexi blättert das Handbuch durch.>\n\nNun, hier steht alles drin, was wir brauchen, aber es gibt ein Problem. Teufelshäscher sind nicht wirklich dafür konstruiert, ferngesteuert zu werden.\n\nWir können einen davon so umbauen, dass es für kurze Zeit funktioniert, aber wir müssen schnell arbeiten. Sonst kann keiner die Folgen absehen. Es würde mich auch nicht wundern, wenn Euer kleines Kunststück mit dem Teufelshäscher die Aufmerksamkeit der Lakaien der Legion auf sich ziehen würde. Passt gut auf Euch auf. Und was immer Ihr tut, vergesst nicht, so viele wie möglich zu zerstören!", sourceObjective = "Benutzt die Teufelshäscherfernsteuerung, um eine Schildwache der Teufelshäscher zu steuern. Zerstört 60 todesgeschmiedete Höllenbestien bevor Euer Teufelshäscher versagt. Meldet Euch danach bei Plexi am Invasionspunkt: Katastrophe.", progress = "Ihr seid zurück. Ich gehe also davon aus, dass Ihr Euren Auftrag erledigt habt. Was habt Ihr zu berichten?", completion = "Erstaunlich! Ihr habt geschafft, was keiner der Greifenreiter der Wildhammerfeste bewerkstelligen konnte! Ihr habt den Vormarsch der Brennenden Legion aufgehalten und uns vor der Vernichtung durch diese schrecklichen Höllenbestien gerettet. Ihr habt unseren tiefsten Dank für Eure Dienste, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10613] = { id = 10613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelshäscherdrift", description = "<Nakansi blättert das Handbuch durch.>\n\nHier sind alle Informationen gesammelt, aber seid gewarnt. Diese Dinger wurden nicht gebaut, um ferngesteuert zu werden.\n\nWir können einen davon so umbauen, dass es für kurze Zeit funktioniert, aber wir müssen schnell arbeiten. Sonst kann keiner die Folgen absehen. Es würde mich auch nicht wundern, wenn Euer kleines Kunststück mit dem Teufelshäscher die Aufmerksamkeit des Legionsabschaums auf sich ziehen würde. Passt auf Euch auf, aber denkt daran, dass die Mission und die Sicherheit Schattenmonds vorgehen!", sourceObjective = "Benutzt die Teufelshäscherfernsteuerung, um eine Schildwache der Teufelshäscher zu steuern. Zerstört 60 todesgeschmiedete Höllenbestien bevor Euer Teufelshäscher versagt. Meldet Euch danach bei Nakansi am Invasionspunkt: Katastrophe.", progress = "Ihr seid zurück. Ich gehe also davon aus, dass Ihr Euren Auftrag erledigt habt. Was habt Ihr zu berichten?", completion = "Ich gebe zu, {name}, ich bin von Euren Errungenschaften beeindruckt. Jetzt, da die Legion nicht länger die Mittel hat, uns in Schattenmond anzugreifen, können wir uns anderen Fronten zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10614] = { id = 10614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Flüstern im Wind", description = "Ich habe in der gesamten Scherbenwelt Gerüchten über die Mok'Nathal nachgejagt und nichts als weitere Gerüchte und Geschichten gefunden. Aber nun haben wir vielleicht tatsächlich ihr Zuhause ausfindig gemacht.\n\nNun, da dieser Moment endlich da ist, fühle ich mich sehr unwohl. Dieses Unwohlsein hat mich während meiner Suche Nacht für Nacht wach gehalten. Werden sie mich annehmen?\n\nIch... kenne den Namen ihres Anführers: Leoroxx. Sucht nach ihm. Seid meine Augen.", sourceObjective = "Sprecht mit Leoroxx im Dorf der Mok'Nathal im Schergrat.", completion = "Was führt Euch in unser Dorf?", sourceObjectiveStatus = "unverified-source-field" }
quests[10615] = { id = 10615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruuanwald", description = "Die Informationen, die ich mit Eurer Hilfe über das Wesen der Arakkoa sammeln konnte, sind auch noch für jemand anders von Interesse.\n\nWir wurden von ein paar Mitgliedern der Expedition des Cenarius aufgesucht, die sich ebenfalls Sorgen um die Pläne der Arakkoa hier im Schergrat machen.\n\nIhr solltet Timeon aufsuchen. Er befindet sich im Ewigen Hain im Ruuanwald. Folgt einfach von hier aus der Straße nach Westen und geht dann an der Weggabelung im Messergrat nach Norden. Wendet Euch nach Westen, wo die Wege in der Messerschlucht sich teilen.", sourceObjective = "Sprecht mit Timeon im Ewigen Hain im Ruuanwald des Schergrats.", completion = "Ah, ja, Dertrok. Wir haben kurz über die Arakkoa gesprochen. Ich muss allerdings zugeben, dass unsere... Interessen was sie betrifft deutlich auseinander gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10617] = { id = 10617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidenflügelkokons", description = "Die Seide der Kokons der Seidenflügel wird hier im Dorf für alle möglichen Zwecke eingesetzt. Wir können nie zu viele davon besorgen und haben.\n\nSobald sie beginnen sich zu verwandeln ist es schwer, die Kokons der Larven zu ernten.\n\nUnsere Krieger sind mit den Angriffen auf unser Dorf beschäftigt. Wenn Ihr sie für uns sammeln könntet, wäre das uns eine große Hilfe.", sourceObjective = "Besorgt 8 Seidenflügelkokons von Seidenflügellarven.\n\nTötet die Larven schnell, da sie sich sonst in Seidenflügel verwandeln und ihre Kokons zerstören.", progress = "Für die Ernte braucht man eine schnelle und ruhige Hand. Ich hoffe, Ihr habt Erfolg.", completion = "Diese Kokons sind von guter Qualität. Wie ich sehe, habt Ihr die Ernte im Griff.\n\nWir haben versucht, unsere eigenen Seidenflügellarven zu züchten, aber leider produzieren die kleineren nicht genug Seide, um unseren Bedarf zu decken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10618] = { id = 10618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die weichsten Flügel", description = "Seidenflügellarven zu jagen ist eine schwierige Aufgabe für unsere jungen Jäger. Aber auch wenn sie es nicht schaffen, die Kokons der Larven zu ernten, können wir noch die Flügel der geschlüpften Seidenflügel nutzen.\n\nIn der Tat sind die Flügel vielseitiger einsetzbar als die Kokons. Wir können nie zu viele davon haben.\n\nWenn Ihr da draußen seid, wäre es mir eine große Hilfe, wenn Ihr mir noch ein paar davon bringen würdet.", sourceObjective = "Beschafft Euch 12 schillernde Flügel.", progress = "Die Flügel sind sehr zerbrechlich, können aber in vielen unserer Kunstgegenstände als Dekoration dienen.", completion = "Vielen Dank, {name}. Wir werden sie schon früher benutzen, als ihr Euch vorstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10619] = { id = 10619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aschenzungen", description = "Der Aschenzungenstamm wird von allen Zerschlagenen gefürchtet. Er besteht aus den bösartigsten und blutrünstigsten Gestalten, die von Akama persönlich ausgewählt wurden. Sie sind so wild und rücksichtslos wie jeder Naga, Dämon oder Blutelf in Illidans Armee. Eine große Anzahl von ihnen wurde in den Ruinen von Baa'ri südwestlich von hier stationiert. Begebt Euch dorthin und dezimiert ihre Zahl, bevor sie die Gelegenheit haben, uns anzugreifen.", sourceObjective = "Verteidiger Aluumen möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ehre den Naaru, {name}. Ihr habt den Willen des Lichts ausgeführt und Illidans Anhänger vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10620] = { id = 10620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gratwirbelbedrohung", description = "Wir wurden angeheuert, um Toshley zu helfen, als er in die Scherbenwelt gezogen ist. Und seitdem sind wir hier auf Achse.\n\nEs sieht jedoch so aus, als hätten wir endlich ein paar Wurzeln geschlagen. All die verrückten Wissenschaftler und Ingenieure hier haben ihre Projekte am Laufen und wir Raunacken sind hier, um sie dabei zu beschützen.\n\nZurzeit könnten wir wirklich jemanden brauchen, der nach Norden in den Messergrat oder nach Osten zur Schuppenflügelbank geht und ihn von den Pirschern befreit. Das sind heimtückische Spinnen, die bei den Felsvorsprüngen leben und nichts ahnende Passanten anspringen.", sourceObjective = "Tötet 10 Gratwirbelpirscher.", completion = "Ziemlich gut für einen Grünschnabel. Es scheint, als gäbe es eine kleine Gruppe von Eierköpfen, die unbedingt die Astralen und ihre Technologie im Norden 'beobachten' möchten. Sie werden sich riesig freuen, dass Ihr ihnen den Weg freigeräumt habt.\n\nHier, nehmt ein paar hiervon. Wir haben nicht viele, aber vielleicht können sie Euch in der Zukunft nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10621] = { id = 10621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter des Illidaribanns", description = "Der Splitter scheint von einer größeren Waffe zu stammen. Ein bedrohliches Leuchten geht von den kantigen Runen, die in das Metall geätzt wurden, aus.\n\nEuch ist nicht klar, welche Aufgabe die Waffe hatte, aber sie ist nur schwer zu verkennen. Die meisten Mo'arg in der Feste der Legion scheinen Bruchstücke des Metalls, das Ihr in den Händen haltet, zu bearbeiten. Vielleicht kann einer der Waffenschmiede in der Wildhammerfeste Euch mehr darüber erzählen.", sourceObjective = "Bringt den Splitter des Illidaribanns zu Ordinn Donnerfaust in der Wildhammerfeste.", progress = "Was habt Ihr da?", completion = "<Ordinn nimmt Euch den Splitter der Waffe ab.>\n\nSo etwas habe schon seit langer Zeit nicht mehr gesehen. Die Waffe wurde aus einem sehr seltenen Erz geschmiedet, aber es handelt sich dabei nicht um eine gewöhnliche Klinge, {name}. Sie ist mit einer Magie erfüllt, die Dämonen töten soll. Wenn Ihr sie von der Legion habt, muss sie eine Art 'Geheimwaffe' sein, die sie gegen Illidan einsetzen wollen. Welch erstaunlicher Fund!", sourceObjectiveStatus = "unverified-source-field" }
quests[10622] = { id = 10622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Beweis der Treue", description = "Akama hat Eure Fortschritte sehr genau verfolgt, {name}.\n\nDie Aschenzungen, die Ihr in den Ruinen von Baa'ri erschlagen habt, zählen zu den bösartigsten Zerschlagenen unter uns. Akama selbst hat sie ausgewählt, um die Fassade gegenüber unseren Meistern der Illidari aufrechtzuerhalten. Doch die Todeshörigen wissen über Akamas eigentliche Pläne Bescheid.\n\nDoch eins nach dem anderen. Wir müssen wissen, dass Ihr nicht mit Illidan unter einer Decke steckt. Ein Satyr namens Zandras überwacht uns in Illidans Auftrag von den Zinnen der Gefängnismauer aus. Tötet ihn als Beweis Eurer Treue.", sourceObjective = "Tötet Zandras im Kerker des Wächters im Schattenmondtal und kehrt danach zu Sanoru zurück.", progress = "Habt ihr getan, worum ich Euch gebeten habe, {name}? Vertrauen ist in dieser Gegend Mangelware.", completion = "Sehr gut, {name}. Eure Gesinnung steht nun außer Frage. Ihr dürft jetzt zu Akama.", sourceObjectiveStatus = "unverified-source-field" }
quests[10623] = { id = 10623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter des Illidaribanns", description = "Der Splitter scheint von einer größeren Waffe zu stammen. Ein bedrohliches Leuchten geht von den kantigen Runen, die in das Metall geätzt wurden, aus.\n\nEuch ist nicht klar, welche Aufgabe die Waffe hatte, aber sie ist nur schwer zu verkennen. Die meisten Mo'arg in der Feste der Legion scheinen Bruchstücke des Metalls, das Ihr in den Händen haltet, zu bearbeiten. Vielleicht kann einer der Waffenschmiede in Schattenmond Euch mehr darüber erzählen.", sourceObjective = "Bringt den Splitter des Illidaribanns zu Grokom Totauge in Schattenmond.", progress = "Was habt Ihr da?", completion = "<Grokom nimmt Euch den Splitter der Waffe ab.>\n\nSo etwas habe schon seit langer Zeit nicht mehr gesehen. Die Waffe wurde aus einem sehr seltenen Erz geschmiedet, aber es handelt sich dabei nicht um eine gewöhnliche Klinge, {name}.\n\nDiese Runen erfüllen die Klinge mit der Macht, Dämonen zu vernichten. Wenn die Legion ihre eigenen Truppen mit Dämonen zerstörenden Waffen ausrüstet, muss ihr Hass auf Illidan unendlich groß sein. Das könnten wir zu unserem Vorteil ausnutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10624] = { id = 10624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Spukgeschichte", description = "Habt Ihr diesen eiskalten Hauch gespürt? Als ob Euch jemand die Hand auf die Schulter legte? Euer Verstand spielt Euch keine Streiche, {race}. Das Land wird heimgesucht. Geister streifen durch die Weiten und sind bis in alle Ewigkeit hier gefangen.\n\nWollt Ihr sie gerne sehen? Seid Ihr Euch sicher? Solche Dinge können ein Wesen verändern - und zwar nicht zum Besseren.\n\nNun gut, dann müsst Ihr mir etwas von der ewig brennenden Asche bringen, die Ihr in der Nähe der Teufelslavabecken im westlichen Schattenmondtal finden könnt. Überall in der Nähe der grünen Lava...", sourceObjective = "Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr ihr 15 Einheiten ewig brennende Asche bringt.", progress = "Was meint Ihr? Ich werde natürlich etwas aus der Asche herstellen.", completion = "Eure Welt wird sich bald ändern, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10625] = { id = 10625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterbrille", description = "Ich nenne sie 'Geisterbrille'. Ganz schön gewitzt, was? Wenn Ihr diese Brille aufzieht, könnt Ihr die Geister des Schattenmondtals sehen. \n\nBevor ich sie Euch gebe, müsst Ihr mir jedoch versprechen, uns dabei zu helfen, die Geister im Dorf zu dezimieren.\n\nNehmt die Brille und vernichtet alle Geister, die Ihr in Schattenmond herumspuken seht. Hoffentlich bewegt das die übrigen Geister, woanders hin zu gehen.", sourceObjective = "Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr 12 Zeloten des Schattenmondklans tötet.", progress = "Wenn Ihr Eure Brille verliert, kann ich Euch eine neue herstellen.", completion = "Blutschatten? T... Teron Blutschatten? Aber... Wie?\n\nWie kann Blutschatten denn hier sein? Das ist nicht möglich!\n\nDie Legende von Teron Blutschatten lässt sogar die Verlassenen vor Angst erzittern. Nach dem, was man hört, war Blutschatten ein Hexenmeister Gul'dans und sehr mächtig. Als Blutschatten von Orgrim Schicksalshammer erschlagen wurde, nahm Gul'dan die Seele des gefallenen Hexenmeisters und pflanzte sie in die zerschlagene Hülle eines gefallenen Ritters von Sturmwind. Und so wurde der erste Todesritter der Horde geboren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10626] = { id = 10626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschafft die Waffen", description = "Wenn ich mehr von diesem Material hätte, könnte ich eine Waffe schmieden, die für Euch geeignet ist.\n\nDie beiden Grubenlords in der Feste der Legion, Makazradon und Morgroron, besitzen bereits diese antidämonischen Waffen. Wir wissen nicht, wie viele davon die Legion herstellen möchte, aber wenn wir diese beiden Prototypen in die Finger bekommen, haben wir sicher genug Material für unser eigenes Projekt.\n\n<Ordinn grinst.>\n\nEs liegt ein wenig Befriedigung darin, die eigenen 'Geheimwaffen' der Legion gegen sie zu verwenden, findet Ihr nicht?", sourceObjective = "Ordinn Donnerfaust in der Wildhammerfeste möchte, dass Ihr ihm Makazradons Gleve und Morgrorons Gleve bringt.", progress = "Habt Ihr die Prototypen?", completion = "Sie sind perfekt. Jetzt wollen wir sie ein eine etwas praktischere Form bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10627] = { id = 10627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschafft die Waffen", description = "Wenn ich mehr von diesem Material hätte, könnte ich eine Waffe schmieden, die für Euch geeignet ist.\n\nDie beiden Grubenlords in der Feste der Legion, Makazradon und Morgroron, besitzen bereits diese antidämonischen Waffen. Wenn wir an diese beiden Waffen kommen könnten, hätten wir genug Material, um Eure und noch einige weitere herstellen zu können.\n\nIch kann es kaum abwarten, mit diesen Waffen in die Schlacht gegen den Feind zu ziehen. Das wird die Dämonen lehren, mit antidämonischer Magie herum zu spielen.", sourceObjective = "Grokom Totauge im Schattenmondtal möchte, dass Ihr ihm Makazradons Gleve und Morgrorons Gleve bringt.", progress = "Habt Ihr die Prototypen?", completion = "Sie sind perfekt. Jetzt wollen wir sie ein eine etwas praktischere Form bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10628] = { id = 10628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akama", description = "Ihr habt bewiesen, auf welcher Seite Ihr steht. Ich werde Euch das Versteck unseres Anführers verraten.\n\nFolgt den Gewölben hinter uns. Zu Eurer Rechten werdet Ihr einen unterirdischen Durchgang finden, der von stehendem Wasser verdeckt ist.\n\nIch muss Euch warnen, {name}. Ihr dürft niemandem von dem, was Ihr sehen werdet, erzählen.", sourceObjective = "Sprecht mit Akama in der verborgenen Kammer im Kerker des Wächters.", completion = "Seid gegrüßt, {name}. Wir haben viel zu besprechen.\n\nIch hoffe, Euer Wesen ist aufgeschlossen. Nicht viele Leute verstehen meine Entscheidungen. Nur meine engsten Mitarbeiter wissen von den bösen Omen, die ich sehe, und den Zeichen, auf die ich warte.\n\nAls ich mich mit Illidan zusammenschloss, geschah dies, weil ich vorausgesehen hatte, dass mein Volk sonst vernichtet würde. Ich habe geduldig auf die anderen Zeichen und Visionen gewartet... Velens Auszug... die Öffnung des dunklen Portals... und nun... Eure Ankunft.", sourceObjectiveStatus = "unverified-source-field" }
quests[10629] = { id = 10629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drecksarbeit", description = "Endlich habe ich meinen Schredder zum Laufen bekommen. Aber wie es scheint, habe ich die Schlüssel verloren. Ich halte ein Rudel Teufelshunde, die mein Lager bewachen. Sie machen ihre Sache nicht sehr gut und beißen mich gerne. Sie mögen auch gerne glänzende Dinge. Sie mögen sogar sehr gerne glänzende Dinge. Daher fürchte ich, dass einer der Teufelshunde meine Schredderschlüssel gefressen hat. Ich bezahle Euch, wenn Ihr mit meinem Teufelshund Gassi geht. Tötet ein paar Hölleneber und lasst ihn davon fressen. Wenn er fertig ist, wird er sein Geschäft machen. Durchsucht danach die Haufen nach den Schlüsseln.", sourceObjective = "Benutzt die Teufelshundepfeife, um einen teuflischen Wachhund zu rufen. Führt den teuflischen Wachhund Gassi und tötet ein paar Hölleneber. Durchsucht dann die Haufen des teuflischen Wachhunds nach den Schlüsseln. Wenn Ihr die Schlüssel gefunden habt, bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar.", progress = "Konntet Ihr meine Schlüssel finden? Ich bin mir sicher, dass einer der Hunde ihn gefressen hat. Wahrscheinlich ist es der, den ich Euch mitgegeben habe. Wahrscheinlich.", completion = "Ihr riecht ja fürchterlich! Aber Ihr habt meine Schlüssel gefunden. Vielen herzlichen Dank! Jetzt kann ich meinen Schredder in Betrieb nehmen und ein wenig Gold verdienen. Bald werde ich das Geld zusammen haben, um die Scherbenwelt zu verlassen. Ich weiß nicht, warum Ihr hier bleiben wollt. Ich hasse diesen Ort. Wärt Ihr nicht viel lieber wieder in Beutebucht?\n\nVielleicht um ein wenig zu Angeln?", sourceObjectiveStatus = "unverified-source-field" }
quests[10630] = { id = 10630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Thrallmar", description = "Ich bin fast wieder im Geschäft. Das Problem ist nur, dass diese Gan'arg sich in meiner Mine herumtreiben. Ich kann meine Peons dort nicht hineinschicken. Und auch wenn ich den Schredder repariert habe, möchte ich nicht riskieren, dass er im Kampf schon wieder kaputt geht. Der Anführer der Gan'arg haust tief unten in der Mine. Wenn Ihr ihn tötet, hauen die anderen Gan'arg vielleicht ab. Dann könnte ich endlich Geld verdienen und von hier weggehen.", sourceObjective = "Tötet Urga'zz und kehrt dann zu Großknecht Razelcraz in der Mine nordwestlich von Thrallmar zurück.", progress = "Ist er schon tot? Ich habe viel zu viel Angst, um hinzuschauen.", completion = "Diese Gan'arg werden sich jetzt sicher verziehen. Und in einer Woche bin ich wieder in Beutebucht. Ich kann es kaum abwarten, endlich wieder angeln gehen zu können. Es war ein Fehler in die Scherbenwelt zu kommen. Wenn Ihr meinen Rat hören wollt, macht Euch schleunigst auf den Weg zurück nach wo Ihr herkommt. Verbringt ein wenig Zeit im Schlingendorntal! Oder wenn Ihr mehr auf Abenteuer aus seid im Krater von Un'Goro. Hauptsache nicht hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[10632] = { id = 10632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne zeigen", description = "Es ist sehr nett von Euch, dass Ihr Toshley und den Wissenschaftlern hier helft. Ich kann mir jedoch nicht den Luxus erlauben, mich meinen 'persönlichen' Interessen hinzugeben.\n\nWenn Ihr hier etwas Besonderes sein wollt, dann tut, was ich sage. Ich brauche Waffen.\n\nUnsere Gewehre sind zwar im Fernkampf ganz nützlich, aber wenn uns diese Insekten zu nahe kommen, brauchen wir mächtige Nahkampfwaffen zur Verteidigung.\n\nDie Zähne der Dolchrachenschmetterschwänze im Messergrat im Norden geben tolle Vibroklingen ab. Treibt ein paar davon für mich auf!", sourceObjective = "Beschafft Euch 5 besonders scharfe Dolchrachenzähne.", progress = "Wie geht es mit dem Sammeln der Zähne voran?\n\nIch bin davon überzeugt, dass Ihr Eure Arbeit für uns gut machen werdet. Und während Ihr das tut, werden wir diesen Außenposten hier sichern.", completion = "Gute Arbeit, Junge. Der Schmerz ist gerechtfertigt, wenn auch nur einem meiner Soldaten durch Eure Bemühungen das Leben gerettet wird.\n\nIch bin der Meinung, dass auch Ihr von Eurem Blut und Euren Tränen profitieren solltet. Wir werden bald neue Waffen bekommen. Warum nehmt Ihr daher nicht einfach eine von meinen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10633] = { id = 10633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Blutschatten - Geschichte und Mythos", description = "Es gibt unzählige Geschichten über das Leben von Teron Blutschatten, aber manche sind eben nur Geschichten. Wir wissen nicht, was mit Blutschatten passiert ist, nachdem er nach Draenor zurückgekehrt war.\n\nMit Sicherheit wissen wir nur, dass er schon einmal gestorben ist.\n\nIch habe gehört, wie die Späher von einem alten Orcgeist sprachen, der beim Altar der Schatten haust. Er befindet sich weit im Südosten, hinter den Netherschwingenfeldern und jenseits des Netherschwingenpasses. Nehmt diese Geisterbrille und sucht diesen Orc. Er weiß sicher mehr über Blutschatten.", sourceObjective = "Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.\n\nWenn Ihr Eure Geisterbrille verlieren solltet, kann Euch Hildagard ein neues Paar herstellen.\n\nBereitgestellter Gegenstand:", completion = "Blutschatten? Diesen Namen habe ich schon seit ewigen Zeiten nicht mehr gehört!\n\nNach dem Zweiten Krieg kehrte Blutschatten mit seinen Todesrittern hierher zurück. Als er nicht mit der Schrecklichkeit seiner neuen Form zurechtkam und ohne die Hilfe seines geliebten Anführers, Gul'dan, hilflos war, nahm Blutschatten sich das Leben.\n\nIch weiß nichts davon, dass er nun als Geist in diesen Weiten herumwandeln soll. Aber vielleicht kann ich das mit Eurer Hilfe herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10634] = { id = 10634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellsicht: Blutschattens Rüstung", description = "Zu Lebzeiten war Blutschatten ein Scheusal, doch im Tod wurde sein Schrecken erst richtig entfesselt.\n\nIm Südosten findet Ihr die Netherschwingenscherbe. Einst war sie ein Teil des Festlands von Schattenmond, doch nun ist sie eine schwebende Insel.\n\nVhel'kur, der Nachkomme von Todesschwinge, nannte sie einst sein Zuhause, doch nun ist sie sein Grab. Er fliegt in endlosen Kreisen über der Insel, brodelnd vor Zorn über seine Niederlage gegen Blutschatten.\n\nWenn Ihr Blutschattens Rüstung beschaffen wollt, müsst Ihr Vhel'kur besiegen.", sourceObjective = "Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Rüstung besorgt.", progress = "Fliegt zur Netherschwingenscherbe und beschafft die Rüstung.", completion = "Ich muss alle Gegenstände besitzen, bevor ich Blutschattens Schicksal mit Hellsicht herausfinden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10635] = { id = 10635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellsicht: Blutschattens Umhang", description = "Er beging so manche Grausamkeit, aber keine war so kaltblütig wie das Abschlachten der Kleriker von Karabor.\n\nNachdem Gul'dans Horde die Draenei von Karabor besiegt hatte, wurden die überlebenden Kleriker verschleppt. Man sagte ihnen, dass sie als Kriegsgefangene in die Höllenfeuerzitadelle gebracht würden.\n\nDoch Blutschatten, der damals noch kein Todesritter war, brachte jeden einzelnen auf grausamste Weise um. Nun streichen sie voller Rachedurst vor dem Schwarzen Tempel umher.\n\nDie Kleriker von Karabor haben Blutschattens Umhang.", sourceObjective = "Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Umhang besorgt.", progress = "Ihr müsst die Geisterbrille benutzen, um die Geister von Schattenmond sehen zu können.", completion = "Wenn ich alle drei Gegenstände in meinem Besitz habe, kann ich mit Hellsicht versuchen, den Aufenthaltsort von Blutschatten zu bestimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10636] = { id = 10636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellsicht: Blutschattens Schlagstock", description = "Einer nach dem anderen kniete vor ihm nieder und brachte ihm seine Ehrerbietung dar. Blutschatten hob seine Sichel und schlug ihnen die Köpfe ab. Kurz nach diesem Massaker nahm er sich selbst das Leben.\n\nDoch er tat es nicht etwa aus Reue! Nein, Blutschatten wollte Unsterblichkeit! Von den Leichen der gefallenen Todesrittern erhoben sich die Geistritter von Karabor.\n\nJetzt reiten sie auf den Straßen um die Hand von Gul'dan herum und warten auf die Rückkehr ihres Meisters. Sie haben Blutschattens Schlagstock. Holt ihn Euch...", sourceObjective = "Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Schlagstock besorgt.", progress = "Ihr müsst die Geisterbrille benutzen, um die Geister von Schattenmond sehen zu können.", completion = "Nur mit allen drei Gegenständen zusammen kann ich die versuchen, die Geheimnisse, die Ihr zu lüften wünscht, hell zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10637] = { id = 10637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine notwendige Ablenkung", description = "Die Waffen sind echt, wie wir befürchtet haben. Illidan bildet in den Ruinen von Karabor Dämonenjäger aus. Das müssen wir verhindern.\n\nLasst Euch nicht von dem Namen täuschen, {name}. Sie werden ihre Macht genauso oft gegen uns einsetzen, wie gegen Dämonen.\n\nIhre Hexenmeister beschwören und unterwerfen Dämonen im Rahmen der Ausbildung der Initiierten. Ein Grubenlord namens Azaloth hat sich in der Ausbildung als zu mächtig erwiesen und wird nun unter Verschluss gehalten. Findet einen Weg, ihn frei zu lassen und auf seine Kerkermeister zu hetzen. Das sollte uns die nötige Zeit verschaffen.", sourceObjective = "Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Wollen wir hoffen, dass diese Ablenkung uns die Zeit verschafft, die wir brauchen, um alles herauszufinden, was wir über die Ausbildungsgelände von Karabor wissen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10638] = { id = 10638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NOT A QUEST", description = "Besucht Euren Lehrer in Silbermond.", sourceObjective = "Sucht <NAME> im <DISTRICT> von Silbermond auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10639] = { id = 10639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Teron Blutschatten...", description = "Jetzt, da wir Blutschattens Gegenstände beisammen haben, fehlt nur noch ein letztes Teil im Puzzle: ein Wirt.\n\n<Die Lippen des uralten Schattenmondgeistes verziehen sich zu einem bösartigen Grinsen.>\n\nIhr habt doch nicht etwa das Märchen geglaubt, das ich Euch aufgetischt habe? Der Altar der Schatten ist mein Gefängnis. Ohne Eure Hilfe wäre ich bis in alle Ewigkeit hier gefangen geblieben. Jetzt werde ich Euren Körper übernehmen und Ihr werdet die, die mich gefangen haben, vernichten und das Band für immer zerreißen. Wenn Ihr ablehnt, sind wir beide bis ans Ende der Zeit hier gefangen.\n\nTeron Blutschatten wird frei sein!", sourceObjective = "Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.\n\nWenn Ihr erfolgreich wart, meldet Euch bei Chefapothekerin Hildagard in Schattenmond.", completion = "Was habt Ihr getan? DUMMKOPF!\n\nIhr müsst dieses Unrecht wieder gutmachen. Schließlich war es Euer Fehler. Nehmt einen dieser Helme. Sie sind mit der Macht der ewig brennenden Asche, die Ihr mir gebracht habt, erfüllt. Viel wichtiger ist jedoch, dass Ihr damit die Geister Schattenmonds sehen könnt, auch Teron Blutschatten.\n\nWenn Ihr ihn jemals findet, vernichtet ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[10640] = { id = 10640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altruis", description = "In diesen Zeiten hört man nur noch selten von solchen, die den Weg des Dämonenjägers eingeschlagen haben. Und noch seltener findet man einen Dämonenjäger, der nicht im Bund mit Illidan steht.\n\nGerüchten zufolge soll ein solches Wesen hier in der Scherbenwelt leben. Es gibt einen Namen, der bei der Legion in Nagrand noch mehr gefürchtet sein soll, als eine ganze Armee von Verteidigern der Aldor, und das ist der Name Altruis.\n\nGeht in den Westen Nagrands und sucht ihn. Vielleicht ist er bereit, etwas mehr über diese neuen Ausbildungsgelände für Dämonenjäger zu erzählen.", sourceObjective = "Reist in den Westen Nagrands und sucht Altruis den Leider.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ihr habt einen langen Weg hinter Euch, Fremder. Ich bin überrascht, dass derjenige, der Euch zu mir geschickt hat, von mir gehört hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10641] = { id = 10641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Legion", description = "Die Brennende Legion hat immer und immer wieder bewiesen, wie leicht sie sterbliche Seelen verderben kann. Wenn ich Euch mit dem Wissen, nach dem Ihr strebt, ausstatten soll, muss ich erst Eure Gesinnung überprüfen.\n\nEine Dämonin namens Sathal schafft es schon eine ganze Weile, mir dank ihrer körperlosen Form zu entwischen.\n\nSie überwacht die Zornpriesterinnen, die ihren Willen in der Konstruktionsbasis: Gehenna ausführen. Tötet eine ihrer Dienerinnen und vergießt ihr Blut auf dem Boden. Diese Beleidigung sollte Sathal dazu bringen, sich für eine Zeitlang zu materialisieren. Tötet sie, solange Ihr die Möglichkeit dazu habt.", sourceObjective = "Altruis der Leidende möchte, dass Ihr das frisch gezapfte Blut einer Zornpriesterin der Konstruktionsbasis: Gehenna im Nethersturm besorgt. Schüttet es auf den Boden und tötet den Avatar von Sathal. Kehrt zu Altruis dem Leider zurück, wenn Ihr fertig seid.", completion = "Ihr habt beweisen, dass Ihr nicht von der Berührung der Legion verderbt wurde. Der Feind meines Feindes ist mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10642] = { id = 10642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritus ex machina", description = "Ich fürchte, dass diese Zwerge nicht verstehen, worauf sie da gebaut haben. Diese Gegend war einst der Ahnengrund der Schattenmondorcs. Ich spreche von Geistern, {race}.\n\nFast zwanzig Jahre lang ruhten sie unter der Wildhammerfeste, doch vor Kurzem hat etwas sie aufgerührt.\n\nReist jenseits der Tore von Wildhammer und untersucht die Becken und Flüsse der Teufelslava überall in dieser Gegend. In der Nähe der Lava findet Ihr ewig brennende Asche. Bringt mir diese Asche, damit ich etwas daraus herstellen kann, das uns helfen wird.", sourceObjective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr ihm 15 Proben ewig brennende Asche bringt.", progress = "Ja, es besteht eine Dualität... Ich kann es fühlen.", completion = "<Zorus beginnt damit, etwas aus den Aschenproben herzustellen.>\n\nEs ist vollbracht. Seht her, eine Geisterbrille!", sourceObjectiveStatus = "unverified-source-field" }
quests[10643] = { id = 10643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herolde des Schattenmondklans", description = "Seid Euch im Klaren, dass Zorus keinen Humor hat.\n\nGenug geredet. Zieht die Geisterbrille auf, damit Ihr die Orcgeister des Schattenmondklans, die sich in dieser Feste herumtreiben, sehen könnt. Habt keine Angst. Eigentlich sind wir die Eindringlinge hier. Dennoch müssen sie zerstört werden, denn ihre Zeit ist schon lange vorüber.\n\nZerstört die Herolde des Schattenmondklans, die in der Wildhammerfeste spuken, und kehrt dann zu mir zurück.", sourceObjective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 12 Herolde des Schattenmondklans tötet.", progress = "Wenn Ihr Eure Brille verliert, kann ich Euch eine neue herstellen.", completion = "Ihr sagt, Ihr habt die Geister zu Euch flüstern hören? Und sie sprachen über Teron Blutschatten?\n\n<Zorus schaudert.>\n\nJa... Ich kenne Teron Blutschatten. Oder besser gesagt kannte ihn. Er ist schon vor langer Zeit gestorben. Wovon können diese Geister wohl gesprochen haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[10644] = { id = 10644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teron Blutschatten - Geschichte und Mythos", description = "Es gibt unzählige Geschichten über das Leben von Teron Blutschatten, aber manche sind eben nur Geschichten. Wir wissen nicht, was mit Blutschatten passiert ist, nachdem er nach Draenor zurückgekehrt war.\n\nMit Sicherheit wissen wir nur, dass er schon einmal gestorben ist.\n\nIch habe gehört, wie die Späher von einem alten Orcgeist sprachen, der beim Altar der Schatten haust. Er befindet sich weit im Osten, hinter den Netherschwingenfeldern und jenseits des Netherschwingenpasses. Nehmt diese Geisterbrille und sucht diesen Orc. Er weiß sicher mehr über Blutschatten.", sourceObjective = "Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.\n\nWenn Ihr Eure Geisterbrille verlieren solltet, kann Euch Zorus der Richter eine neue herstellen.\n\nBereitgestellter Gegenstand:", completion = "Blutschatten? Diesen Namen habe ich schon seit ewigen Zeiten nicht mehr gehört!\n\nNach dem Zweiten Krieg kehrte Blutschatten mit seinen Todesrittern hierher zurück. Als er nicht mit der Schrecklichkeit seiner neuen Form zurechtkam und ohne die Hilfe seines geliebten Anführers, Gul'dan, hilflos war, nahm Blutschatten sich das Leben.\n\nIch weiß nichts davon, dass er nun als Geist in diesen Weiten herumwandeln soll. Aber vielleicht kann ich das mit Eurer Hilfe herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10645] = { id = 10645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Teron Blutschatten...", description = "Jetzt, da wir Blutschattens Gegenstände beisammen haben, fehlt nur noch ein letztes Teil im Puzzle: ein Wirt.\n\n<Die Lippen des uralten Schattenmondgeistes verziehen sich zu einem bösartigen Grinsen.>\n\nIhr habt doch nicht etwa das Märchen geglaubt, das ich Euch aufgetischt habe? Der Altar der Schatten ist mein Gefängnis. Ohne Eure Hilfe wäre ich bis in alle Ewigkeit hier gefangen geblieben. Jetzt werde ich Euren Körper übernehmen und Ihr werdet die, die mich gefangen haben, vernichten und das Band für immer zerreißen. Wenn Ihr ablehnt, sind wir beide bis ans Ende der Zeit hier gefangen.\n\nTeron Blutschatten wird frei sein!", sourceObjective = "Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.\n\nWenn Ihr erfolgreich wart, meldet Euch bei Zorus dem Richter in der Wildhammerfeste.", completion = "Was habt Ihr getan? DUMMKOPF!\n\nIhr müsst dieses Unrecht wieder gutmachen. Schließlich war es Euer Fehler. Nehmt einen dieser Helme. Sie sind mit der Macht der ewig brennenden Asche, die Ihr mir gebracht habt, erfüllt. Viel wichtiger ist jedoch, dass Ihr damit die Geister Schattenmonds sehen könnt, auch Teron Blutschatten.\n\nWenn Ihr ihn jemals findet, vernichtet ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[10646] = { id = 10646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidans Schüler", description = "Ihr habt bewiesen, dass Ihr guter Gesinnung seid, {name}. Bitte verzeiht mein Misstrauen, aber in dieser Welt sind die Dinge nicht so, wie sie scheinen.\n\nWenn Ihr bereit seid, werde ich Euch von Varedis erzählen.", sourceObjective = "Hört Euch Altruis' Geschichte an.", progress = "Varedis ist mächtig. Dennoch gibt es einen Weg, wie er besiegt werden kann.", completion = "Jetzt kennt Ihr die Geschichte. Bleibt nur noch eine Sache zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10647] = { id = 10647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Uvuros, Geißel von Schattenmond", description = "Gesucht - TOT:\n\nUvuros, Geißel des Schattenmondtals.\n\nAuf Befehl des Oberanführers Or'barokh ist die Teufelsbestie zu töten, wenn sie angetroffen wird. Ferner ist die Mähne als Beweis von dem toten Leib abzutrennen. Bringt die feurige Mähne der Bestie zu Kriegsrufer Sardon Treuschnitt, wenn Ihr erfolgreich wart.\n\nUvuros wurde zuletzt bei der Hand von Gul'dan im Herzen des Schattenmondtals, östlich von Schattenmond, gesehen.", sourceObjective = "Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Sardon Treuschnitt in Schattenmond im Schattenmondtal.", progress = "Wollt Ihr die Belohnung kassieren, Mann?", completion = "Ihr seid echt der Brüller, was? Gut gemacht! Und Ihr kriegt auch Eure Belohnung. Is' doch Ehrensache...", sourceObjectiveStatus = "unverified-source-field" }
quests[10648] = { id = 10648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Uvuros, Geißel von Schattenmond", description = "Gesucht- TOT:\n\nUvuros, Geißel des Schattenmondtals.\n\nAuf Befehl von Than Yoregar ist die Teufelsbestie zu töten, wenn sie angetroffen wird. Ferner ist die Mähne als Beweis von dem toten Leib abzutrennen. Bringt die feurige Mähne der Bestie zu Kriegsrufer Bierschnut, wenn Ihr erfolgreich wart.\n\nUvuros wurde zuletzt bei der Hand von Gul'dan im Herzen des Schattenmondtals, nordöstlich der Wildhammerfeste, gesehen.", sourceObjective = "Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Bierschnut in der Wildhammerfeste im Schattenmondtal.", progress = "Ich hoffe, Ihr habt etwas Großartiges getan, Bursche. Ansonsten macht Euch vom Acker!", completion = "Hier ist Eure Belohnung. Gebt nicht alles auf einmal aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10649] = { id = 10649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Buch der teuflischen Namen", description = "Ich finde es gut, dass Ihr vorhabt, Varedis und seine Anhänger aufzuhalten, aber Ihr habt keine Chance gegen ihn. Es sei denn, Ihr findet das Artefakt, das ihm seine Macht verliehen hat.\n\nDas Buch der teuflischen Namen soll sich im Besitz von Schwarzherz dem Hetzer befinden, der sich im Schattenlabyrinth von Auchindoun aufhält. Eure einzige Hoffnung, Varedis besiegen zu können, ruht auf diesem Buch.", sourceObjective = "Reist in das Schattenlabyrinth von Auchindoun und besorgt das Buch der teuflischen Namen von Schwarzherz dem Hetzer. Kehrt danach zu Altruis in Nagrand zurück.", progress = "Habt Ihr das Buch besorgt, {name}?", completion = "Ich konnte die Macht des Buches schon über Meilen hinweg spüren. Die Versuchung, es einfach zu behalten ist... sehr groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[10650] = { id = 10650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu den Aldor", description = "Dieses Buch... könnte meine Macht verzehnfachen... nein! Es würde meine Seele verderben, ich weiß es genau. Bringt es zurück zu denen, die Euch geschickt haben, {name}.\n\nIhr habt nun die Mittel, um Varedis aufzuhalten. Wartet, bis er sich mithilfe der Metamorphose in seiner dämonischen Form manifestiert. Genau in diesem Moment müsst Ihr das Buch in seiner Anwesenheit verbrennen. Nur so könnt Ihr ihn seiner Macht berauben.", sourceObjective = "Sprecht mit Exarch Onaala beim Altar der Sha'tar im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ihr bringt diese Abscheulichkeit eines Buches an einen heiligen Ort? Ich hoffe, dass Ihr dafür eine gute Erklärung habt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10651] = { id = 10651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varedis muss aufgehalten werden", description = "Wir müssen dieses abscheuliche Artefakt zerstören, jedoch nicht, bevor wir damit Varedis seiner Mächte beraubt haben.\n\nDas Ausbildungsgelände der Ruinen von Karabor muss für alle Zeiten geschlossen werden. Dazu müsst Ihr nicht nur Varedis töten, sondern auch seine drei Nachtelfenmeister, die ihn unterstützen: Alandien, Theras und Netharel.\n\nStellt eine geeignete Truppe zusammen und kehrt zu den Ruinen von Karabor zurück. Befolgt Altruis' Anweisungen, um Varedis zu besiegen. Ich hoffe für uns alle, dass sie funktionieren.", sourceObjective = "Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Exarch Onaala zurück.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Habt Ihr vollendet, worum ich Euch gebeten habe, {name}?", completion = "Ausgezeichnete Arbeit, {name}! Euer Sieg über Varedis ist ein entscheidender Schritt in unserem Krieg gegen Illidan.\n\nIhr habt Euch nicht nur den Aldor, sondern gegenüber der gesamten Scherbenwelt als würdig erwiesen. Bitte gestattet mir, die Überreste dieses schrecklichen Buchs zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10652] = { id = 10652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Linien", description = "Es wurden alle Vorkehrungen getroffen, um Euch zum Versteck der Spione zu bringen. Sucht mich einfach auf, wenn Ihr bereit seid, und wir werden Euch auf den Weg schicken.", sourceObjective = "Sprecht mit Veronia, wenn Ihr bereit seid, zur Manaschmiede Coruu aufzubrechen. Meldet Euch dort bei Caledis Morgenhell.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Willkommen, {class}. Bemüht Euch, unsere Position nicht zu verraten.\n\nWenn Kaels Spießgesellen uns entdecken, leben wir nicht mehr lange.", sourceObjectiveStatus = "unverified-source-field" }
quests[10653] = { id = 10653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Male des Sargeras", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Die hochrangigsten Mitglieder der Legion findet Ihr im Nethersturm und im Schattenmondtal.", sourceObjective = "Bringt 10 Male des Sargeras zu Adyen dem Lichtwächter in Shattrath.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, {name}?", completion = "Sich den Dämonen der Brennenden Legion und den wahnsinnigen Kultisten, die sie verehren, zu stellen ist keine geringe Tat, {name}. Ihr habt viel Hingabe und Mut bewiesen. Macht so weiter, und Euer Ruf bei den Aldor wird weiter steigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10654] = { id = 10654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Male des Sargeras", progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, {name}? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können.", completion = "Beweist Euch weiterhin als würdig, {name}. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden." }
quests[10655] = { id = 10655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Male des Sargeras", progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Ihr beweist Euch weiterhin als würdig, {name}. Besiegt die Feinde des Lichts, wo immer Ihr sie findet. Eure Taten sollen angemessen belohnt werden." }
quests[10656] = { id = 10656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Sonnenzorns", description = "Ihr wisst vielleicht, dass die Seher mit Kael'thas Armeen im Krieg stehen. Kael betrachtet uns als Bedrohung für seinen Einfluss über die Blutelfen und hat immer wieder versucht, uns zu vernichten.\n\nWenn Ihr uns in der Schlacht gegen Kael'thas helfen wollt, gibt es viele Ziele, die Ihr angreifen könnt. Kaels hochrangigste Soldaten tragen die Siegel des Sonnenzorns, der ihren Rang angibt. Ihr findet sie überall im Nethersturm und im Schattenmondtal.", sourceObjective = "Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Los, {name}. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ihr habt beeindruckende Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10657] = { id = 10657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie abblitzen!", description = "Wir sind nicht gerade sparsam mit dem Zephyriumkapazitorium umgegangen. Aber wie es scheint verfügen die Schlangen der Schuppenflügelbank im Osten über einen Blitzschlagatem und Blitzschlagdrüsen, die wir uns zu Nutze machen können.\n\nIch habe den Magnetsammler repolarisiert, sodass er die Blitzschläge absorbieren kann. Begebt Euch dorthin, schaltet es an und besorgt uns ein wenig billige Energie!", sourceObjective = "Benutzt die repolarisierte Magnetsphäre, um 25 Blitzschläge von Schuppenflügelschlangen abzufangen. Beschafft darüber hinaus 5 Blitzschlagdrüsen eines Schuppenflügels.", progress = "Der Trick dabei ist, die repolarisierte Magnetsphäre rechtzeitig abzuschalten, bevor Ihr gegrillt werdet.\n\nNatürlich müsst Ihr Euch dabei gut überlegen, wie vielen Schlangen Ihr gleichzeitig gegenübersteht.\n\nWo wir gerade davon sprechen, habt Ihr die Sphäre schon aufgeladen?", completion = "Jippieh, es hat geklappt! Ich war mir da ehrlich gesagt nicht so sicher... Ich habe eine Wahrscheinlichkeit von 23,72 Prozent berechnet, dass Ihr beim dritten Treffer implodiert.\n\n<Toshley grinst unschuldig.>\n\nJetzt wissen wir also, dass die Sphäre funktioniert. Es sollte also keine weiteren Probleme geben, den nötigen Saft für unser Zephyriumkapazitorium zu beschaffen. Natürlich nur, wenn ich noch mehr Freiwillige finde, die für mich dort hinaus gehen und sich brutzeln lassen.\n\nAber Ihr habt den Pionier für unsere Bemühungen gespielt und verdient eine Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[10658] = { id = 10658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Siegel des Sonnenzorns", progress = "Was habt Ihr in letzter Zeit für uns getan, {name}? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?", completion = "Ausgezeichnet! Das wird Kael'thas zeigen, dass unsere Macht nicht zu unterschätzen ist." }
quests[10659] = { id = 10659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Siegel des Sonnenzorns", progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, {name}. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Kaels Armee wird bald fallen." }
quests[10660] = { id = 10660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welch merkwürdige Wesen...", description = "Ich möchte mehr über die merkwürdigen Reptilien, die bei den Lavaströmen des Schattenmondtals umherstreifen, erfahren. Ich habe noch nie zuvor Tiere gesehen, die der sengenden Hitze geschmolzener Lava widerstehen konnten!\n\nAußerhalb von Schattenmond, wo der Boden aufgerissen ist und die Lava durch die Risse tritt, findet Ihr die Teufelsfeuerdimetrodonten. Tötet sie und bringt mir ihre Milzen. Mit ihrer Hilfe kann ich eine erste Analyse ihres Feuerwiderstands durchführen.\n\nBeginnt Eure Suche im Südosten.", sourceObjective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt.", progress = "Milzen! Ich brauche Milzen!", completion = "<Forscher Tiorus nimmt die Milzen an sich und beginnt seine Untersuchung.>\n\nDas dürfte eine Weile dauern. Nehmt dies als Bezahlung für Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10661] = { id = 10661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demilziös!", description = "Habt Ihr jemals von Essen gehört, dass sich selbst kocht und für immer warm bleibt? Das wäre traumhaft!\n\nAber vielleicht muss es kein Traum bleiben! Außerhalb der Feste, in der Nähe der Lavabecken und Lavaströme, gibt es Kreaturen, die in der glühenden Hitze gedeihen. Man nennt sie Teufelsfeuerdimetrodonten.\n\nDie Zwerge hier haben mir gesagt, dass sie die leckersten Milzen aller Zeiten haben. Und das Beste ist, dass sie schon vorgekocht sind! Bringt mir ein paar dieser Milzen! Ich werde Euch gut bezahlen.\n\nBeginnt direkt östlich von hier mit Eurer Suche.", sourceObjective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt.", progress = "Milzen! Ich brauche Milzen!", completion = "<Gnomus reißt die Milzen hungrig an sich.>\n\nHier ist die versprochene Bezahlung. Ich rufe Euch, wenn ich noch mehr Milzen brauche.\n\nSo lecker... Ich würde fast meinen 'demilziös'!", sourceObjectiveStatus = "unverified-source-field" }
quests[10662] = { id = 10662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wanderschmied", description = "<Ordinn betrachtet seinen Versuch, das Metall zu schmieden, und schüttelt den Kopf.>\n\nMeine Fertigkeiten reichen dazu nicht aus, aber das soll nicht heißen, dass die Waffe für Euch nicht neu geschmiedet werden kann.\n\nEin talentierter Schmied namens David Wayne begleitete die Söhne Lothars nach Draenor, doch er beschloss, die Expedition zu verlassen. Heute lebt er in einem kleinen Lager auf einer Halbinsel östlich des Postens der Feuerschwingen in den Wäldern von Terokkar. Bringt diese Barren zu ihm und schaut, ob Ihr ihm beim Schmieden der Waffe helfen könnt.", sourceObjective = "Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar.", progress = "Was führt Euch hierher, {class}? Ich bekomme nicht viel Besuch.", completion = "Ordinn hat Euch damit zu mir geschickt?\n\n<Der Schmied untersucht die Barren.>\n\nEr hatte Recht. Der Großteil der Magie ist verschwunden, aber ich kann noch immer Spuren davon in dem Metall spüren. Mit ein wenig Arbeit und ein paar 'ausgefallenen' Materialien kann ich Euch ein mächtiges antidämonisches Schwert aus diesem Metall schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10663] = { id = 10663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wanderschmied", description = "<Der Orc betrachtet seinen Versuch, das Metall zu schmieden, und schüttelt den Kopf.>\n\nMeine Fertigkeiten reichen dazu nicht aus, aber das soll nicht heißen, dass die Waffe für Euch nicht neu geschmiedet werden kann.\n\nEin talentierter Schmied namens David Wayne begleitete die Söhne Lothars nach Draenor, doch er beschloss, die Expedition zu verlassen. Heute lebt er in einem kleinen Lager auf einer Halbinsel östlich des Postens der Feuerschwingen in den Wäldern von Terokkar. Bringt diese Barren zu ihm und schaut, ob er Euch beim Schmieden der Waffe helfen kann.", sourceObjective = "Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar.", progress = "Was führt Euch hierher, {class}? Ich bekomme nicht viel Besuch.", completion = "Ordinn hat Euch damit zu mir geschickt?\n\n<Der Schmied untersucht die Barren.>\n\nEr hatte Recht. Der Großteil der Magie ist verschwunden, aber ich kann noch immer Spuren davon in dem Metall spüren. Mit ein wenig Arbeit und ein paar 'ausgefallenen' Materialien kann ich Euch ein mächtiges antidämonisches Schwert aus diesem Metall schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10664] = { id = 10664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusätzliche Materialien", description = "Das Metall, das Ihr mir gebracht habt, reicht zwar weitestgehend aus, um die Klinge des Schwerts zu schmieden, aber ich benötige noch viele andere Dinge, um die übrigen Teile der Waffe herzustellen.\n\nWollen wir mal schauen... Mir fehlen ein Adamantitrahmen, ein wenig schweres Knotenhautleder und ein Dämonenschutztotem. Geübte Kunsthandwerker sollten die ersten beiden Materialien herstellen können. Das dritte bekommt Ihr nur bei dem Reagenzienverkäufer Fantei im Unteren Viertel in Shattrath. Er hält sich bei den anderen Händlern auf.", sourceObjective = "David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm einen Adamantitrahmen, 4 Stück schweres Knotenhautleder und ein Dämonenschutztotem bringt.", progress = "Habt Ihr die Materialien?", completion = "<Der Schmied nimmt Euch die Materialien ab und nickt zufrieden.>\n\nDie werden reichen. Der Rest der Materialien, die ich benötige, wird jedoch nicht so leicht zu bekommen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10665] = { id = 10665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch von der Mechanar", description = "Um das Metall, das Ihr mir gebracht habt, zu bearbeiten, brauche ich große Hitze - viel mehr, als eine normale Schmiede herstellen kann.\n\nIch werde eine zusätzliche Hitzequelle für die Schmiede brauchen. Nur wenige Dinge in der Scherbenwelt können diese Art von Wärmeenergie liefern.\n\nIn der Mechanar der Festung der Stürme werden Manazellen, in denen eine unglaubliche Menge an Energie gespeichert ist, hergestellt. Sucht eine überladene Manazelle in den Stapeln um Mechanolord Kapazitus herum und bringt sie zu mir.", sourceObjective = "David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm eine überladene Manazelle bringt.", progress = "Konntet Ihr eine Manazelle aus der Mechanar schmuggeln?", completion = "Sie ist sogar noch mächtiger, als ich erwartet habe! Mit so viel Energie könnte ich ein Dutzend Klingen schmieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10666] = { id = 10666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encyclopaedia Daemonica", description = "Um die Verzauberungen auf der Klinge wiederherzustellen, müssen mehrere Zaubersprüche auf Dämonisch gesprochen werden.\n\nDas habe ich während meiner Ausbildung leider nicht gelernt, aber es führt kein Weg daran vorbei. Es gibt ein Buch, das Encyclopaedia Daemonica genannt wird. Darin könnte ich die meisten Worte, die ich brauche, finden. Leider ist das Buch im Besitz eines mächtigen Hexenmeisters des Schattenrats.\n\nTief im Schattenlabyrinth von Auchindoun wird es von Großmeister Vorpil bewacht. Tut, was immer Ihr tun müsst, um das Buch zu besorgen und bringt es zu mir.", sourceObjective = "Beschafft die Encyclopaedia Daemonica von Großmeister Vorpil und bringt sie zu David Wayne in Waynes Zuflucht.", progress = "Habt Ihr das Buch besorgt?", completion = "<David blättert die Seiten des Buchs durch und schaudert.>\n\nDas ist nichts, mit dem man spielen sollte, {name}. Sobald die Waffe fertig ist, werde ich es zerstören. Es gibt schon genug dämonische Macht in dieser Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10667] = { id = 10667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterweltlehm", description = "Der Rahmen, den Ihr mir gebracht habt, wird nicht ausreichen, um geschmolzenes Metall ohne zusätzliche Verstärkung zu halten. Der Rahmen kann mit einer seltenen Art von Erde abgekühlt und verdichtet werden, die ihm eine unnatürliche Stärke verleiht.\n\nDiese Erde ist als Unterweltlehm bekannt und gilt bei den Nagas als äußerst wertvoll. Nur wenige von ihnen besitzen etwas davon und ich kenne nur eine Naga in der Scherbenwelt, die sie benutzt: Wasserbeschwörerin Thespia, die in der Dampfkammer des Echsenkessels lebt.", sourceObjective = "Beschafft Euch ein Gefäß mit Unterweltlehm von Wasserbeschwörerin Thespia und bringt es zu David Wayne in Waynes Zuflucht.", progress = "Habt Ihr den Unterweltlehm bekommen?", completion = "Das sollte funktionieren. Ich hatte zwar auf etwas mehr gehofft, aber um ehrlich zu sein können wir uns glücklich schätzen, hier draußen überhaupt etwas davon in die Finger bekommen zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10668] = { id = 10668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Illidari", description = "Ich habe immer noch Respekt vor Illidan. Ohne ihn hätte ich nie meinen Pfad gefunden.\n\nDoch er ist nicht mehr der, der er einst war. Seine Seele wurde von Macht verderbt, sein Geist durch seine Niederlagen zerrissen. Ich habe geschworen, das, was aus ihm geworden ist, zu vernichten. Seine Schoßtierchen, die Illidari, sind genauso abscheulich wie die Dämonen der Brennenden Legion.\n\nAuch wenn sich sein Griff um die Scherbenwelt lockert, hat er immer noch weit reichenden Einfluss. Beweist mir, dass Ihr nicht auf seiner Seite steht, und tötet seinen Leutnant Lothros bei der Stätte der Illidari im Schattenmondtal.", sourceObjective = "Altruis der Leidende möchte, dass Ihr Lothros in der Stätte der Illidari im Schattenmondtal tötet.", completion = "Ihr gehört also nicht zu Illidan. Ihr seid einen Schritt näher daran, mein volles Vertrauen zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10669] = { id = 10669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen jede Chance", description = "Einige Dämonen schwören nur sich selbst die Treue. Ein wahrer Dämonenjäger sucht und vernichtet jedoch seine Beute ungeachtet ihrer Zugehörigkeit.\n\nDer Dämon Xeleth, ein Abtrünniger der Legion, wurde einst von den primitiven Sumpfkreaturen der Zangarmarschen als Gott verehrt. Als Draenor fast zerstört wurde, zog er sich in einen tiefen Schlaf unter dem Sumpflichtsee zurück. Findet das Portal beim See und steckt diesen Speer in den Boden.\n\nXeleth wird davon erwachen. Tötet ihn und beweist, dass Ihr ein Feind aller Dämonen seid.", sourceObjective = "Altruis der Leidende möchte, dass Ihr den magieerfüllten Silberspeer bei der Portalsicherung in der Nähe des Sumpflichtsees in den Zangarmarschen verwendet, um Xeleth zu wecken. Kehrt zu Altruis zurück, wenn Ihr den Dämon erlegt habt.", progress = "Ihr seid zurück. Ist Xeleth tot?", completion = "Gut gemacht, {name}. Er konnte sich also immer noch an den Tag erinnern, an dem ich den Speer in seinen Körper rammte? Das ist schon so lange her...", sourceObjectiveStatus = "unverified-source-field" }
quests[10670] = { id = 10670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träne der Erdenmutter", description = "Die Verzauberungen des Schwerts müssen mit einem mächtigen Fokus gebunden werden, wie zum Beispiel einem Edelstein. Nur wenige Steine können eine so starke Magie in sich aufnehmen, ohne zu zerbersten, doch ich kenne einen.\n\nDer Edelstein, den wir brauchen, wird Träne der Erdenmutter genannt. Er ist ein mächtiges Artefakt, das sich in den Händen seiner Schöpfer, der Oger, befindet. Kriegshetzer O'mrogg, der den Stein im Augenblick besitzt, hat viele mächtige Verbündete in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Seid also vorsichtig, wenn Ihr die Träne besorgt, {name}.", sourceObjective = "Besorgt die Träne der Erdenmutter von Kriegshetzer O'mrogg und bringt sie zu David Wayne in Waynes Zuflucht.", progress = "Konntet Ihr den Edelstein O'mroggs Klauen entreißen?", completion = "<David Wayne hält den Edelstein gegen das Licht und bewundert ihn.>\n\nEr ist absolut makellos und genau das, was wir brauchen. Ein fehlerhafter Edelstein würde den Träger der Waffe in Gefahr bringen und die Magie gegen ihn richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10671] = { id = 10671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Pfund Geschnetzeltes", description = "{name}, ich habe noch eine andere Aufgabe für Euch. Einer der Eierköpfe möchte die bösartigen Fleischbestien untersuchen, die sich bei Razaans Landeplatz nördlich des Messergrats aufhalten.\n\nGenauer gesagt wollen sie das Fleisch der Fleischbestien dort untersuchen.\n\n<Dina verzieht angewidert das Gesicht.>\n\nAber sie wollen sich die Hände natürlich nicht schmutzig machen. Und sie wollen nur das astralisierte Fleisch, das sicher nicht alle haben.\n\nMeiner Meinung nach kann man als Bettler nicht wählerisch sein, aber was sollen wir schon machen?", sourceObjective = "Beschafft Euch 5 Einheiten astralisiertes Fleisch.", progress = "Habt Ihr mein Geschnetzeltes schon? Wie, das findet Ihr nicht lustig?", completion = "Das sollte genügen. Es stinkt fürchterlich, oder?\n\nIch hoffe, dass es Eure Mühen wert war... Ich bin nur froh, dass ich das Zeug nicht selber sammeln musste!", sourceObjectiveStatus = "unverified-source-field" }
quests[10672] = { id = 10672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ergibt echt keinen Sinn...", description = "Wir müssen diese Wesen weiter untersuchen.\n\nWeit im Osten, in der Nähe des riesigen Lavastroms unter den Ruinen von Baa'ri, könnt Ihr Arkanosteuereinheiten finden. Diese Steuerungen wurden von einem Genie namens Gnomus hergestellt. Ihr einziger Zweck ist, Lava mithilfe eines mechanischen Skorpions zu erforschen.\n\nEr hat schon vor langer Zeit den Verstand verloren. Jetzt interessiert er sich nur dafür, das heißeste Essen in der Geschichte der Gnomheit zu futtern.\n\n<Tiorus rollt mit den Augen.>\n\nIch möchte, dass Ihr die Steuereinheit benutzt, um die Dimetrodonten des Lavastroms für unsere weiteren Studien zu markieren.", sourceObjective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr zu dem Lavastrom in der Nähe der Ruinen von Baa'ri reist und die Arkanosteuereinheit benutzt, um einen Arkanoskorp zu steuern. Schwimmt mit dem Arkanoskorp durch die Lava und markiert 8 große Teufelsfeuerdimetrodonten.", completion = "Wir haben keine Zeit zu verschwenden. Ich habe die markierten Dimetrodons beobachtet und herausgefunden, dass sie alle einem riesigen, nein, GIGANTISCHEN Dimetrodon namens Teufelsbuckel dem Großen unterstellt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[10673] = { id = 10673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsflosse der Große", description = "Gnomus weiß von dem riesigen Dimetrodon und will ihn aufessen! Er muss von irgendwoher erfahren haben, was ich durch sein Arkanoskorp gesehen habe. Nun, wir haben keine Zeit für Erklärungen. Er ist verrückt, und diese Verrücktheit könnte uns das kosten, was einem feuerfesten Anzug am Nächsten kommt.\n\nKehrt zurück zum Lavastrom in der Nähe von Baa'ri und findet Teufelsflosse den Großen. Bringt mir seinen Balg!\n\nVersucht nicht mit mir zu diskutieren, {name}. Darüber bin ich längst hinaus.", sourceObjective = "Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr Teufelsflosse den Großen tötet und Teufelsflosses Balg beschafft.", progress = "Kommt in die Gänge! Der Appetit dieses Gnoms kennt keine Grenzen!", completion = "Endlich bin ich vollkommen vor der Lava geschützt! Natürlich könnt auch Ihr etwas von dieser Technologie abhaben, {name}. Ihr habe es Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10674] = { id = 10674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht der Phantasie einfangen", description = "Die Astralen der Razaani bei Razaans Landeplatz im Norden spielen mit einer interessanten Technologie herum.\n\nIch bin mir sicher, dass sie nichts dagegen hätten, wenn Ihr diese Falle benutzen würdet, um ein paar ihrer kleinen, rosafarbenen, schwebenden Lichtkugeln zu sammeln. Wahrscheinlich sind sie ohnehin nur Dekoration.\n\nDie Falle hat eine ganz spezielle Eigenschaft. Wenn sie geöffnet wird, sollte sie eine der schwebenden Kugel anziehen. Natürlich wird sie auch die Aufmerksamkeit der Razaani auf Euch lenken.", sourceObjective = "Benutzt die Lichtfalle, um 15 Lichtkugeln der Razaani zu fangen.", progress = "Ich nehme an, dass Ihr die Lichtkugeln bei Razaans Landeplatz schon besorgt habt, wenn Ihr Zeit habt, hier mit mir zu plaudern. Ich würde sie wirklich gerne untersuchen und herausfinden, was die Astralen damit vorhaben.", completion = "He! Wartet mal!!\n\nDas sieht nicht gut aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[10675] = { id = 10675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gnom kennt kein Erbarmen!", description = "<Toshley erbleicht.>\n\nDiese Kugeln bestehen sowohl aus Netherenergie als auch aus Seelen! Sogar Gnomseelen sind dabei!\n\nWie können sie es wagen! Waren sie es vielleicht, die unsere Leute, die auf dem Weg nach Norden waren, getötet haben?!\n\n{name}, Ihr müsst dem ein Ende setzen und das geht nur, wenn Ihr ihren Anführer, Nexusprinz Razaan, ausschaltet.\n\nIhr müsst ihn jedoch aus seinem Versteck herauslocken. Ich schätze, dass Ihr das erreichen könnt, indem Ihr möglichst viele seiner Astralen der Razaani tötet.\n\nBringt mir seine Seelensammlung. Ich bin mir sicher, dass er eine hat.", sourceObjective = "Beschafft Euch die Seelensammlung.", progress = "Habt Ihr diesen Bastard Razaan schon erledigt?", completion = "Das geschieht ihm ganz Recht! Vielen Dank, dass Ihr dieser makaberen Mischung aus Magie und Technologie ein Ende bereitet habt.\n\nAls wahrer Held der Gnome überall auf dieser Welt, lasse ich Euch nun die höchste unserer Ehren zukommen... ein paar Stromwandler und Eure Wahl aus diesen Dingen hier!\n\nIch weiß, dass Ihr sie gut einsetzen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10676] = { id = 10676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bann der Illidari", description = "<David sammelt seine Schmiedeausrüstung zusammen.>\n\nIhr habt alles, was ich zum Schmieden einer antidämonischen Klinge brauche. Eure harte Arbeit und Euer Einsatz soll belohnt werden.\n\nEs ist an der Zeit, die Klinge zu schmieden.", sourceObjective = "Wartet, bis David Wayne das Schwert für Euch fertig geschmiedet hat.", completion = "<David wischt sich den Schweiß von der Braue.>\n\nDer größte Teil der Arbeit ist getan. Um die Magie jedoch zum Leben zu erwecken, muss das Schwert erst gehärtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10677] = { id = 10677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zweite Gang...", description = "Ich erinnere mich, dass ich östlich der Hand von Gul'dan, in der Nähe der Lavaströme um die Ruinen von Baa'ri herum größere Dimetrodonten gesehen habe. Ich möchte, dass Ihr mir einen überentwickelten Teufelsfeuermuskelmagen von den Kreaturen in dieser Gegend besorgt. Ihr müsst wahrscheinlich mehrere erlegen, bevor Ihr einen solchen Muskelmagen findet. Bleibt immer schön am Ball! Einer von ihnen hat meine nächste Mahlzeit bei sich!", sourceObjective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr einen überentwickelten Teufelsfeuermuskelmagen besorgt.", progress = "Tagesmenü: Muskelmagen.", completion = "Das ist fantastisch! Aber ich habe gerade unglaubliche Nachrichten erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10678] = { id = 10678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Hauptgericht!", description = "Ich werde mich kurz fassen. Ich arbeitete einst mit einem Blutelfen namens Tiorus zusammen. Meine Partnerschaft zu Tiorus brach ab, als ich mich dem Leben als Gourmet zugewandt habe. Er beschloss, unsere Forschungen mit MEINEN Erfindungen auf eigene Faust weiterzuführen. Wie auch immer, er hat ein paar seiner Hordendummköpfe meine Arkanoskorpfühler bei den Ruinen von Baa'ri benutzen lassen und dabei den Vater aller Dimetrodonten entdeckt!\n\nIch möchte, dass Ihr vor ihm dorthin gelangt und das Dimetrodon Teufelsflosse tötet. Bringt mir seinen Balg!\n\nBeeilt Euch!", sourceObjective = "Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr Teufelsflosses Balg besorgt.", progress = "Tagesmenü: Teufelsbuckels Balg", completion = "Ich brauche jetzt etwas Zeit für mich, {name}. Vielen Dank für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[10679] = { id = 10679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe härten", description = "Die Klinge ist fast fertig!\n\nMan kann beinahe schon fühlen, wie die Magie im Stahl zusammenfließt. Aber eine Sache ist noch zu tun.\n\nIhr müsst die geschmiedete Klinge zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan im Schattenmondtal bringen und das Schwert in den Lavabecken härten. Kehrt zurück, wenn Ihr den Stahl gehärtet habt.", sourceObjective = "Reist zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan und härtet die geschmiedete Klinge des Illidaribanns in den Lavabecken. Kehrt dann mit der gehärteten Klinge des Illidaribanns zu David Wayne in Waynes Zuflucht zurück.", progress = "Habt Ihr das Schwert in der Lava der Hand von Gul'dan gehärtet?", completion = "Gut gemacht!\n\n<Der Schmied untersucht die Klinge sehr genau.>\n\nIch würde sagen, dass sie deutlich besser ist, als die grobe Waffe der Legion, mit der wir angefangen haben. Diese Klinge wird nicht nur die Dämonen der Illidari erschlagen, sondern auch die Diener der Legion vernichten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10680] = { id = 10680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand von Gul'dan", description = "Die Elemente brauchen Eure Hilfe, {race}! Das Schattenmondtal wurde von unaussprechlichen Schrecken heimgesucht. Bis zum heutigen Tag leiden die Geister. Viele sind wütend und wollen nicht mit dem Irdenen Ring in Verbindung treten.\n\nHelft dieser Welt zu heilen, Freund.\n\nNordöstlich der Wildhammerfeste gibt es einen Ort, der als der Altar der Verdammnis bekannt ist. Begebt Euch dorthin und sprecht mit Erdheiler Torlok.", sourceObjective = "Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal.", completion = "Es ist gut, dass Ihr gekommen seid, {race}. Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10681] = { id = 10681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand von Gul'dan", description = "Die Elemente brauchen Eure Hilfe, {race}! Das Schattenmondtal wurde von unaussprechlichen Schrecken heimgesucht. Bis zum heutigen Tag leiden die Geister. Viele sind wütend und wollen nicht mit dem Irdenen Ring in Verbindung treten.\n\nHelft dieser Welt zu heilen, Freund.\n\nSüdöstlich von Schattenmond, im Herzen des Schattenmondtals, gibt es einen Ort, der als der Altar der Verdammnis bekannt ist. Begebt Euch dorthin und sprecht mit Erdheiler Torlok.", sourceObjective = "Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal.", completion = "Es ist gut, dass Ihr gekommen seid, {race}. Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[10682] = { id = 10682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu verhandeln...", description = "Als wir hier im Ruuanwald ankamen, hielten sich die Wyrmkultisten nur im Pechschwingenkoven, der sich jenseits des Tunnels im Westen befindet, auf. Doch nun rücken sie immer näher an uns heran.\n\nIhr müsst den Aufseher der Wyrmkultisten finden. Es ist bekannt, dass er regelmäßige Kontrollgänge zwischen den verschiedenen Lagern hier im Ruuanwald durchführt.\n\nVerhandelt mit ihm. Lasst ihn wissen, dass wir kompromissbereit sind, jedoch auf keinen Fall zu dem Abschlachten der Wildtiere oder dem Fällen von Bäumen beitragen oder es tolerieren werden.", sourceObjective = "Verhandelt mit Aufseher Nuaar.", completion = "WAS?! Sie haben Euch fortgeschickt und unser Angebot ausgeschlagen?\n\nDas ist empörend! Wir sind in Frieden zu ihnen gekommen und sie schicken Euch weg, ohne auch nur zu versuchen, einen Kompromiss zu finden?\n\nNun, das wird Folgen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[10683] = { id = 10683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrifttafeln von Baa'ri", description = "Die Zerschlagenen der Aschenzungen wurden von Illidan beauftragt, in den Ruinen von Baa'ri weit im Norden Ausgrabungen durchzuführen. Sicher suchen sie nach Draeneiartefakten. Baa'ri verfügte über viele Relikte von Baa'ri, bevor Gul'dan die Stadt unter einer vulkanischen Explosion begrub. Wir müssen diese Chance nutzen, um an die Schrifttafeln von Baa'ri zu kommen. Dieser alte Text soll angeblich die Geheimnisse des Tempels von Karabor, der heute als Schwarzer Tempel bekannt ist, enthalten.", sourceObjective = "Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Schrifttafeln schon gefunden, {name}?", completion = "Die Schrifttafeln von Baa'ri! Ja, die wird uns sehr wichtige Informationen liefern.", sourceObjectiveStatus = "unverified-source-field" }
quests[10684] = { id = 10684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronu der Älteste", description = "Laut den Schrifttafeln wurde in Baa'ri ein Artefakt, das als Medaillon der heiligen Stimme bekannt ist, aufbewahrt. Nur die höchstrangigen Draeneipriester durften es tragen, da es uneingeschränkten Zugang zum Tempel von Karabor bot.\n\nWir müssen herausfinden, ob die Aschenzungen das Medaillon schon gefunden haben. Seine Macht wäre uns eine große Hilfe im Kampf gegen Illidan.\n\nAkamas Leutnant in Baa'ri, Oronu der Älteste, erhält täglich schriftliche Befehle von Akama. Besorgt sie Euch und bringt sie mir.", sourceObjective = "Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Gibt es schon Neuigkeiten, {name}? Wir haben nicht viel Zeit.", completion = "Akamas Handschrift... wollen wir mal sehen, was wir daraus erfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10685] = { id = 10685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderber der Aschenzungen", description = "Laut Akamas Brief wurden vier Teile des Medaillons ausgegraben und den Verderbern der Aschenzungen übergeben. Diese gefürchteten Zerschlagenen waren einst mächtige Schamanen, die nun die Elemente schänden, die sie einst verehrten.\n\nHaalum, der Verderber der Luft, befindet sich am Netherschwingenpass. Eykenen und Uylaru, die Verderber der Erde und des Feuers, wurden zuletzt bei den Teufelsgruben in der Nähe der Hand des Gul'dan gesehen. Lakaan, der Verderber des Wassers, soll sich in der Nähe der Echsennarbe aufhalten.\n\nFindet sie und besorgt Euch die Medaillonfragmente von ihnen.", sourceObjective = "Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal zurück.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die vier Fragmente des Medaillons, {name}?", completion = "Ja! Die vier Fragmente des Medaillons. Und nun setzt sie zusammen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10686] = { id = 10686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kerker des Wächters", description = "Die Fragmente, die Ihr besorgt habt, sind nur eine Hälfte des Amuletts. Der Anführer der Aschenzungen, Akama, muss die andere Hälfte haben.\n\nIch wage es fast nicht, Euch darum zu bitten, da Akama sowohl böse als auch gerissen ist.\n\nEr und die Todeshörigen der Aschenzungen - die bösartigsten und grausamsten der Zerschlagenen -  sollen irgendwo im Kerker des Wächters eine Folterkammer betreiben.\n\nIch möchte, dass Ihr dieses gefürchtete Gefängnis findet und Akamas Aufenthaltsort bestimmt. Sein Stellvertreter vor Ort ist ein Zerschlagener namens Sanoru. Befragt ihn, wenn Ihr müsst.", sourceObjective = "Arkanist Thelis möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru über Akamas Aufenthaltsort befragt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Wir haben Euch erwartet, {name}. Akama sagte, dass Ihr früher oder später kommen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10687] = { id = 10687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildungsgelände von Karabor", description = "Unsere Späher haben uns von einem massiven Zufluss von Blutelfenrekruten des Sonnenzorns in den Ruinen von Karabor berichtet. Normalerweise würden wir darin eine rein militärische Bedrohung sehen, doch wir glauben, dass hier noch mehr im Argen liegt.\n\nDie Beschreibungen ihrer Kleidung und ihres Kampfstils klingen verdächtig nach Illidan selbst. Ich will mich nicht ohne handfeste Beweise beunruhigen, daher möchte ich Euch bitten, dorthin zu gehen und mir ihre Waffen zu bringen. Dann werden wir sehen, ob meine Befürchtungen unbegründet sind oder nicht.", sourceObjective = "Larissa Sonnenhieb beim Sanktum der Sterne möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, nordöstlich des Sanktums der Sterne, beschafft.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Aufgabe, mit der ich Euch betraut habe, erfüllt, {name}?", completion = "Wollen wir uns diese Waffen einmal genauer ansehen, {name}. Hmmm... das ist ziemlich beunruhigend.", sourceObjectiveStatus = "unverified-source-field" }
quests[10688] = { id = 10688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine notwendige Ablenkung", description = "Die Waffen sind echt, wie wir befürchtet haben. Illidan bildet in den Ruinen von Karabor Dämonenjäger aus. Das müssen wir verhindern.\n\nLasst Euch nicht von dem Namen täuschen, {name}. Sie werden ihre Macht genauso oft gegen uns einsetzen, wie gegen Dämonen.\n\nIhre Hexenmeister beschwören und unterwerfen Dämonen im Rahmen der Ausbildung der Initiierten. Ein Grubenlord namens Azaloth hat sich in der Ausbildung als zu mächtig erwiesen und wird nun unter Verschluss gehalten. Findet einen Weg, ihn frei zu lassen und auf seine Kerkermeister zu hetzen. Das sollte uns die nötige Zeit verschaffen.", sourceObjective = "Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Das sollte uns genug Zeit verschaffen... hoffentlich reicht sie aus, um weitere Informationen zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[10689] = { id = 10689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altruis", description = "Heutzutage trifft man nur noch selten auf Dämonenjäger. Ihr eigenes Volk begegnet ihnen mit Argwohn. Und noch seltener findet man einen Dämonenjäger, der nicht im Bund mit Illidan steht.\n\nGerüchten zufolge soll ein solches Wesen hier in der Scherbenwelt leben. Sein Name ist Altruis. Er hasst alle Dämonen mit Leidenschaft und wird uns helfen, wenn Ihr ihn davon überzeugen könnt, dass wir auf seiner Seite stehen.\n\nGeht in den Westen Nagrands und sucht ihn. Vielleicht ist er bereit, etwas mehr über diese neuen Ausbildungsgelände für Dämonenjäger zu erzählen.", sourceObjective = "Reist in den Westen Nagrands und sucht Altruis den Leider.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ihr habt einen langen Weg hinter Euch, Fremder. Ich bin überrascht, dass derjenige, der Euch zu mir geschickt hat, von mir gehört hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10690] = { id = 10690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhlenmutter", description = "GESUCHT!\n\nRema, die Mutter und wichtigste Verteidigerin des Zackengrats südlich der Donnerfeste.\n\nIhr findet sie, indem Ihr das Dorf Richtung Osten verlasst und die Brücke über die Blutschlägerklamm überquert. Sie versteckt sich im Tunnel am südlichen Ende des Grats.\n\nKehrt mit den Nachrichten über Ihr Ableben zu Kommandant Himmelsschatten in Sylvanaar zurück.", sourceObjective = "Tötet Rema.", progress = "Was kann ich heute für Euch tun?", completion = "Unglaublich. Habt Ihr Rema ganz alleine getötet?\n\nSo wie Ihr ausseht, glaube ich das. Wisst Ihr, wir sind auf der Suche nach einem starken {class} wie Ihr es seid, um uns hier ein wenig zu helfen. Besonders bei den ständigen Problemen, die wir mit den Ogern haben, könnten wir Euch brauchen. Setzt Euch mit mir in Verbindung, wenn Ihr Interesse habt.\n\nDas Kopfgeld, das auf dem Anschlag versprochen wurde, habt Ihr Euch jedenfalls verdient.\n\nBitte, wählt Euch etwas aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[10691] = { id = 10691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu den Sehern", description = "Dieses Buch... könnte meine Macht verzehnfachen... Nein! Es würde meine Seele verderben, ich weiß es genau. Bringt es zurück zu denen, die Euch hierher geschickt haben, {name}.\n\nIhr habt nun die Mittel, um Varedis aufzuhalten. Wartet, bis er sich mithilfe der Metamorphose in seiner dämonischen Form manifestiert. Genau in diesem Moment müsst Ihr das Buch in seiner Anwesenheit verbrennen. Nur so könnt Ihr ihn seiner Macht berauben.", sourceObjective = "Sprecht mit Larissa Sonnenhieb beim Sanktum der Sterne im Schattenmondtal.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Viele würden für das Buch, das Ihr bei Euch tragt, einen hohen Preis bezahlen. Es ist eine Schande, dass wir es zerstören müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10692] = { id = 10692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varedis muss aufgehalten werden", description = "Wir müssen dieses abscheuliche Artefakt zerstören, jedoch nicht, bevor wir damit Varedis seiner Mächte beraubt haben.\n\nWir müssen diese Akademie von Illidanimitatoren auslöschen. Dazu müsst Ihr nicht nur Varedis töten, sondern auch seine drei Nachtelfenmeister, die ihn unterstützen: Alandien, Theras und Netharel.\n\nStellt eine geeignete Truppe zusammen und kehrt zu den Ruinen von Karabor zurück. Befolgt Altruis' Anweisungen, um Varedis zu besiegen. Ich hoffe für uns alle, dass sie funktionieren. Wenn nicht... war schön, Euch kennengelernt zu haben.", sourceObjective = "Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Larissa Sonnenhieb zurück.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Habt Ihr die Aufgabe, mit der ich Euch betraut habe, erfüllt, {name}?", completion = "Ausgezeichnete Arbeit, {name}! Euer Sieg über Varedis ist ein entscheidender Schritt in unserem Krieg gegen Illidan.\n\nNach dieser Tat wird euer Name sicher die Runde machen.\n\nBitte erlaubt mir, die Überreste des Buchs der teuflischen Namen an mich zu nehmen. Ich werde dafür sorgen, dass es ordnungsgemäß... entsorgt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10693] = { id = 10693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Belobigungsabzeichen" }
