quests[10700] = { id = 10700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen" }
quests[10701] = { id = 10701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherbrock zerschmettern", description = "An alle, denen an einer rechtzeitigen Fertigstellung der X-52 Netherrakete gelegen ist:\n\nDer König der hiesigen Bergriesen, Netherbrock, terrorisiert die Schwindenden Weiten! Er behindert Unternehmungen am gesamten südlichen Rand der Insel!\n\nSchließt Euch mit ein paar Freunden zusammen und erledigt ihn! Kehrt dann zu mir hier in Area 52 zurück.\n\nRaketenchef Doppeldecker", sourceObjective = "Tötet Netherbrock und meldet Euch danach bei Raketenchef Doppeldecker in Area 52 im Nethersturm.", completion = "Oh! Oh... Ihr habt Netherbrock erledigt. Das sind gute Nachrichten!\n\nJetzt, da dieser lästige Bergriese von der Bildfläche verschwunden ist, können wir die Rohstoffe der schwindenden Weiten leichter ausbeut... äh, verwalten.\n\nIch bin froh, dass diese armen, unschuldigen Elementare da unten jetzt nicht mehr von ihm zerquetscht werden.\n\nWie kann ich Euch je dafür entlohnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10702] = { id = 10702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Routinearbeiten", description = "Alle Streitkräfte der Horde in dieser Gegend sind damit beschäftigt, die Angriffe der Brennenden Legion abzuwehren. Wir haben daher niemanden, der uns die kleinen Routinearbeiten abnimmt.\n\nUnsere Versorgungskarawanen werden regelmäßig von den Wildtieren der Region bedroht. Wir können uns keine 15 Fuß von der Straße entfernen, ohne einer Schimäre, einem Teufelseber oder einem abnormal großen Skorpion in die Fänge zu laufen.\n\nGeht dort hinaus und befreit das Schattenmondtal von seinen sadistischen Wildtieren! Erschlagt sie einfach alle!", sourceObjective = "Oberanführer Or'barokh in Schattenmond im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.\n\nDazu gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig.", completion = "Fantastisch! Wenn ich noch mehr Routinearbeiten zu erledigen habe, komme ich auf Euch zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[10703] = { id = 10703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zieht Eure Knieschoner an...", description = "Es ist an der Zeit, sich im Schlamm zu wälzen und dreckig zu machen. Was habt Ihr denn erwartet? Man muss schließlich laufen lernen, bevor man krabbelt, oder nich'? Ähem, anders 'rum...\n\nEgal, wir haben jedenfalls alle Hände voll mit dem Müll zu tun, mit dem uns die Legion bewirft. Daher wird Euch die Ehre zuteil, die durchgeknallten Wildtiere des Schattenmondtals zu erlegen.\n\nSchnappt Euch Schwert, Stab oder was auch immer Euch glücklich macht, und tötet so viele Wildtiere, wie Ihr könnt. So halten wir den Weg für unsere Versorgungskarawanen frei.", sourceObjective = "Than Yoregar in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.\n\nDarunter gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig.", progress = "Kehrt zu mir zurück, wenn unsere Karawanen sicher durch die Wildnis kommen!", completion = "Jap, gute Arbeit! Hier habt Ihr ein wenig Bares für Eure Mühen. Wenn ich noch mehr Drecksarbeit zu erledigen habe, weiß ich ja, wen ich rufen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[10704] = { id = 10704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man in Arkatraz einbricht", description = "In dem Kristall von Ata'mal, den Ihr uns gebracht habt, war eine Nachricht versteckt. Nexusprinz Haramad hat uns dadurch wichtige Informationen für unsere Vorgehensweise gegen die Festung der Stürme zukommen lassen.\n\nEr berichtet, dass es einen zweiteiligen Schlüssel gibt, mit dem man den Satellit Arkatraz der Festung aufschließen kann.\n\nDie eine Hälfte des Schlüssels befindet sich im Besitz eines Urtums namens Warpzweig in der Botanika. Der zweite Teil wird von Panthaleon dem Kalkulator in der Mechanar bewacht.\n\nBringt mir beide Fragmente, damit ich den Schlüssel zur Arkatraz zusammensetzen kann.", sourceObjective = "A'dal bittet Euch, das obere und das untere Fragment des Schlüssels zur Arkatraz zu besorgen. Bringt beide Fragmente zu ihm zurück, damit er sie für Euch zum Schlüssel zur Arkatraz zusammenfügen kann.", progress = "<A'dals Stimme summt melodisch in Eurem Geist.>\n\nIhr seid zurück. Habt Ihr die beiden Fragmente des Schlüssels zur Arkatraz bei Euch?", completion = "Ich bin beeindruckt, {name}, auch wenn ich von dem Helden, der den Kristall von Ata'mal zurückgebracht hat, nichts anderes erwartet habe.\n\nGebt mir die Fragmente, damit ich sie zu ihrer endgültigen Form zusammenfügen kann. Dann werdet Ihr Zugang zur Arkatraz haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[10705] = { id = 10705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seher Udalo", description = "Ich hoffe, Ihr seid nicht schockiert, wenn ich Euch verrate, dass die Teile des Medaillons von Karabor, die Ihr von meinen Dienern beschafft habt, nichts als Nachbauten sind.\n\n<Akama zeigt Euch ein identisches Medaillon, das auf seiner Handfläche liegt.>\n\nMeine Todeshörigen haben dieses Geheimnis so lange wie möglich von Illidan bewahrt. Dennoch fehlt uns noch das letzte Stück.\n\nSeher Udalo erschien mir in meinen Träumen und sagte mir, dass er das letzte Stück gefunden habe. Er wird jedoch von Kael'thas auf der Arkatraz in der Festung der Stürme gefangen gehalten. Sucht ihn und findet heraus, was er weiß.", sourceObjective = "Sucht Seher Udalo in der Arkatraz in der Festung der Stürme.", completion = "Der Seher der Aschenzungen ist schon lange tot. Als Ihr Euch über seinen Körper beugt, erkennt Ihr, dass auf dem Boden etwas geschrieben steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10706] = { id = 10706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mysteriöses Omen", description = "Bevor er starb, hat Udalo noch ein einzelnes Wort auf den Boden unter sich geschrieben. Die Schrift ist kaum lesbar, aber Ihr erkennt das Wort 'Ata'mal'.\n\nVielleicht versteht Akama die Nachricht seines Bruders.", sourceObjective = "Kehrt zu Akama im Kerker des Wächters im Schattenmondtal zurück.", completion = "Ja... natürlich! Jetzt wird alles klar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10707] = { id = 10707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse von Ata'mal", description = "Wir haben herausgefunden, dass die Höllenorcs unter Illidans Kommando bei der Terrasse von Ata'mal einen Kristall von Ata'mal, der als Herz des Zorns bekannt ist, aufbewahren. Sie verschleiern seine Präsenz mit einer dunklen Magie, um ihn vor den Sha'tar zu verstecken.\n\nKämpft Euch zur Terrasse von Ata'mal außerhalb des Schwarzen Tempels durch und blickt zum Himmel. Schattenfürst Todesklage kreist außerhalb Eurer Reichweite um die Terrasse herum. Ihr müsst ihn und seine Hexenmeister töten, bevor Ihr an den Kristall kommt.\n\nEs wird nicht einfach werden, {name}. Ich wünsche Euch Glück.", sourceObjective = "Begebt Euch zur Spitze der Terrasse von Ata'mal im Schattenmondtal und beschafft das Herz des Zorns. Kehrt danach zu Akama beim Kerker des Wächters im Schattenmondtal zurück.", progress = "Ihr seid zurück, {name}.", completion = "Der Kristall! Seine Macht... in meinen Händen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10708] = { id = 10708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akamas Versprechen", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, {name}. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.", sourceObjective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[10709] = { id = 10709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenführung", description = "Ihr kommt also aus der Welt jenseits des Portals? Und Ihr kennt Rexxar. Oh ja, auch ich kenne ihn sehr gut.\n\nEr ist mein Sohn.\n\nAber er hat seine Entscheidung vor langer Zeit getroffen. Er ist keiner von uns und hier nicht willkommen. Wir haben genug Probleme mit den Ogern der Totschläger.\n\nIhr müsst eines wissen: ein Halbblut zu sein macht niemanden zu einem Mok'Nathal.", sourceObjective = "Sprecht mit Rexxar in der Donnerfeste im Schergrat.", completion = "Mein Vater ist also tatsächlich am Leben. Ich habe nicht erwartet, dass er mir verzeiht. Das war noch nie seine Art. Aber ich hatte gehofft, dass seine Wut über meine Abreise über die Jahre schwächer geworden ist.\n\nVor dreißig Jahren habe ich die Mok'Nathal verlassen, um der Horde nach Azeroth zu folgen. Leoroxx war strikt dagegen, gab mir aber auch keinen Grund zu bleiben. Und doch hätte ich mir ein herzlicheres Willkommen gewünscht.\n\nEr wollte einen Mok'Nathal als Sohn haben und hat immer noch einen, auch wenn er nichts davon wissen möchte.\n\nIch werde ihm die Augen öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10710] = { id = 10710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Der Singende Bergrücken", description = "Ich habe ein wenig an dem Zephyriumkapazitorium herumgebastelt und bin bereit für einen weiteren Test! Wollt Ihr mir helfen?\n\nDieser nächste Flug sollte kurz, aber schnell sein!\n\nÄh... und obwohl ich mir sicher bin, dass es nicht gefährlich wird... habe ich hier diesen Haftungsausschluss, den Ihr bitte unterschreiben möchtet. Nur eine Formalität, kein Grund zur Sorge!\n\nViel Glück! Sprecht mit Rally, wenn Ihr zum Abschuss bereit seid und kehrt zu mir zurück, wenn das Experiment vorbei ist!", sourceObjective = "Unterzeichnet Tallys Haftungsausschluss und sprecht mit Rally Zapschnapper, um das Zephyriumkapazitorium zu benutzen.", progress = "Keine Sorge, {name}! Sorgen haben noch niemandem weitergeholfen!", completion = "Wow! Ihr habt schon wieder überlebt! Ich bin ein besserer Ingenieur, als ich immer dachte!\n\nHier ist Eure Bezahlung! Und schaut doch später nochmal bei mir vorbei... Ich habe noch mehr Experimente, für die ich Versuchspersonen brauche!", sourceObjectiveStatus = "unverified-source-field" }
quests[10711] = { id = 10711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Razaans Landeplatz", description = "{name}, ich habe die Effizienz des Zephyriumkapazitoriums um 30 Prozent gesteigert! Ein Versuchsobjekt von Eurem Gewicht wird dann Dank des Luftreibungsverhältnisses in ungeahnte Höhen geschleudert! Wollt Ihr meine Theorie testen? Dieses Experiment sollte Euch in die Nähe von Razaans Landeplatz schicken.\n\nSprecht mit Rally... er wird Euch für den Abschuss vorbereiten.", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium.", progress = "Was? Ihr wollt das Experiment nicht durchführen? Nicht kneifen, {name}! Ich bin die ganze Zeit hinter Euch!", completion = "Oh, beeindruckend! So schnell schon zurück! Ich habe gesehen, wie Ihr abgehoben habt und wie eine Rakete in die Luft geschossen seid! Ich dachte, es würde mindestens einen Monat Genesung brauchen, bis Eure gebrochenen Beine wieder geheilt sind! Ihr seid hart im Nehmen, mutig und kühn! Aber vor allem... mutig!", sourceObjectiveStatus = "unverified-source-field" }
quests[10712] = { id = 10712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testflug: Ruuanwald", description = "He {name}! Gut, dass ich Euch treffe! Ich habe einen sehr wichtigen Auftrag für Euch.\n\nDas hier ist eine Netherwetterfahne. Ich möchte, dass Ihr während des Flugs ein paar Aufzeichnungen macht und sie zu meinem Vetter im Ruuanwald bringt.\n\nSprecht mit Rally und nehmt einen Flug mit dem Zephyriumkapazitorium zum Ruuanwald. Lasst während dem Flug die Fahne rotieren!\n\nBringt nach Eurer Landung die rotierende Fahne zu O'Mally Zapschnapper.\n\nViel Glück, {name}. Und trödelt nicht!", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Lasst auf Eurem Flug die Netherwetterfahne rotieren. Bringt die rotierende Netherwetterfahne zu O'Mally Zapschnapper im Ewigen Hain.", progress = "Hallo hallo! Mein Klo... äh... mein Vetter Tally hat mir gesagt, dass Ihr vorbeikommen würdet. Habt Ihr etwas für mich?", completion = "Oh, Ihr habt Aufzeichnungen mit der Netherwetterfahne gemacht? Ausgezeichnet! Die Daten dieses Instruments werden zusammen mit meinen Messungen druidischer Magie sicher viele Früchte tragen!\n\nOh, die Einsatzmöglichkeiten werden Euch um den Verstand bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10713] = { id = 10713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und Zeit zu Handeln", description = "Wir werden nicht tatenlos zusehen, wie sie den Ruuanwald um uns herum ausrotten. Unser höchstes Augenmerk muss den Bäumen gelten.\n\n{class}, ich möchte, dass Ihr in den Wald geht, und eine ganz besondere Nachricht von uns übermittelt. Ich möchte, dass Ihr jeden einzelnen ihrer Roder, dem Ihr begegnet, tötet.\n\nWenn sie nicht auf vernünftige Argumente hören möchten, dann vielleicht auf schlagkräftige.", sourceObjective = "Tötet 10 Roder des Wyrmkults.", progress = "Habt Ihr die Bäume geschützt? Habt Ihr die Roder gefällt?", completion = "Danke, {name}.\n\nWir werden uns darum kümmern, dass die Wildtiere sich selbst wieder schnell vermehren. Bei den Bäumen ist dies jedoch ein sehr viel zeitaufwändigerer Prozess.", sourceObjectiveStatus = "unverified-source-field" }
quests[10714] = { id = 10714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf geisterhaften Schwingen", description = "Wenn die Mok'Nathal von den Ogern der Blutschläger tyrannisiert werden, werde ich sie und ihre Anhänger aufhalten. Oger sind einfach gestrickte Wesen. Die Mok'Nathal zu belästigen bringt ihnen keine besonderen Vorteile.\n\nEs muss mehr dahinter stecken, {name}. Nehmt Geisterschwinge, meinen Falken, und belauscht die Gespräche der Anführer der Blutschläger. Er wird unbeobachtet bleiben, wo Ihr auffallen würdet.", sourceObjective = "Sucht einen Zuchtmeister der Blutschläger und einen Sterndeuter der Blutschläger, die sich gerade unterhalten. Benutzt Rexxars Pfeife, um Geisterschwinge zu rufen und sie durch ihn zu belauschen.", progress = "Was habt Ihr erfahren, {name}?", completion = "<Geisterschwinge lässt sich auf Rexxars Schulter nieder, während Rexxar aufmerksam zuhört.>\n\nDie Söhne des Gruul stecken also hinter den Handlungen der Oger. Sie befehlen den Ogern der Blutschlägern, die Mok'Nathal zu vernichten, um ihre Gunst zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10715] = { id = 10715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grabenschlucht", description = "Euer Rexxar möchte also, dass ich ein Gift für ihn herstelle? Ich werde ihm geben, was er sich wünscht, aber das hat einen Preis, den auch Freunde bezahlen müssen.\n\nZunächst müsst Ihr einen kurzen Weg nach Südwesten in die Grabenschlucht zurücklegen.\n\nDort leben ein paar der giftigsten Kreaturen der ganzen Scherbenwelt, wenn nicht die giftigsten überhaupt. Ich spreche von den Krustenbohrern. Wenn Ihr ein Gift wollt, müsst Ihr ein paar Ihrer Drüsen für mich sammeln.", sourceObjective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10716] = { id = 10716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Flight: Raven's Wood <needs reward>", description = "Das Zephyriumkapazitorium ist für seinen bisher längsten Flug bereit! Was meint Ihr, {name}? Wollt Ihr noch einmal fliegen?\n\nIch habe das Antriebssystem verbessert, aber bis ich die passenden Einstellungen gefunden habe, werden wir zusätzlichen Treibstoff brauchen, um ihm den richtigen Kick zu geben! Sprecht vor dem Flug mit Rally, er hat die Einzelheiten.\n\nViel Glück, {name}. Dieser Flug wird Euch zum weit entfernten Rabenwald bringen. Wenn Ihr ihn überlebt - und die Oger und Arakkoa des Waldes - kommt zu mir zurück, damit wir feiern können!", sourceObjective = "Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[10717] = { id = 10717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilderer wildern", description = "Verzeiht, aber ich konnte nicht umhin, Euer Gespräch mit Chawn mitzuhören. Ich würde gerne helfen.\n\nIch stelle Nachforschungen über den Pechschwingenkoven an und helfe den Druiden, mit ihnen fertigzuwerden.\n\nIch bin sehr daran interessiert, an ein paar ihrer Welplinge zu kommen. Um einen Feind wirklich verstehen zu können, muss man lernen, was er verehrt.\n\nAber zunächst bräuchten wir ein paar Netze. Die Wilderer des Wyrmkults draußen im Ruuanwald haben eine ganze Menge davon.", sourceObjective = "Beschafft Euch 5 Netze des Wyrmkults.", progress = "Wie geht es mit der Beschaffung der Netze voran? Meiner Einschätzung nach sind diese Netze der Wilderer stark genug, um unserer Sache dienlich zu sein.", completion = "Oh, die sehen hervorragend aus. Diese Kultisten wissen wirklich, was wahre Handwerkskunst ist.\n\nZu schade, dass sie sie missbrauchen.\n\nJetzt, da wir die Netze haben, bräuchte ich Eure Hilfe bei ein oder zwei Angelegenheiten. Habt Ihr Lust?", sourceObjectiveStatus = "unverified-source-field" }
quests[10718] = { id = 10718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme der Geister", description = "{name}, jetzt, da Ihr mich sehen könnt, müsst Ihr Rexxar etwas von mir ausrichten. Ich weiß, dass er sein Volk sucht und ich weiß auch, wo es ist.\n\nDie Mok'Nathal haben ein Dorf im Osten, hinter dem Messergrat.\n\nGeht und bringt Rexxar diese Nachricht. Sein Volk ist in Gefahr! Ich weiß, dass er ihnen sehr gerne helfen würde.", sourceObjective = "Sprecht mit Rexxar in der Donnerfeste im Schergrat.", completion = "Wovon redet Ihr?\n\nGarm Wolfsbruder? Er war der letzte Häuptling der Donnerfürsten. Wenn Ihr mit seinem Geist gesprochen habt, muss es wahr sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10719] = { id = 10719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid eingeladen!", description = "Der Kultist hat diese Einladung fallenlassen, die offensichtlich an Aufseher Nuaar übergeben werden sollte. Sie ist mit dem Namen Kolphis Dunkelschuppe unterzeichnet.\n\nBaumhüter Chawn wäre sicher sehr interessiert daran.", sourceObjective = "Bringt die Einladung zum Treffen zu Baumhüter Chawn im Ewigen Hain im Schergrat.", progress = "Was habt Ihr da? Ist da ein Blutfleck auf der Einladung?", completion = "Das ist interessant, aber auch beunruhigend. Vielleicht sollten wir Samia fragen, wer dieser Kolphis Dunkelschuppe ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[10720] = { id = 10720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kleinsten Wesen", description = "So einfältig sie auch sein mögen, würde es den Ogern auffallen, wenn Ihr dieses Gift in ihrem Lager verteilt. Daher will ich Euch beibringen, wie man die Hilfe eines der kleinsten Wesen in der Natur für diese Aufgabe in Anspruch nehmen kann.\n\nWenn Ihr einen einfachen Rhythmus auf dieser Trommel spielt, könnt Ihr ein Murmeltier so beeinflussen, dass es Euren Befehlen gehorcht.\n\nIn der Nähe des Lagers der Blutschläger gibt es einen Murmeltierbau. Er befindet sich im Norden in der Dolchrachenklamm hinter dem Zirkel des Blutes.\n\nBenutzt ein Murmeltier dazu, das Gift in den Fässern der Blutschläger zu verteilen, sobald Ihr es beeinflussen könnt.", sourceObjective = "Begebt Euch zum Murmeltierbau und schlagt die Kodobalgtrommel. Vergiftet die drei Fässer im Lager der Blutschläger, während Ihr das Murmeltier kontrolliert.", progress = "Ist es vollbracht?", completion = "Viele Jahre lang habe ich versucht, die Kommunikation mit der Natur zu perfektionieren. Dies ist nur ein Bruchteil dessen, was die Tiere für Euch tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10721] = { id = 10721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc einen Eber aufbinden", description = "{name}, ich habe einen Eber namens Grummel als Haustier. Er möchte Euch dabei helfen, ein wenig Spaß mit einem der Söhne Gruuls in der Nähe zu treiben.\n\nGrulloc lebt an einem Ort namens Verfluchtes Dunkel. Begebt Euch dorthin und lasst Grummel dann frei. Der Gronn wird es lustig finden, ihn umher zu jagen. Ihr könnt in der Zwischenzeit den Sack, den er bewacht, stehlen und zu Baron Zobelmähne beim Zirkel des Blutes bringen.\n\nIhr gelangt zum Verfluchten Dunkel, indem Ihr den nördlichen Pfad hinunter geht und dann nach Osten durch Drachenend hindurch geht. Das Dunkel befindet sich am östlichen Rand.", sourceObjective = "Beschafft Euch Grullocs Sack.", progress = "So schnell schon zurück? Seid Ihr hier, um Rexxars Schulden zurückzuzahlen?", completion = "<Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.>\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun, da der Preis bezahlt ist, werde ich Rexxar geben, was er begehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10722] = { id = 10722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Pechschwingenkoven", description = "Ich weiß, was zu tun ist! {name}, Ihr müsst Euch als Aufseher Nuaar ausgeben und an diesem Treffen teilnehmen!\n\nDie Wyrmkultisten tragen alle ein Standardgewand. Sammelt ein paar Fetzen davon. Wenn Ihr genügend zusammen habt, können wir eine Verkleidung herstellen, in der Ihr an dem Treffen teilnehmen könnt.\n\nSprecht mit Kolphis Dunkelschuppe und hört Euch an, was er zu sagen hat. Kehrt danach zu mir zurück.\n\nIhr findet den Koven indem Ihr durch den Tunnel des Wyrmschädels geht und dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende folgt.", sourceObjective = "Sammelt genügend Gewandfetzen von verschiedenen Wyrmkultisten, um eine Aufseherverkleidung herzustellen. Benutzt die Verkleidung, um am Treffen mit Kolphis Dunkelschuppe teilzunehmen.", completion = "Uns angreifen? Uns auslöschen? Das glaube ich aber nicht!\n\nDieser Pechschwingenkoven muss noch viel lernen, wenn sie denken, dass man die Expedition des Cenarius so leicht loswerden kann!\n\nWie sagt man so schön? Wie du mir, so ich dir!", sourceObjectiveStatus = "unverified-source-field" }
quests[10723] = { id = 10723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom der Drachenfresser", description = "Der Gronn, den wir suchen, heißt Gorgrom der Drachenfresser. Mit Zobelmähnes Falle werdet Ihr ihm kurzen Prozess machen können. Ihr könnt ihn wahrscheinlich antreffen, wenn er die Opfer der Oger von Fels'mok entgegen nimmt.\n\nFolgt der Straße, die nach Norden vom Zirkel des Blutes weg führt, und wendet Euch dann beim Ruuanwald nach Westen. Durchquert danach den Tunnel nach Nordwesten.\n\nTötet zunächst die Oger, um an ihre Köpfe zu kommen. Stellt danach die Falle bei Gorgroms Altar auf und wartet auf seine Ankunft. Tötet ihn und stellt dann die Köpfe als grausige Totems um seine Leiche herum auf. Diese Nachricht sollte man nicht missverstehen können.\n\nNehmt den Bären mit!\n\n<Misha knurrt.>", sourceObjective = "Sammelt 3 grausige Totems von den Ogern von Fels'mok. Stellt danach Zobelmähnes Falle bei Gorgroms Altar auf, um Gorgrom den Drachenfresser zu rufen, und tötet ihn.\n\nWenn Gorgrom tot ist, platziert die drei grausigen Totems in der Nähe seiner Leiche.", progress = "Die Oger der Blutschläger werden uns nie mehr belästigen, wenn Ihr Eure Aufgabe erfüllt habt.", completion = "Die Oger der Blutschläger und ihr Meister, Gorgrom, werden die Mok'Nathal nie wieder belästigen.\n\nIch mache mir jedoch Sorgen über die Auswirkungen unserer Tat auf die anderen Gronn. Ich glaube, wir müssen diesem Kampf ein für allemal ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10724] = { id = 10724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangener der Speerspießer", description = "Kurz nach meiner Ankunft in den Bergen wurde ich von einer Gruppe von Ogern der Speerspießer angegriffen.\n\nIch konnte mich zwar freikämpfen, doch sie haben es geschafft, meinen Wyvern Leokk zu entführen. Geisterschwinge hat ihn gefunden. Er wird in der Mitte des Lagers der Speerspießer außerhalb von Gruuls Unterschlupf in einem Käfig gefangen gehalten.\n\nEiner der Oger muss den Schlüssel dazu haben. Findet ihn, dann kann Geisterschwinge damit Leokks Käfig öffnen.\n\nDas Lager liegt dort unten am nördlichen Ende der Dolchrachenklamm.", sourceObjective = "Tötet die Oger der Speerspießer, um an den Wyvernkäfigschlüssel zu kommen. Sobald Ihr ihn habt, benutzt Geisterschwinges Pfeife, um Geisterschwinge zu rufen, der den Käfig öffnen wird, um Leokk zu befreien.", progress = "Es wäre schön, Leokk wieder an meiner Seite zu wissen.", completion = "Leokk hat uns den Kopf eines schwarzen Drachen von Drachenend gebracht, damit können wir Goc, den Gronn, der ihn gefangen genommen hat, erzürnen und ihn in die Schlacht locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10725] = { id = 10725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geachtet vom Violetten Auge", description = "Eure Dienste haben unsere Erwartungen bei Weitem übertroffen, {name}. Ihr seid nur einen Schritt davon entfernt, die höchste Ehre unter denen, die nicht in Dalaran leben, zu erlangen.\n\nBeweist uns weiterhin Eure Treue und ich werde den Siegelring mit der größtmöglichen Macht ausstatten.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt.", progress = "Seid gegrüßt, {name}! Es ist mir eine Freude, Euch wieder zu sehen.", completion = "Euer Siegelring ist nun so mächtig wie der eines jeden Erzmagiers des Rats. Tragt ihn immer an Eurem Finger, damit die Eingeweihten Eure Zugehörigkeit zu uns erkennen können. Möge seine Macht Euch immer so gut dienen, wie Ihr uns gedient habt!", sourceObjectiveStatus = "unverified-source-field" }
