quests[10732] = { id = 10732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Beschützers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10733] = { id = 10733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[10734] = { id = 10734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[10735] = { id = 10735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[10736] = { id = 10736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[10737] = { id = 10737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung des Meisters", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.", sourceObjective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10738] = { id = 10738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
quests[10739] = { id = 10739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
quests[10740] = { id = 10740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
quests[10741] = { id = 10741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
quests[10742] = { id = 10742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale", description = "Jetzt geht es wie folgt weiter. Wir locken Goc von seinem Unterschlupf weg und vernichten ihn. Wenn Goc tot ist, werden die Oger der Speerspießer die Mok'Nathal nie mehr belästigen. Geht zu Gocs Altar außerhalb von Gruuls Unterschlupf und blast dann in mein Horn. Ich werde kommen und zusammen werden wir Gruuls Sohn zur Strecke bringen.", sourceObjective = "Benutzt Rexxars Kampfhorn beim Altar von Goc und tötet Goc.", progress = "Nur wenn Goc und Gorgrom der Drachenfresser tot sind, werden die Mok'Nathal frei sein.", completion = "Der Kampf war hart und Ihr habt Euch gut geschlagen, {name}. Ich bin stolz, dass ich in der Schlacht gegen Goc an Eurer Seite kämpfen durfte.\n\nDie Mok'Nathal sollten von diesen großartigen Siegen erfahren, aber ich bin noch nicht bereit, ihnen gegenüberzutreten. Ich kenne meinen Vater und ich kenne mein Herz. Es gibt immer noch vieles, was ich lernen und tun kann, um stärker zu werden und ihm zu beweisen, dass ich sein wahrer Sohn bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[10744] = { id = 10744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Sieg", description = "Ihr müsst sofort Kurdran Wildhammer von unserem Sieg berichten! Seine Leute haben unter Schwadronskommandant Nuainn rund um die Uhr gekämpft, um die Wildhammerfeste zu schützen. Eure Rückkehr wird sie sicher anspornen. Jetzt, da die Bedrohung der Legion aus dem Weg geräumt ist, kann Kurdran sich endlich Illidans Streitkräften widmen. Unsere Stellung hier ist noch lange nicht gesichert, aber wir haben heute einen entscheidenden Sieg errungen.", sourceObjective = "Kehrt zur Wildhammerfeste zurück und sprecht mit Kurdran Wildhammer.", completion = "<Kurdran hört Euren Bericht an.>\n\nDas sind in der Tat gute Nachrichten! Noch vor ein paar Tagen hätte ich mir nie träumen lassen, dass wir der Belagerung der Legion ein Ende machen könnten.\n\nIhr habt nicht nur ihren Angriff verhindert, sondern auch noch ihre Maschinerie vernichtet! Für diesen Heldenmut habt Ihr den Dank der Wildhämmer, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10745] = { id = 10745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Sieg", description = "Ihr müsst sofort Oberanführer Or'barokh von unserem Sieg berichten! Jetzt, da wir die Legion geschlagen und ihre Anwesenheit im Schattenmondtal beendet haben, kann der Oberanführer sich endlich unseren anderen Feinden widmen.\n\nAuch wenn die Wache der Kor'kron es nie zugeben würden, werden sie erleichtert sein, nicht mehr an zwei Fronten gleichzeitig kämpfen zu müssen.", sourceObjective = "Kehrt nach Schattenmond zurück und sprecht mit Oberanführer Or'barokh.", completion = "<Der Oberanführer hört Euren Bericht an.>\n\nAusgezeichnete Nachrichten! Den Angriffen der Legion standzuhalten nahm einfach viel zu viele Leute in Anspruch. Ich habe zwar nie geglaubt, dass meine Leute versagen würden, aber sie standen unter großer Belastung.\n\nIhr habt heute bewiesen, wie wichtig Ihr für die Horde seid. Die Wache der Kor'kron wird sich jederzeit geehrt fühlen, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10747] = { id = 10747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welpen des Wyrmkults", description = "Wie ich bereits sagte würde es uns helfen, den Kult zu verstehen, wenn wir einige der Welpen, die sie beim Pechschwingenkoven züchten, untersuchen.\n\nSo wie ich das verstanden habe, müssen in ihrem höhlenartigen Lager eine ganze Menge von Welpen herumfliegen. Dort sind auch ein paar Eier, die wahrscheinlich schlüpfen werden, wenn Ihr ihnen zu nahe kommt.\n\nBitte, {name}, nehmt das Netz und sammelt ein paar davon lebend für mich.\n\nIhr findet den Koven im Westen. Überquert die Brücke des Wyrmschädels und nehmt dann den Tunnel des Wyrmschädels. Folgt dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende.", sourceObjective = "Verwendet das Schwarzwelpennetz, um 10 Schwarzwelpen des Wyrmkults zu fangen.", progress = "Hattet Ihr viel Ärger beim Versuch, die Welpen zu fangen? Ich hoffe, Ihr habt Euch nicht verbrannt!", completion = "Ach herrje, das sind ja mehr, als ich gehofft hatte! Für Euren Heldenmut habt Ihr gewiss ein Lob verdient!\n\nDiese Welpenbrut sieht sehr gut aus. Sie sind wie gemacht für meine Untersuchungen.\n\nBitte, nehmt eine kleine Belohung von mir an. Ich bestehe darauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[10748] = { id = 10748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxnar muss sterben!", description = "Sie haben uns keine andere Wahl gelassen, {name}. Es ist an der Zeit, der Bedrohung am Pechschwingenkoven ein Ende zu setzen. Wir müssen ihren Anführer, Maxnar den Aschenmagen, erschlagen.\n\nIch weiß nicht, ob Ihr ihn schon zu Gesicht bekommen habt, als Ihr dort wart, aber er ist ein Drachkin, halb Mensch, halb Drache. Und er ist ganz schön zäh, also unterschätzt ihn nicht!\n\nErledigt ihn schnell. Mit etwas Glück bringt Ihr so die Sicherheit in den Ewigen Hain und den Ruuanwald zurück.", sourceObjective = "Tötet Maxnar den Aschenmagen.", completion = "Jetzt, da der Anführer unserer Feinde tot ist, können wir endlich wieder ein wenig aufatmen. Und Ihr habt auch noch das gesamte Gebirge vor ihrer Verwüstung bewahrt.\n\nWas auch immer ihre endgültigen Pläne gewesen sein mögen, Ihr habt sie vereitelt!\n\nIhr habt unseren Dank, {name}. Bitte nehmt dieses Zeichen unserer Wertschätzung sowie unsere ewig währende Gastfreundschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[10749] = { id = 10749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähnes Gift", description = "Hier, bringt dies zu Eurem Auftraggeber. Ich bin mir sicher, dass Rexxar es sinnvoll einzusetzen weiß.\n\nOh, und stellt sicher, dass er sich im Klaren ist, dass er mir etwas schuldet.\n\nEr weiß, was ich will. Ich bin mir sicher, dass wir uns - ganz gleich, wie er es zu beschafften gedenkt - schneller wiedersehen werden, als Ihr vielleicht denkt.\n\nJetzt seid ein <braver Junge/braves Mädel> und bringt dies zu Rexxar.", sourceObjective = "Bringt Baron Zobelmähnes Gift zu Rexxar in der Donnerfeste im Schergrat.", progress = "{class}, so schnell schon zurück? Habt Ihr das Gift?", completion = "Die Verwendung von Giften ist ein dreckiges Geschäft. Aber so werden wir unsere Ziele erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10750] = { id = 10750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Eroberung", description = "Meine Windreiter sind mit ein paar Neuigkeiten zurückgekehrt, {name}. Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt weit im Süden und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Windreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", sourceObjective = "Reist zum Pfad der Eroberung im Schattenmondtal.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10751] = { id = 10751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad bereinigen", description = "Wir brauchen mehr Zeit, {race}! Ich werde mit den anderen Windreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Windreiter mithilfe der Leuchtpistole der Kor'kron!", sourceObjective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 10 Zauberbinder der Mondfinsternis.", completion = "Ihr werdet es nicht glauben, Grunzer!", sourceObjectiveStatus = "unverified-source-field" }
quests[10752] = { id = 10752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Eschental!", description = "Vor Kurzem kam Raene Wolfsläufer aus Darnassus durch Auberdine. Sie war auf dem Weg ins Eschental und murmelte etwas von Furbolgs. Ich hatte keine Gelegenheit, sie genauer dazu zu befragen, aber vielleicht könnt Ihr Euch ja auf die Suche nach ihr begeben und ihr Eure Hilfe anbieten, {class}. Nehmt die südliche Straße aus Auberdine hinaus. Folgt der Straße einfach weiter, sobald Ihr die Grenze zum Eschental erreicht habt. Dort findet Ihr schließlich Astranaar und Raene Wolfsläufer.", sourceObjective = "Sprecht mit Raene Wolfsläufer in Astranaar.", completion = "Thundris Windwirker denkt also immer noch, dass man auf mich aufpassen muss? Ich werde ihn wohl daran erinnern müssen, wer hier wen gerettet hat. Er scheint vergessen zu haben, dass ich ihn vor den schlimmsten Übeln bewahrt habe.\n\nNun, da Ihr schon hier seid, {race}, habe ich vielleicht doch eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10753] = { id = 10753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis ausmerzen", description = "Die Zahl der Verbrechen, die die Brennende Legion begangen hat, steigt ins Unermessliche. Genau in diesem Moment schickt die Legion wieder ihre Truppen aus, um die Lebewesen dieser Welt heimzusuchen. Sie sind ihrer Macht hilflos ausgeliefert und fallen einer nach dem anderen ihrer Gewalt zum Opfer. {name}, helft mir dabei, diese Verbrechen gegen die Natur aufzuhalten und vernichtet alles, was von ihrer Verderbnis befallen wurde.\n\nHinter den Bergen im Osten könnt Ihr sehen, wie sich die Verderbnis in der Messerschlucht ausbreitet. Tötet die Verantwortlichen, die Teufelsverderber, und so viele Teufelsanbeter, wie Ihr nur könnt.", sourceObjective = "Tötet 4 Wesen der Schuppenflügelteufelsbrut, 4 Wesen der Dolchrachenteufelsbrut und 2 Teufelsverderber.", completion = "Es erfüllt mich nicht mit Stolz zu zerstören, was Elune erschaffen hat, aber die Verderbnis muss aufgehalten werden. Ihr habt Eure Arbeit gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10754] = { id = 10754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang zur Zitadelle", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Danath, der Truppenkommandant der Ehrenfeste, dafür.", sourceObjective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Danath in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Kann das wahr sein? Lasst mich die Form einmal genauer betrachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10755] = { id = 10755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugang zur Zitadelle", description = "Diese frisch gegossene Form wurde für die Herstellung eines Schlüssels benutzt. Das eingravierte Bild auf ihr deutet darauf hin, dass sie etwas mit der Höllenfeuerzitadelle zu tun hat.\n\nVielleicht interessiert sich Nazgrel, der Anführer der Streifkräfte der Horde in Thrallmar, dafür.", sourceObjective = "Bringt die präparierte Schlüsselform zu Truppenkommandant Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Wollt Ihr mir etwas zeigen, {name}?", completion = "Eine Schlüsselform? Könnte es das sein, was uns Zugang zu den Zerschmetterten Hallen verschafft?", sourceObjectiveStatus = "unverified-source-field" }
quests[10756] = { id = 10756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Rohok", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Rohok, unserem Schmied hier. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", sourceObjective = "Bringt die präparierte Schlüsselform zu Rohok nach Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Was ist das?", completion = "Nazgrel möchte, dass ich einen Schlüssel herstelle? Hat er vergessen, dass wir auf einem Schlachtfeld sind? Es gibt Klingen und Speere zu schmieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[10757] = { id = 10757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohoks Bitte", description = "Die Schmiedekunst der Höllenorcs mag nicht gerade die anspruchsvollste sein, aber es ist dennoch Geschick für ihr Handwerk von Nöten. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", sourceObjective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Rohok in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe?", completion = "Ausgezeichnet. Wollen wir es versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10758] = { id = 10758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer als die Hölle", description = "Es klappt nicht, {name}! Egal wie viele Kohlen ich auf das Feuer lege, die Hitze des Feuers reicht einfach nicht aus.\n\nMir fällt nur noch eine Sache ein, die heiß genug sein könnte, um diesen Schlüssel auf die richtige Temperatur zu bringen, und das ist das Innere eines Teufelshäschers der Legion.\n\nIch habe bisher nur einmal gesehen, wie einer niedergestreckt wurde. Seine Innereien rauchten, brannten und dampften, als er fiel. Nehmt diese Form und haltet sie in einen gefallenen Teufelshäscher. Ich würde Euch empfehlen, ein paar Freunde mitzunehmen, falls Ihr vorhattet, ihn alleine zur Strecke zu bringen.", sourceObjective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Rohok in Thrallmar.", progress = "Habt Ihr getan, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt es geschafft! Jetzt müsst Ihr sie nur noch ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10759] = { id = 10759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Deserteur", description = "Ich habe das Gefühl, dass alle Teile des Puzzles vor meinen Augen liegen, aber ich kann sie einfach nicht sinnvoll zusammensetzen.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Nordwesten. Wahrscheinlich hat er dort Zuflucht gesucht.", sourceObjective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", completion = "<Der Arakkoa kichert.>\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10760] = { id = 10760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wrack der Sketh'lon", description = "Das Wrack der Sketh'lon, direkt im Osten, ist ein unheimlicher Ort. Die Peons sind davon überzeugt, dass es dort spukt.\n\nEs gibt dort ein paar Bäume, deshalb haben die Peons keine andere Wahl, als in die Ruinen der Arakkoa zu gehen und Holz zu schlagen. Die Geister der Arakkoa nähren sich an den Arbeitern. Sie saugen ihre Lebensenergie auf und benutzen sie, um ihre verdorbene Magie zu verstärken.\n\nWir müssen herausfinden, was den Dunklen Rat dazu treibt und ihn aufhalten, bevor sein Einfluss überhand nimmt. Durchsucht das Wrack der Sketh'lon nach Hinweisen auf ihre Pläne.", sourceObjective = "Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Unteroffizier Kargrul in Schattenmond.", progress = "Was habt Ihr herausgefunden?", completion = "<Der Unteroffizier untersucht die Tagebuchseiten.>\n\nHier steht nicht viel Sinnvolles, aber ein paar Einträge könnten sich als nützlich erweisen. Wie es aussieht waren die Arakkoa dabei, ein kompliziertes magisches Ritual vorzubereiten, bis sie starben, aber warum? Hier steht auch etwas Merkwürdiges über einen 'Deserteur'.", sourceObjectiveStatus = "unverified-source-field" }
quests[10761] = { id = 10761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Deserteur", description = "Hier steht nichts, was erklären würde, warum die Geister dieser Arakkoa in dieser Welt zurückbleiben oder wie sie ihren Durst nach Orcblut entwickelt haben.\n\nIch glaube, dass unsere heißeste Spur dieser Deserteur ist. Wir müssen ihn finden. Wenn er seine Kameraden im Lager zurückgelassen hat, besteht die Möglichkeit, dass Ihr ihn vielleicht dazu überreden könnt uns zu verraten, was die Arakkoa des Dunklen Rats vorhaben.\n\nBeginnt Eure Suche nach ihm in den Magmafeldern im Süden. Wahrscheinlich hat er dort Zuflucht gesucht.", sourceObjective = "Sucht Parshah in den Magmafeldern und sprecht mit ihm.", completion = "<Der Arakkoa kichert.>\n\nJa, ich bin der Deserteur, den der Kommandant in seinem Tagebuch erwähnt. Ich habe auf den Tag gewartet, an dem auch andere die Bedrohung erkennen, die von meinen einstigen Brüdern ausgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10762] = { id = 10762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Dumphry", description = "Das Symbol auf dem Schlüsselgriff... man kann es in der Form nur schwer erkennen, aber ich erkenne es als das Siegel der Zerschmetterten Hand.\n\nEs besteht eine hohe Wahrscheinlichkeit, dass dieser Schlüssel Euch Zugang zu den Zerschmetterten Hallen bieten kann.\n\nSprecht mit Dumphry. Er ist ein Meister seiner Kunst. Wenn er diesen Schlüssel nicht für Euch herstellen kann, kann es niemand.", sourceObjective = "Bringt die präparierte Schlüsselform zu Dumphry in der Ehrenfeste.", progress = "Was ist das?", completion = "Ein Schlüssel? Danath sollte uns eigentlich an Belagerungsmaschinen arbeiten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10763] = { id = 10763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dumphrys Bitte", description = "Die Höllenorcs mögen vollkommene Barbaren sein, aber ihre Schmiedekunst ist nicht so primitiv, wie Ihr denken mögt. Wenn wir einen funktionierenden Schlüssel herstellen möchten, dürfen wir nur Teufelseisen in diese Form gießen. Alles andere würde sie wahrscheinlich zum Zerbrechen bringen.\n\nBringt mir ein paar Teufelseisenbarren, ein wenig arkanen Staub und Feuerpartikel. Ich werde mich daran versuchen, aber ich kann nichts versprechen.", sourceObjective = "Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Dumphry in der Ehrenfeste auf der Höllenfeuerhalbinsel.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe?", completion = "Dann wollen wir es mal versuchen. Mal sehen, was hinter der Schmiedekunst der Orcs steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10764] = { id = 10764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer als die Hölle", description = "Es funktioniert nicht, <Kumpel/Mädel>. Ich kann einfach nicht genug Hitze erzeugen... die Materialien kommen nicht auf ausreichende Temperaturen.\n\nDie Teufelshäscher der Brennenden Legion werden von einem sengenden Kern aus Teufelsfeuer angetrieben, der viel heißer als gewöhnliches Feuer ist.\n\nWenn Ihr genügend Leute zusammentrommeln könntet, um einen davon zur Strecke zu bringen, könntet Ihr die Schlüsselform in dem gefallenen Häscher aufheizen. Aber seid vorsichtig, {class}, diese Teufelshäscher können ganz schön zuschlagen!", sourceObjective = "Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Dumphry in der Ehrenfeste.", progress = "Habt Ihr getan, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt es geschafft, Junge! Jetzt müsst Ihr sie nur noch zur Höllenfeuerzitadelle bringen und ein paar Orcs erlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10765] = { id = 10765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Welten kollidieren...", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfenkanzlerin aussah. Vielleicht habt Ihr auch schon die kleineren Riesen auf dem Pfad bemerkt. Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", sourceObjective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10766] = { id = 10766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Katastrophe", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Die Wildhammerfeste ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Plexi erwartet Euch bereits am Ankunftsort.", sourceObjective = "Meldet Euch bei Plexi im Invasionspunkt: Katastrophe.", completion = "Es freut mich, Euch kennen zu lernen, {name}. Mein Name ist Plexi.\n\nIch werde Euch nicht mit Höflichkeiten langweilen. Wir wissen beide, warum wir hier sind. Und nun an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10767] = { id = 10767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Katastrophe", description = "Jetzt, da wir Zugang zur Basis der Legion beim Invasionspunkt: Katastrophe haben, müssen wir herausfinden, wie wir sie dort aufhalten können. Schattenmond ist erst in Sicherheit, wenn wir die Legion völlig aus dem Schattenmondtal vertrieben haben.\n\nIch habe einen Vortrupp zum Invasionspunkt geschickt, der mit Euch einen Plan entwickeln soll, wie wir die Vorräte der Legion zerstören können. Kehrt zur Feste der Legion zurück und benutzt den Teleporter, über dem grüne Kristalle schweben. Nakansi erwartet Euch bereits am Ankunftsort.", sourceObjective = "Meldet Euch bei Nakansi im Invasionspunkt: Katastrophe.", completion = "Ihr müsst derjenige sein, von dem Blutwache Gulmok gesprochen hat. Ich habe bereits einen Plan, aber ich brauche Eure Hilfe, um die Vorbereitungen abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10768] = { id = 10768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenröcke der Illidari", description = "Die Windreiter müssen nach Schattenmond zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Kor'kron, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, {race}?", sourceObjective = "Sammelt 10 Wappenröcke der Illidari.", progress = "Was habt Ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10769] = { id = 10769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwietracht in den Rängen...", description = "Forscher Tiorus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", sourceObjective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Oberanführer Or'barokh in Schattenmond im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Kor'kron zurück.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Grunzer ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n<Or'barokh nickt.>\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10770] = { id = 10770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Funken", description = "Nordöstlich von hier, auf der Ebene über uns, liegt mein altes, zu Asche verbranntes Zuhause. Bevor die Legion ihre Sengwichtel geschickt hat, um uns in Flammen aufgehen zu lassen, stand dort einst ein stattlicher Wald. Dabei sind so viele ums Leben gekommen, dass sich mein altes Herz auch noch Jahrhunderte später nach Rache sehnt. Es sind zu viele von ihnen dort, um das Land tatsächlich zurückzufordern, aber Ihr könntet ihnen vielleicht ein wenig Angst einjagen.\n\nIhr werdet mir doch helfen, oder?", sourceObjective = "Moosborke der Uralte möchte, dass Ihr 8 Sengwichtel tötet und danach zu ihm im Ruuanwald zurückkehrt.", completion = "Es gibt so viele, dass wir sie nie alle töten können, aber Ihr habt mir Hoffnung gegeben. Vielleicht sollte ich noch ein paar Jahrhunderte lang stärker versuchen, meinen geliebten Wald wieder zum Leben zu erwecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10771] = { id = 10771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Asche", description = "Wenn Ihr der Straße nach Osten den Berg hinauf folgt und dann nach Norden abbiegt, gelangt Ihr an mein altes Zuhause.\n\nEinst stand dort ein prächtiger Wald, dessen Name schon lange vergessen ist. Doch vor ewigen Zeiten rief die Brennende Legion Sengwichtel und andere Flammenwesen herbei, zerstörte mein Zuhause und zwang mein Volk zu fliehen. Nun bin nur noch ich übrig.\n\nIch habe ein paar Eisenwurzelsamen aufgehoben, die in fruchtbaren vulkanischen Boden gepflanzt werden können. Ihre Magie ist sehr stark. Bitte tut mir diesen Gefallen und ich werde die Schätze längst vergangener Zeiten mit Euch teilen.", sourceObjective = "Moosborke der Uralte möchte, dass Ihr nach Skald reist und Eisenwurzelsamen in drei verschiedene Hügel fruchtbarer Vulkanerde pflanzt. Kehrt danach zu ihm im Ruuanwald zurück.", progress = "Ist es vollbracht? Habt Ihr etwas Leben in mein altes Zuhause zurückgebracht?", completion = "Ihr habt viele dieser verderbten Kreaturen getötet. Mit dieser Gewissheit kann ich nun etwas ruhiger schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10772] = { id = 10772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Eroberung", description = "Meine Greifenreiter sind mit ein paar Neuigkeiten zurückgekehrt! Die Blutelfen der Mondfinsternis führen etwas Großes im Schilde. Sie haben begonnen, ihre Armeen beim Pfad der Eroberung zusammen zu ziehen. Er liegt östlich von hier und schließt an die Stätte der Mondfinsternis an.\n\nIch möchte, dass Ihr zum Pfad der Eroberung reist und die Situation einschätzt. Wenn Ihr fertig seid, benutzt diese Leuchtpistole um einen Greifenreiter herbeizurufen. Daraufhin wird sich einer aus den Lüften schwingen, um Euch zu treffen. Berichtet, was Ihr entdeckt habt und erwartet Eure neuen Befehle.", sourceObjective = "Reist zum Pfad der Eroberung im Schattenmondtal.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Diese lästigen Hunde planen etwas Heimtückisches. Wir müssen weitere Nachforschungen anstellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[10773] = { id = 10773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Pfad bereinigen", description = "Wir brauchen mehr Zeit, {race}! Ich werde mit den anderen Greifenreitern vorausfliegen. Hoffentlich können wir ein paar weitere Informationen sammeln. Ihr müsst für mich den Pfad freiräumen. Und noch viel wichtiger: uns ihre Pfeile vom Leib halten!\n\nWenn Ihr ihre Reihen gelichtet habt, ruft einen Greifenreiter mithilfe der Leuchtpistole der Wildhämmer!", sourceObjective = "Tötet 20 Soldaten der Mondfinsternis, 10 Dragoner der Mondfinsternis und 5 Söhne des Corok.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Ihr werdet es nicht glauben, Soldat!", sourceObjectiveStatus = "unverified-source-field" }
quests[10774] = { id = 10774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutelf + Riese = ???", description = "Am südlichen Ende des Pfads der Eroberung, in der Nähe der lagernden Karawane, habe ich etwas beobachtet, das nach einem Treffen zwischen einem Riesen und einer Blutelfe aussah. Was machen die Riesen überhaupt hier? Irgendwas ist an der Sache faul, Soldat.\n\nIch möchte, dass Ihr Euch zu diesem Treffen durchschlagt und die Versammlung auflöst. Sammelt alles, was Ihr dort noch finden könnt, und ruft dann einen von uns mit der Leuchtpistole.", sourceObjective = "Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Sie versuchen also, sich die Gunst der Riesen zu erschleichen, was? Ich habe einen Plan, der diese unheilige Verbindung ganz schnell wieder zerreißen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10775] = { id = 10775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenröcke der Illidari", description = "Die Greifenreiter müssen zur Wildhammerfeste zurückkehren, um sich auf die nächste Phase unseres Angriffs vorzubereiten. Ich benötige von Euch die Wappenröcke, die diese Blutelfen tragen.\n\nWenn Ihr genügend Wappenröcke gesammelt habt, benutzt die Leuchtpistole der Wildhämmer, um einen Greifenreiter zu rufen. Seid ihr bereit für ein wenig Spionage, {race}?", sourceObjective = "Sammelt 10 Wappenröcke der Illidari.", progress = "Was habt ihr zu berichten, Soldat?", completion = "Aha! Die werden funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10776] = { id = 10776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwietracht in den Rängen...", description = "Gnomus war so freundlich, uns dieses Gebräu für unseren finalen Schlag herzustellen. Ich schütte es einfach über den Wappenrock, den Ihr mir gebracht habt, um ihn mit der Essenz der Illidari zu erfüllen.\n\nNehmt diesen verzauberten Wappenrock und reist zu den Feldern der Mondfinsternis südwestlich der Stätte der Mondfinsternis. Wenn Ihr angekommen seid, benutzt den Wappenrock, um Euch in einen Anhänger Illidans zu verwandeln. Tötet die wahnsinnigen Kolosse, die auf den Feldern herumstreifen, solange Ihr verkleidet seid. Sie werden es für einen Angriff der Mondfinsternis halten und alle Beziehungen zu ihnen abbrechen.", sourceObjective = "Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Than Yoregar in der Wildhammerfeste im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Wildhämmer zurück.", progress = "Ihr seid zurück!", completion = "Gut, gut, gut... Wenn das nicht der Soldat ist, den ich zu den Feldern geschickt habe. Ihr seid heil zurück.\n\n<Yoregar nickt.>\n\nIch wusste, dass Ihr mich nicht enttäuschen würdet, Soldat. Ihr habt ein entscheidendes Vorrücken der Illidari aufgehalten und Euch damit eine Belohung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[10777] = { id = 10777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asghars Totem", description = "Was im Tagebuch des Kommandanten steht, ist wahr. Während sich die orcische Horde unter Gul'dan sammelte, versuchte mein Volk, diese Bedrohung abzuwenden, indem sie einen Angriff planten. Gul'dan erfuhr jedoch davon und wirkte einen mächtigen Zauber, der unsere Lager zerstörte und die Geister meiner Brüder zerbrach.\n\nSie müssen aufgehalten werden, bevor sie noch mehr Unheil anrichten. Sucht nach Asghar beim Wrack der Sketh'lon im Norden und bringt mir das Totem, das er bei sich trägt. Damit können wir beginnen, die Pläne des Dunklen Rats zu vereiteln.", sourceObjective = "Bringt das Kriegstotem der Sketh'lon zu Parshah in den Magmafeldern.", progress = "Habt Ihr das Totem von Asghar beschafft?", completion = "<Parshah untersucht das Totem.>\n\nGut. Dieses alte Totem hat seine Macht über die Jahre nicht eingebüßt, doch es alleine reicht noch nicht aus, um den Dunklen Rat aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10778] = { id = 10778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rute von Lianthe", description = "Das Totem alleine ist nicht stark genug, um der teuflischen Magie des Dunklen Rats entgegen zu wirken.\n\nWir können es jedoch mit anderen mächtigen Gegenständen zu einem Stab verarbeiten, mit dem wir die Energien bündeln können. Es ist nicht mehr möglich, meine Brüder aus den Tiefen ihrer Verderbtheit zu erretten, aber wir können sie aufhalten.\n\nEiner dieser Gegenstände, den ich benötige, ist die Rute von Lianthe, die sich im Besitz der Blutelfen in der Stätte der Mondfinsternis im Südosten befindet. Sie wird in einem Pavillon ganz oben in den Ruinen aufbewahrt und sehr schwer bewacht. Seid vorsichtig, {name}.", sourceObjective = "Besorgt Euch den Schlüssel von Lianthe von den Blutelfen in der Stätte der Mondfinsternis und benutzt ihn, um die Schließkassette von Lianthe zu öffnen und die Rute von Lianthe an Euch zu nehmen. Bringt die Rute zu Parshah in den Magmafeldern.", progress = "Konntet Ihr die Rute beschaffen?", completion = "Gut gemacht. Ein solcher Schatz verdient besseres, als in einer dunklen Kiste weggesperrt zu werden. Wir werden ihn für einen guten Zweck einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10779] = { id = 10779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Jägers", description = "Hallo, junger Jäger. Ihr seht aus, als wärt Ihr bereits tüchtig genug, um ein Tier auszubilden und zu Eurem Begleiter zu machen.\n\nSprecht mit Kella Nachtbogen auf der Azurmythosinsel. Sie kann Euch beibringen, wie man ein eigenes Tier beherrscht.", sourceObjective = "Sprecht mit Kella Nachtbogen auf der Azurmythosinsel.", sourceObjectiveStatus = "unverified-source-field" }
quests[10780] = { id = 10780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn der Sketh'lon", description = "Uns fehlt noch ein letztes Element des Stabs. Wir müssen seine Macht gegen die Geister des Dunklen Rats richten.\n\nDies erreichen wir, indem wir Federn bei den Ruinen des Basislagers der Sketh'lon sammeln und an dem Stab befestigen. Das Basislager befindet sich im Süden, östlich der Wildhammerfeste.\n\nGul'dans Magie hat meine Brüder vernichtet und nur ihre Geister übrig gelassen, doch das war nicht alles. Die Magie hat sich an dem Zauber, den die Arakkoa vorbereiteten, genährt und eine ruchlose Macht erschaffen, die die Geister in ihren Bann gezogen hat.", sourceObjective = "Sammelt 8 Federn der Sketh'lon und bringt sie zu Parshah in den Magmafeldern.", progress = "Habt Ihr die Federn für den Stab schon gesammelt?", completion = "<Parshah nimmt Euch die aschebestäubten Federn ab und schüttelt den Kopf.>\n\nEs wäre besser gewesen, wenn ich an diesem Tag gestorben wäre, aber die Dinge sind niemals so einfach. Dass Gul'dans Magie sie in etwas verwandelt hat, das sie aufzuhalten versuchten, ist ein grausames Spiel des Schicksals.", sourceObjectiveStatus = "unverified-source-field" }
quests[10781] = { id = 10781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht an der Purpurwacht", description = "Während wir uns hier unterhalten, suchen sie Euch wahrscheinlich auf dem Pfad der Eroberung. Ihr müsst fliehen, {race}!\n\nLasst mich zurück, ich bin ohnehin dem Untergang geweiht... Sie... Ich glaube, ich höre sie kommen. Jetzt oder nie! Flieht! Wenn Ihr bleibt, werdet Ihr kämpfen müssen!\n\nWenn Ihr doch kämpft und es irgendwie schafft, zu überleben, berichtet A'dal in Shattrath von dem, was Ihr gesehen habt!", sourceObjective = "Bekämpft Illidans Truppen bei der Purpurwacht und überlebt!\n\nKehrt zu A'dal in Shattrath zurück, wenn Ihr als Sieger aus der Schlacht hervorgehen solltet.", completion = "Wir werden weitere Nachforschungen über das Purpursiegel anstellen. Sie stellen eine Bedrohung für alles Leben in Draenor dar. Ich sehe einen Tag voraus, an dem ihr dunkler Herr für seine Verbrechen geradestehen muss. Vielleicht seid Ihr ja derjenige, der ihn der Gerechtigkeit zuführen wird, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10782] = { id = 10782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kopfstück mit Magie erfüllen", description = "Der Stab ist fast fertig!\n\nJetzt müssen wir nur nach das Kopfstück mit der Macht von Gul'dans Echo, das durch diesen verfluchten Ort hallt, erfüllen. Im Osten, in der Nähe der Teufelsgruben und südlich der Todesschmiede, befindet sich der Altar der Verdammnis.\n\nDort sind Teile der Vergangenheit gefangen. Wenn Ihr das unfertige Kopfstück des Stabs in die Gegend um den Altar herum bringt, werden einige Wesenheiten darauf reagieren. Seid also auf der Hut. Ihr tragt einen sehr gefährlichen Gegenstand bei Euch, der eng mit der Katastrophe zusammenhängt.", sourceObjective = "Reist zum Altar der Verdammnis und benutzt das unfertige Kopfstück, während Ihr in der Nähe von Gul'dan steht. Kehrt zu Parshah in den Magmafeldern zurück, wenn Ihr das Kopfstück aufgeladen habt.", progress = "Seid Ihr mit dem magieerfüllten Kopfstück zurück?", completion = "<Parshah nimmt Euch das Kopfstück ab und hält es behutsam in den Händen.>\n\nDieses Kopfstück enthält die Macht, die wir brauchen, um die Pläne des Dunklen Rats im Basislager der Sketh'lon zunichte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10783] = { id = 10783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähne", description = "Das ist mein Plan. Wir werden die Oger vergiften und dann ihren Gronnmeister vernichten.\n\nWährend meinen Reisen in diesen Bergen habe ich einen Mann namens Baron Zobelmähne getroffen. Er ist ein Meister der Alchemie und lässt sich vielleicht davon überzeugen, uns zu helfen.\n\nIhr findet ihn beim Zirkel des Blutes, unten in der Schlucht nördlich von hier. Welchen Preis er auch immer verlangen mag, nehmt ihn an!", sourceObjective = "Sprecht mit Baron Zobelmähne beim Zirkel des Blutes im Schergrat.", completion = "Hallo, {race}. Ich bin Baron Zobelmähne. Ein Freund Rexxars ist auch mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10784] = { id = 10784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet das Lager der Blutschläger!", description = "<Tor'chunk beugt sich zu Euch herüber und flüstert.>\n\n{name}, mit Euren Erfolgen im Kampf gegen die Oger bisher habt Ihr uns mehr als stolz gemacht. Und auch wenn ich vollstes Vertrauen in Rexxars Plan habe, möchte ich Euch trotzdem bitten, die Oger im Lager der Blutschläger zu vernichten, bevor Ihr zurückkehrt.\n\nSo können wir unseres Erfolgs doppelt sicher sein.\n\nIhr gelangt in das Lager, indem Ihr den Weg nach Norden aus der Donnerfeste hinausgeht. Wendet Euch am Ende des Steilwegs nach Westen durch Drachenend hindurch und dann nach Norden durch die Grabenschlucht und die Dolchrachenklamm.", sourceObjective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", completion = "<Tor'chunk nickt und scheint dabei sichtlich zufrieden mit Eurer mörderischen Kühnheit.>\n\nIhr erstaunt mich immer wieder, {name}. Jedes Mal, wenn einer dieser stinkenden Oger zu Boden geht, sind wir einen Schritt näher daran, einen unwürdigen Feind loszuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10785] = { id = 10785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine Falle!", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nBeeilt Euch und bringt die Falle zu Rexxar. Mein Rachedurst muss gestillt werden!", sourceObjective = "Bringt die Drachenfeuerfalle zu Rexxar in der Donnerfeste im Schergrat.", progress = "Habt Ihr bekommen, was auch immer in diesem Sack des Gronns war? Habt Ihr es Zobelmähne gebracht? Hat er Euch etwas für mich mitgegeben?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10786] = { id = 10786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel in Fels'mok", description = "Ich weiß, dass Rexxar Euch nach Fels'mok schicken möchte. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichtemachen!\n\nFels'mok liegt weit im Nordwesten. Reist nach Norden zum Ruuanwald und von dort aus nach Westen durch den Tunnel hinter den Rabenwald.\n\n{name}, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok tötet. Radiert sie aus!", sourceObjective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok. Kehrt danach zu Tor'chunk Zweiklaue in der Donnerfeste im Schergrat zurück.", completion = "<Tor'chunk grinst, als Ihr ihm von Euren Abenteuern in Fels'mok erzählt.>\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, {name}, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10788] = { id = 10788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Talionia zurück", description = "Einer Eurer Meister, Talionia in Silbermond, schickt nach Euch, {name}. Ich bin mir sicher, dass für Euch die Zeit gekommen ist zu lernen, wie man einen mächtigeren Dämon beschwört und kontrolliert. Ich schlage daher vor, dass Ihr Euch sofort auf den Weg macht. Wie ich weiß befindet sich Talionia im Sanktum, einer gemütlichen kleinen Hütte des Bösen an der Mördergasse.", sourceObjective = "Sprecht mit Talionia in Silbermond.", sourceObjectiveStatus = "unverified-source-field" }
quests[10789] = { id = 10789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Carendin Halgar", description = "Ah, da seid Ihr ja, {name}.\n\nCarendin Halgar schickt nach Euch. Ihr sollt ihn im Magieviertel von Unterstadt aufsuchen. Er ist nicht gerade für seine Geduld bekannt, daher würde ich ihn an Eurer Stelle nicht so lange warten lassen.", sourceObjective = "Sprecht mit Carendin Halgar in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10790] = { id = 10790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Gan'rul Blutauge", description = "Ihr seid weit von zu Hause entfernt, {race}. Vielleicht ist es an der Zeit, dass Ihr zurückkehrt, um von Eurem Meister Gan'rul Blutauge zu lernen. Für sein Wissen ist er bei allen, die etwas von der Kunst verstehen, bekannt, sogar bei uns hier.\n\nGan'rul lebt in der Kluft der Schatten in Orgrimmar.", sourceObjective = "Sprecht mit Gan'rul Blutauge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10791] = { id = 10791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen Wolfgeist!", description = "Ich habe die Gewandung, die ich während der Zeremonie tragen werde, fast fertig. Während ich die letzten Handgriffe erledige, möchte ich Euch bitten, diesen Weihrauch bei den Kerzen in der Nähe des Runensteins zu meiner Linken zu platzieren.\n\nIch glaube, dass er uns dabei helfen wird, die Aufmerksamkeit des Wolfgeistes zu erlangen, da er aus den Tagen der orcischen Klans stammt. Ich kann fast schon sehen, wie meine Vorfahren ihn in einer Zeremonie entzündeten, in der sie dem Wolfgeist nach einer erfolgreichen Jagd dankten.\n\nSobald Ihr den Weihrauch platziert habt, werde ich mit der Zeremonie beginnen.", sourceObjective = "Benutzt den zeremoniellen Weihrauch in der Nähe der Kerzen in Malukaz' Hütte und beobachtet die Zeremonie. Sprecht erneut mit Malukaz, wenn die Zeremonie vorbei ist.", progress = "Die Verbindung mit dem Wolfgeist wiederherzustellen ist nur der Anfang meiner Reise, nicht das Ende.", completion = "Es ist unglaublich! Ich bin zu dieser Reise aufgebrochen, ohne auch nur die leiseste Ahnung zu haben, ob der Wolfgeist auf unsere Anrufung hin kommen würde. Und nun fühlt es sich an, als wäre er nie fort gewesen. Vielleicht war er das auch nie, {name}.\n\nVielleicht hat er darauf gewartet, dass die Orcs verstehen, was ihre Entscheidung bewirkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[10792] = { id = 10792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeth'Gor muss brennen!", description = "Der Klan des Blutenden Auges hat seine noble Herkunft verraten! Wir, die Orcs, die gekämpft haben und gestorben sind, um uns vor der Verderbtheit Mannoroths zu schützen, sehen in unseren bösen Vettern nur Schwäche und Unwürdigkeit... und dafür sollen sie brennen!\n\nGeht nach Zeth'Gor, ihre Bastion im Osten, und steckt ihre Gebäude in Brand. Tötet die Peons, um an ihre Fackeln zu kommen, entzündet diese an ihrer Schmiede und werft die brennenden Fackeln auf ihre Hütten, ihren Stall und ihre Kaserne. Brennt sie alle nieder und kehrt dann zu mir zurück!\n\nFür die Horde!", sourceObjective = "Tötet Peons des Blutenden Auges, um an ihre Fackeln zu kommen. Entzündet sie an der Schmiede von Zeth'Gor und werft die brennenden Fackeln auf die Gebäude von Zeth'Gor.", completion = "Hah! Ich konnte die Flammen über Zeth'Gor bis hierher sehen! Mögen unsere Feinde des Blutenden Auges zu Asche zerfallen und keinem wahren Orc mehr unter die Augen kommen!\n\nVielen Dank, {name}. Ihr habt geholfen, eine Beleidigung für den Geist eines jeden Orcs hinfort zu brennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10793] = { id = 10793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'zareqs Tagebuch: Vorboten des Krieges", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", sourceObjective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.\n\nSucht ihn in einem Kristallgefängnis.", progress = "<General Auralion schwebt in der Mitte des Kristalls.>\n\nWa... Was tut Ihr hier?", completion = "Ihr habt ihren Eroberer getötet? Dann haben wir nicht viel Zeit...\n\nDas Purpursiegel besteht aus der Elite von Illidans Dienern. Sie stehen am oberen Ende der Befehlskette für Illidans Armeen außerhalb des Schwarzen Tempels. Diese Soldaten stehen in direktem Kontakt mit dem Verräter und führen seine Anweisung ohne Fragen zu stellen aus.\n\nSie sind diejenigen, die ohne mit der Wimper zu zucken einen Angriff auf diese Welt starten und dabei alles, was ihnen in Wege steht, dem Erdboden gleich machen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10794] = { id = 10794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurken der Zerschmetterten Hand", description = "{name}, es gibt Geheimnisse auf dieser Welt, die wir jetzt noch nicht verstehen. Die Zerschlagene Hand in Orgrimmar kann Euch zu einem dieser Geheimnisse führen: der Kunst, tödliche Gifte zu brauen. Tut einfach, was sie sagen, und Ihr werdet ihr Vertrauen gewinnen.\n\nUm nach Orgrimmar zu kommen müsst Ihr das Portal in Silbermond nach Unterstadt nehmen. Begebt Euch danach aus der Stadt hinaus und sucht den in der Nähe gelegnen Turm auf, bei dem die Zeppeline der Goblins ihre Fahrgäste aufnehmen. Fliegt von dort aus nach Orgrimmar, wo Ihr Shenthul in der Kluft der Schatten finden könnt.", sourceObjective = "Sprecht mit Shenthul in Orgrimmar.", completion = "Ihr wollt also für die Zerschlagene Hand arbeiten? Wie es aussieht, bekommen wir jeden Tag jemand Neues dazu.\n\nHört genau zu. Ich werde Euch erklären, was Ihr zu tun habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10795] = { id = 10795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Dorgok", description = "Gut, ich habe Euch hier gesehen und wollte Euch in einer Angelegenheit von ziemlicher Wichtigkeit sprechen.\n\nMich ereilen Berichte, laut denen die Oger der Blutschläger einen Angriff gegen Sylvanaar und den Rabenwald planen. Wir wissen nicht, wer oder was sie dazu treibt, dies zu tun, aber ich bin entschlossen, ihren Plan im Keim zu ersticken!\n\nDie Angriffe sollen vom Lager der Blutschläger aus starten. Begebt Euch nach Nordwesten den Pfad aus dem Ruuanwald hinab in das Lager. Ich möchte, dass Ihr ihren Anführer Dorgok tötet!", sourceObjective = "Tötet Dorgok im Lager der Blutschläger.", completion = "Jetzt, da Dorgok tot ist, sind die Oger der Blutschläger ohne Anführer und hoffentlich verwirrt, bis ein neuer Anführer aus ihren Rängen gewählt wird.\n\nVielen Dank, {class}. Ich glaube, wir können nun ein wenig aufatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10796] = { id = 10796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet das Lager der Blutschläger!", description = "Ich habe gehört, dass Ihr uns im Kampf gegen die Oger bis jetzt mehr als stolz gemacht habt. Nun möchte ich Euch bitten, ihnen nochmals gegenüber zu treten. Ich möchte, dass Ihr das Lager der Blutschläger vernichtet!\n\nIhr gelangt dorthin, indem Ihr den nordwestlichen Weg aus den Ruuanwald hinab nehmt. Ihr findet die Oger am Ende des Weges.\n\nViel Glück, {class}!", sourceObjective = "Tötet 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger.", completion = "<Der Leutnant nickt und scheint mit Eurer mörderischen Kühnheit sichtlich zufrieden.>\n\nIch bin beeindruckt, {name}. Euer Ruf scheint wohlverdient zu sein.\n\nJedes Mal, wenn einer dieser Oger zu Boden geht, sind wir einen Schritt näher daran, einen Feind loszuwerden, der uns niemals in Frieden lassen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[10797] = { id = 10797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst der Gronn", description = "Aus Dorgoks leblosem Griff fällt ein Abzeichen in Form einer kleinen Statuette. Sie hat frappierende Ähnlichkeit mit einem Gronn.\n\nKommandant Haephus Steinwall im ewigen Hain im Ruuanwald, den Weg im Osten hinauf, ist daran sicher sehr interessiert.", sourceObjective = "Bringt Gorgroms Gunst zu Kommandant Haephus Steinwall im Ewigen Hain im Schergrat.", progress = "Hallo, Junge! Was gibt es Neues?", completion = "Oh, das ist aber hübsch. Sieht ein bisschen aus wie diese Gronn, die die Oger der Speerspießer immer durch die Gegend scheuchen.\n\nKomisch, dass Ihr es in der Hand eines Anführers der Blutschläger gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10798] = { id = 10798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Baron einen Besuch abstatten", description = "Das sind schlechte Nachrichten. Gorgrom der Drachenfresser steckt hinter den Plänen der Blutschläger, Sylvanaar anzugreifen.\n\nIch weiß nicht, warum er sie manipuliert und nicht einfach die Speerspießer dazu benutzt. Aber wenn wir uns mit einem Gronn auseinandersetzen müssen, werden wir Hilfe benötigen.\n\nIch kenne einen Mann, der in allen möglichen Arten exotischer Magie bewandert ist. Sein Name ist Baron Zobelmähne. Er hält sich beim Zirkel des Blutes auf. Ihr könnt dorthin gelangen, indem Ihr den Weg im Nordwesten hinabsteigt und dann nach Südenwesten durch die Schlucht geht.\n\nBittet ihn, uns eine Falle für den Gronn herzustellen.", sourceObjective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", completion = "Ah, ein Gesandter der gerühmten Allianz. Sagt mir, Lakai, warum seid Ihr es, der hierher gekommen ist und mich um dieses Ding bittet, und nicht Eurer illustrer Kommandant?\n\nKann es etwa sein, dass er Angst vor mir hat? Irgendetwas an Euch sagt mir, dass Ihr keine habt, aber ich weiß noch nicht, was das ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[10799] = { id = 10799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grabenschlucht", description = "Nun gut, ich werde diese Falle herstellen, aber zunächst möchte ich etwas dafür haben.\n\nZufälligerweise befindet sich ein Gronn in der Nähe im Besitz eines Gegenstands, den ich haben möchte. Ihr könnt ihm Euch jedoch nicht stellen, zumindest noch nicht.\n\nDaher werden wir ein Schlafpulver aus dem Gift der Krustenbohrer dieser Gegend herstellen.\n\nIhr findet sie in der Grabenschlucht im Südwesten. Bringt mir ein paar ihrer Drüsen und macht schnell!", sourceObjective = "Beschafft Euch 7 Giftdrüsen eines Krustenbohrers.", progress = "Habt Ihr die Giftdrüsen? Wenn nicht, dann hinfort mit Euch und wagt nicht, meine Zeit zu verschwenden, bevor Ihr sie habt!", completion = "Sehr gut, Ihr habt eine einfache, wenn nicht gar banale Aufgabe erfüllt. Nun gebt mir die Drüsen, damit ich den schwierigen Teil erledigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10800] = { id = 10800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Nacht, Gronn", description = "Ich habe mich mal wieder selbst übertroffen. Ich habe für Euch ein Schlafpulver erstellt, das Ihr Grulloc verabreichten könnt, dem Gronn, der besitzt, was ich möchte.\n\nGrulloc hält sich im Verfluchten Dunkel auf. Diese Gegend befindet sich am östlichen Rand von Drachenend auf der anderen Seite des Zirkels des Blutes.\n\nAn Eurer Stelle würde ich nicht lange zögern, sobald Ihr seinen Sack geschnappt habt. Die Wirkung des Staubs lässt schnell nach.", sourceObjective = "Beschafft Euch Grullocs Sack.", progress = "Ihr steht mir wieder gegenüber, {class}. Das muss bedeuten, dass Ihr den Sack unter Grullocs Nase weggeschnappt habt.", completion = "<Baron Zobelmähne lugt in den Sack des Gronns und scheint zufrieden.>\n\nSehr gut, Ihr habt Euren Teil der Abmachung gehalten. Nun werde ich Euren Kommandanten mit der Falle beschenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[10801] = { id = 10801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist eine Falle!", description = "Es gibt nichts, was ich auf der Welt mehr hasse, als die Söhne Gruuls und ihren Vater! Sie haben mein Volk und meine Kinder abgeschlachtet, und nun will ich meine Rache dafür!\n\nIch habe eine Falle aus Drachenfeuer gebaut. Wenn Ihr gewitzt genug seid, könnt Ihr damit einen Gronn töten.\n\nIch bin mir sicher, dass Ihr einen bestimmten Gronn in Sinn habt. Mir ist ganz gleich welcher, Hauptsache, Ihr tötet einen. Beeilt Euch und bringt die Falle zu Kommandant Steinwall.\n\nMein Rachedurst muss gestillt werden!", sourceObjective = "Bringt die Drachenfeuerfalle zu Kommandant Haephus Steinwall im Ewigen Hain im Schergrat.", progress = "Hat der Baron uns eine Falle gebaut? Eine, die stark genug ist, um einen Gronn zu töten?", completion = "Hm, eine Falle, die aus der Essenz einer Drachenflamme gebaut wurde? Ich frage mich, wie Zobelmähne an eine so seltene Substanz gekommen ist!\n\nNun, ganz egal. Nicht egal ist allerdings, dass wir sie benutzen werden, um einen Sohn des Gruul zu töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[10802] = { id = 10802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrom der Drachenfresser", description = "Wir müssen den Ogern zeigen, dass sie sich nicht mit uns anlegen sollten! Wir müssen ihnen eine Nachricht zukommen lassen.\n\nReist nach Fels'mok und tötet die Oger dort. Hebt ihre Köpfe auf!\n\nGeht danach zu Gorgroms Altar und stellt die Falle auf. Daraufhin wird Gorgrom erscheinen. Ihr müsst versuchen, ihn in die Falle zu locken. Wenn er tot ist, stellt die Ogerköpfe als grausige Totems bei seinem Körper auf, damit die Oger ihren gefallenen Meister und ihre gefallenen Kameraden sehen können. Dann werden sie wissen, was man bekommt, wenn man sich mit uns anlegt!", sourceObjective = "Beschafft Euch 3 grausige Totems von den Ogern von Fels'mok. Benutzt danach Zobelmähnes Falle bei Gorgroms Altar, um Gorgrom den Drachenfresser zu rufen und zu töten.\n\nPlatziert die 3 grausigen Totems in der Nähe seines Körpers, wenn er gestorben ist.", progress = "Wurde die Nachricht schon überbracht?", completion = "Gut gemacht, {name}. Sehr gut gemacht!\n\nIch nehme an, dass wir nun nicht mehr von den Ogern und ihrem Herrn hören werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[10803] = { id = 10803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemetzel in Fels'mok", description = "Ich weiß, dass wir vorhaben, Euch nach Fels'mok zu schicken. Es gibt etwas, das Ihr für mich tun könntet, wenn Ihr dort seid.\n\nWir müssen jede Gelegenheit nutzen, um den Ogern dieser Berge einen Schlag zu versetzen. Sonst werden sie uns überrennen und alles, wofür wir geblutet haben und gestorben sind, zunichtemachen!\n\nFels'mok liegt im Westen. Reist nach Südwesten, überquert die Brücke und geht durch den Tunnel. Ihr findet sie auf der westlichen Seite des Rabenwalds.\n\n{name}, ich möchte, dass Ihr die Oger der Speerspießer in Fels'mok auslöscht!", sourceObjective = "Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok.", completion = "<Leutnant Schönwetter grinst, als Ihr ihr von Euren Abenteuern in Fels'mok erzählt.>\n\nAch, ich wünschte, ich hätte mit Euch kommen können. Ich will Euch etwas sagen, {name}, lasst Euch nie auf Pflichten ein, die Euch vom Ruhm der Schlacht fernhalten!\n\nHa! Habt Ihr mir überhaupt noch ein paar Oger in den Bergen übrig gelassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10804] = { id = 10804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundlichkeit", description = "Etwas hat sie aufgescheucht, {race}.\n\n<Mordenai zeigt auf die Netherdrachen, die über Euch fliegen.>\n\nSie kommen nicht einmal herunter, wenn ich sie füttere. Ich habe schon einige gesehen, die einfach zu Boden fielen. Sie sind vor Erschöpfung gestorben, noch bevor ihr Körper die Erde berührt hat.\n\nWir müssen sie retten! Die Felsspitzenschinder, die sich in der Nähe der Kristalle aufhalten, sind ihre natürliche Beute. Tötet die Schinder und nehmt ihre Kadaver. Legt einen Kadaver auf das Feld und verhaltet Euch äußerst ruhig. Solange Ihr keine hektischen Bewegungen macht, werden sie Euch auch nicht angreifen.", sourceObjective = "Mordenai bei den Netherschwingenfeldern im Schattenmondtal möchte, dass Ihr 8 ausgewachsene Drachen der Netherschwingen füttert.", progress = "Ich kann sie nicht alleine retten, {name}!", completion = "Ihr seid ein freundlicher und mitfühlender {race}, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[10805] = { id = 10805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massaker in Gruuls Unterschlupf", description = "Ihr habt Euch als sehr nützlich erwiesen. Daher werde ich Euch in meinem persönlichen Kampf gegen Gruul und seine Söhne einsetzen.\n\nDer Stamm der Speerspießer steht in der Gunst der Gronn. Auch wenn Ihr ihre Reihen an anderen Orten bereits deutlich gelichtet habt, habt Ihr die Stärksten noch nicht erwischt.\n\nGruul lasst seinen Unterschlupf nur von den Kräftigsten unter den Ogern bewachen, und genau die müsst Ihr vernichten. Begebt Euch nach Norden durch die Dolchrachenklamm. An ihrem Ende findet Ihr Gruuls Unterschlupf.", sourceObjective = "Tötet 10 Vollstrecker der Speerspießer, 5 Kampfmagier der Speerspießer, 5 Verheerer der Speerspießer und ihren Anführer Fingrom.", completion = "Sehr gut. Ich habe eine weise Wahl getroffen, als ich Euch zur Speerspitze meines Kampfes gemacht habe. Ich schätze, es ist an der Zeit, die Dinge auf eine ganz neue Ebene zu tragen.\n\nErinnert Ihr Euch an den kleinen Leckerbissen, den Ihr Grolloc für mich unter der Nase weggeschnappt habt? Ihr werdet die Gelegenheit bekommen, ihn sinnvoll einzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10806] = { id = 10806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale", description = "Es ist für uns an der Zeit, uns Goc zu stellen, dem Herrn der Oger der Speerspießer. Es ist auch an der Zeit, dass ich mich in die Geschehnisse einmische und dem Gronn in seiner Todesstunde beiwohne.\n\nNehmt meinen Siegelring. Wenn Ihr zum Altar von Goc gelangt, benutzt ihn und ich werde Euch zu Hilfe kommen.\n\nZusammen werden wir Goc vernichten.", sourceObjective = "Benutzt Zobelmähnes Siegelring beim Altar von Goc und tötet Goc.", progress = "Bald werden alle Söhne des Gruul vernichtet sein.", completion = "Für einen wie Euch habt Ihr erstaunlich gut gekämpft. Es war mir eine Ehre, Euch an meiner Seite zu wissen. Meine Verwandlung muss Euch wohl ein wenig überrascht haben. Ich hoffe, ich habe Euch nicht allzu sehr erschreckt.\n\nWir sollten meine wahre Identität jedoch für uns behalten. Als Belohnung für Eure treuen Dienste biete ich Euch eines dieser Schmuckstücke an.", sourceObjectiveStatus = "unverified-source-field" }
quests[10807] = { id = 10807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aschenzungen", description = "Der Aschenzungenstamm wird von allen Zerschlagenen gefürchtet. Er besteht aus den bösartigsten und blutrünstigsten Gestalten, die von Akama persönlich ausgewählt wurden. Sie sind so wild und rücksichtslos wie jeder Naga, Dämon oder Blutelf in Illidans Armee. Eine große Anzahl von ihnen wurde in den Ruinen von Baa'ri nördlich von hier stationiert. Begebt Euch dorthin und dezimiert ihre Zahl, bevor sie die Gelegenheit haben, uns anzugreifen.", sourceObjective = "Varen der Fordernde möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ehre den Sehern, {name}. Ihr habt den Willen des Lichts ausgeführt und Illidans Anhänger vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[10808] = { id = 10808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Dunklen Rat in die Quere kommen", description = "Die Geister des Dunklen Rats versuchen, ein altes und mächtiges Übel durch ein Ritual, das bei den Lavabecken südlich des Basislagers der Sketh'lon durchgeführt werden soll, in diese Welt zu beschwören.\n\nGul'dans Magie vermischt mit ihrer eigenen! Und damit wollen sie diese Kreatur in unsere Welt rufen! Das dürfen wir nicht zulassen, {name}. Der Tod und die Zerstörung, die dieses Wesen in unsere Welt bringen würde, sind unvorstellbar!\n\nBringt den Stab zu dem Ort, an dem sie die Beschwörung durchführen wollen und benutzt seine Magie, um den Dunklen Rat ein für alle Mal aufzuhalten!", sourceObjective = "Tötet die Ritualisten des Dunklen Rats und benutzt Parshahs Stab, um das Beschwörungsritual des Dunklen Rats zu beenden. Kehrt danach zu Parshah in den Magmafeldern zurück.", progress = "Ist es vollbracht, {name}? Habt Ihr den Dunklen Rat davon abgehalten, das Ritual zu vollenden?", completion = "Ich habe jahrelang nach einem Weg gesucht, um den Dunklen Rat aufzuhalten. Ihr habt geschafft, wobei ich versagt habe. Die finsteren Rituale des Dunklen Rats werden nie wieder zu einer Bedrohung für uns.\n\nIch fühle mich oft schuldig, weil ich meine Kameraden vor all diesen Jahren verlassen habe, aber nun weiß ich endlich, dass es die richtige Entscheidung war. Hätte mein Gewissen damals nicht zu mir gesprochen, wäre ich nun vielleicht ein Schatten unter ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10809] = { id = 10809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Worgmeister Kruush", description = "Auf dem Anschlag steht geschrieben:\n\n\"Worgmeister Kruush führt die Worgreiter des Blutenden Auges an. Da seine Reiter große Opfer unter den Versorgungskarawanen des Rückenbrecherpostens gefordert haben, wurde ein Preis auf seinen Kopf ausgesetzt.\"\n\n\"Späher berichten, dass er in Zeth'Gor gesehen wurde. Der Held, der den abgetrennten Kopf des Übeltäters zu mir bringt, wird den Dank der Horde sowie ein großzügiges Kopfgeld erhalten.\"\n\nGezeichnet: Hauptmann Nachtheul", sourceObjective = "Tötet Worgmeister Kruush und bringt seinen Kopf zu Hauptmann Nachtheul im Rückenbrecherposten.", progress = "Berichtet, {name}. Ist das Blut des Blutenden Auges da auf Eurem Ärmel? Ich hoffe doch!", completion = "Ihr habt also den Tunichtgut Kruush erschlagen! Gut gemacht, {name}! Sehr gut! Sein Tod wird seinen verfluchten Worgreitern die Giftzähne ziehen! Ich hoffe, Ihr habt auch ein paar von ihnen erledigt, als Ihr Euren kleinen Ausflug nach Zeth'Gor gemacht habt!\n\nHier ist Eure Belohung. Ihr habt sie Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[10810] = { id = 10810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die beschädigte Maske", description = "Während ihr die beschädigte Maske betrachtet, hört Ihr Geräusche aus ihrem Inneren kommen. Wenn die Maske nicht beschädigt wäre, könntet Ihr die Geräusche deutlicher hören.\n\nO'Mally Zapschnapper im Ruuanwald könnte sie vielleicht reparieren.", sourceObjective = "Bringt die beschädigte Maske zu O'Mally Zapschnapper in den Ewigen Hain im Schergrat.", progress = "Geht mir nicht auf die Nerven! Könnt Ihr nicht sehen, dass ich dabei bin, mysteriöse Kräfte zu entfesseln?", completion = "Ah, was habt Ihr denn da? Lasst mich das mal genauer ansehen, {class}. Ja, ja... es ist genau das, was ich dachte. Lasst mich die Maske für Euch reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10811] = { id = 10811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Neltharaku auf", description = "Ihr Patron schwebt hoch oben in den Lüften, {name}. Vielleicht hat die Freundlichkeit, die Ihr seinen Kindern gegenüber gezeigt habt, sein Herz bewegt. Sucht Neltharaku auf und bittet ihn um Hilfe. Zusammen könnt Ihr vielleicht die Not der Netherschwingendrachen beenden.\n\n<Mordenai zeigt in den Himmel.>\n\nFliegt hoch, {class}.", sourceObjective = "Sucht Neltharaku, den Patron des Drachenschwarms der Netherschwingen auf.", completion = "Meine Kinder haben mir von Eurer heldenhaften Tat erzählt, {race}. Es gibt noch mehr, was Ihr tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10812] = { id = 10812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheimnisvolle Maske", description = "Gut, jetzt sollte sie funktionieren. Was das ist, fragt Ihr? Nun, es ist ein Kommunikationsgerät. Diese Schafsköpfe kommunizieren so miteinander. Ihr wisst schon, die Brennende Legion! Ich würde Euch empfehlen, die Maske zu Wildfürst Antelarion zu bringen. Er geht dort drüben auf und ab. Immer in Bewegung!\n\nNun los mit Euch! Er versucht schon eine ganze Weile eine von den Masken in die Finger zu bekommen.", sourceObjective = "Bringt die geheimnisvolle Maske zu Wildfürst Antelarion in den Ewigen Hain im Schergrat.", progress = "Ich traue meinen Augen nicht.", completion = "Diese Maske, die Ihr da in den Händen haltet, ist eine Gasmaske der Teufelsbrut! Und wie es aussieht, ist sie nicht beschädigt! Der Ärger, den wir damit im Konstruktionslager: Groll anrichten können, ist grenzenlos! Habt Ihr Lust, uns dabei zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10813] = { id = 10813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Grillok", description = "{name}, Ihr habt im Nest der Orcs des Blutenden Auges, im gefürchteten Zeth'Gor, Euren Heldenmut bewiesen und überlebt! Vielleicht seid Ihr stark genug, um mir zu helfen, denn ich werde in den Geist ihres finstersten Hexers blicken, Grillok!\n\nNehmt diesen Splitter. Benutzt ihn, um ein Auge von Grillok zu behexen und bindet es an Euch. Kehrt dann zu mir zurück und nähert Euch meinem Kessel... er wird das Auge anziehen.\n\nGeht, {name}. Und seid auf der Hut! Ein Auge von Grillok wird Euch an Eure Feinde verraten, wenn es auch nur die geringste Gelegenheit dazu bekommt!", sourceObjective = "Benutzt Zezzaks Splitter, um ein Auge von Grillok zu fangen und nähert Euch damit Zezzaks Kessel. Bringt den Splitter zu Zezzak zurück, wenn Ihr das Auge dem Kessel übergeben habt.", progress = "Die Orcs des Blutenden Auges waren einst starke Verbündete... und nun sind sie noch stärkere Feinde.", completion = "Ich stehe tief in Eurer Schuld, {name}. Ihr habt ein weiteres Mal über Zeth'Gor triumphiert und seine Dunkelheit nahe an Euer Herz gelassen. Ich werde das Auge untersuchen und damit hoffentlich die Geheimnisse seines Meisters Grillok lüften.\n\nHoffentlich kann es seine Magie nicht länger einsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10814] = { id = 10814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharakus Geschichte", description = "Ich habe Informationen, die Euch vielleicht weiterhelfen können. Bitte hört Euch an, was ich zu erzählen habe.", sourceObjective = "Sprecht mit Neltharaku und hört Euch seine Geschichte an.", completion = "Werdet Ihr uns also helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10815] = { id = 10815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'zareqs Tagebuch: Vorboten des Krieges", description = "Dieses Tagebuch dokumentiert die letzten Handlungen von Illidans Armeen. Es erklärt auch, warum Val'zareq auf dem Pfad der Eroberung eine Parade abgehalten hat. Er war persönlich für die Gefangennahme eines hohen Generals der Sha'tar verantwortlich.\n\nDieser General wird an einem Außenposten namens Purpurwacht, der sich am südlichen Ende des Pfades der Eroberung befindet, gefangen gehalten. Eine mysteriöse Vereinigung, die sich selbst das Purpursiegel nennt, ist dafür verantwortlich, ihn sicher unter Verschluss zu halten. Wenn Ihr Euch entschließt, weitere Nachforschungen anzustellen, solltet Ihr einige Verbündete mitnehmen.", sourceObjective = "Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[10816] = { id = 10816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückforderung geheiligten Bodens", description = "Ihr habt Eure Arbeit bei den Zerschlagenen in Baa'ri gut gemacht, {name}. Wollen wir mal sehen, wie Ihr gegen Illidans gefürchtetste Armee besteht.\n\nDie Terrasse von Ata'mal war einst eine geheiligte Stätte, an der wir die Kristalle von Ata'mal benutzten, um spirituelle Zeremonien durchzuführen. Nun ist dieser Orts von den Höllenorcs des Schattenmondklans besetzt worden.\n\nWir hatten guten Grund zur Annahme, dass sie einen Kristall von Ata'mal in der Nähe versteckt halten, aber unsere magische Beobachtung dieses Ortes lieferte kein Ergebnis. Dennoch sind die Orcs auf unserem geheiligten Boden eine Schmach, die wir nicht tolerieren können.", sourceObjective = "Verteidiger Aluumen möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Aufgaben für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", completion = "Ausgezeichnete Arbeit, {class}. Möge das Licht Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10817] = { id = 10817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Vergeltung", description = "Ihr habt Euch im Kampf gegen die Zerschlagenen der Aschenzungen tapfer geschlagen, {name}. Wenn Ihr bereit seid, habe ich eine weitere Herausforderung für Euch.\n\nVor nicht allzu langer Zeit wurde das Sanktum der Sterne Opfer eines gewaltigen Angriffs durch Illidans Höllenorcs.\n\nWir haben herausgefunden, dass die Schattenmondorcs, die die Terrasse von Ata'mal behausen, dieses Verbrechen verübt haben.\n\nZeigt ihnen, dass man sich besser nicht mit den Sehern anlegen sollte!", sourceObjective = "Varen der Fordernde möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.\n\nDas Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", completion = "Ihr habt meinen höchsten Respekt verdient, {name}.\n\nEinen Höllenorc alleine zu töten ist schon keine leichte Aufgabe. Eine ganze Meute von ihnen zu töten ist, nun... heroisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10818] = { id = 10818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Zobelmähne verlangt nach Euch", description = "{name}, während Ihr Euch da draußen wie <ein/eine:c> Teufels{class} geschlagen habt, hat Baron Zobelmähne seinen Drachen mit einer Nachricht hierher geschickt.\n\nEr hat nach Euch persönlich gefragt. So wie ich es verstanden habe, möchte er, dass Ihr seinen eigenen Kampf gegen die Gronn weiterführt.\n\nIch schätze, dass Ihr wohl die geeignetste Person in der ganzen Scherbenwelt seid, um ihm dabei zu helfen, aber an Eurer Stelle würde ich ein paar Freunde bitten, Euch zum Zirkel des Blutes zu begleiten.", sourceObjective = "Sprecht mit Baron Zobelmähne im Zirkel des Blutes im Schergrat.", completion = "Ah, wie ich sehe habt Ihr beschlossen, Euch ganz schön Zeit zu lassen, bis Ihr meinem Aufruf Folge geleistet habt.\n\nWie auch immer, ich hatte genug Zeit, um an meinen Racheplänen zu feilen, und Ihr sollt in der kommenden Schlacht mein Vollstrecker sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[10819] = { id = 10819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gasmaske der Teufelsbrut", description = "Ich habe eine ganz besondere Aufgabe für Euch, {name}. Ich möchte, dass Ihr Euch in das Konstruktionslager: Groll östlich von hier einschleicht. Ihr werdet die Gasmaske der Teufelsbrut tragen müssen, wenn Ihr das Lager betretet, um den Legionskommunikator zu suchen. Sobald Ihr das Kommunikationsgerät gefunden habt, benutzt es. Sprecht mit demjenigen, der sich auf der anderen Seite meldet.\n\nWenn alles klappt, könnt Ihr dem Dämon ein Märchen auftischen! Versucht, ihm zu erzählen, dass im Konstruktionslager: Groll ein Aufstand ausgebrochen ist.\n\nViel Glück, {class}.", sourceObjective = "Setzt die Gasmaske der Teufelsbrut auf und benutzt den Legionskommunikator im Konstruktionslager: Groll im Schergrat.\n\nBereitgestellter Gegenstand:", completion = "Was soll das bedeuten? Niemand ruft mich! Sprecht, oder ich werde Euch für immer zum Schweigen bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10820] = { id = 10820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuscht den Feind", description = "Mit jedem Moment, in dem ich Stille höre, rückt Ihr dem Tod ein Stückchen näher! SPRECHT!\n\nWas? Das Lager revoltiert? Das kann nicht wahr sein! Meine Diener würden es niemals wagen, meine Autorität zu untergraben.\n\nNun gut, jeder Einzelne von ihnen wird für diesen Verrat bezahlen... teuer bezahlen! Bringt sie alle zum Schweigen! Meldet Euch bei mir zurück, wenn Ihr meinen Befehl ausgeführt habt, oder ich werde mich um Euch kümmern.", sourceObjective = "Tötet 4 Knechte der Schicksalsschmiede und 4 Ingenieure der Schicksalsschmiede.", progress = "Meine Geduld neigt sich dem Ende zu, warum habt Ihr sie noch nicht erledigt?", completion = "Das wird ihnen sicher zeigen, dass sie besser tun sollten, was ich ihnen sage...\n\nÜbrigens... wo ist Schicksalsrufer? Warum habt Ihr mir von dieser Revolte berichtet und nicht sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[10821] = { id = 10821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid gefeuert!", description = "Schicksalsruferin hat nichts gegen den Aufstand unternommen? Wie kann sie es wagen! Sie hat schon seit einer Weile versucht, meine Autorität zu untergraben. Doch zum allerletzten Mal! Ihr müsst sie rufen und persönlich zur Verantwortung ziehen.\n\nIhre Grollwachen tragen die Schlüssel bei sich, mit denen sie ins Konstruktionslager: Groll gerufen werden kann. Beschafft Euch die fünf Schlüssel und aktiviert die fünf Obelisken der Legion. Die Obelisken schalten sich nach kurzer Zeit wieder ab, also seht zu, dass Ihr sie alle gleichzeitig aktiviert. Und denkt daran: die Grollwachen tragen noch mehr Schlüssel bei sich.", sourceObjective = "Tötet Schicksalsruferin.", completion = "Das sind wirklich großartige Nachrichten, {name}. Ich hätte es mir nicht besser wünschen können. Eure Dienste gegenüber meinem Volk sind sehr geschätzt. Bitte wählt Euch einen dieser Gegenstände aus.\n\nEuer Name wird für immer in den Herzen unseres Volkes klingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10822] = { id = 10822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Siegel des Sonnenzorns", progress = "Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, {name}. Unsere Feinde sind stark, aber wir werden siegen!", completion = "Sieg für die Seher! Kaels Streitmächte werden bald fallen!" }
quests[10823] = { id = 10823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Siegel des Sonnenzorns", progress = "Wir verläuft der Kampf gegen Kaels Streitmächte?", completion = "Ihr macht Euch einen Namen, {name}. Weiter so!" }
quests[10824] = { id = 10824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Sonnenzorns", description = "Das Überleben der Seher hängt davon ab, ob wir es schaffen, mehr Rekruten zu sammeln als Kael'thas. Jeder Pilger aus Quel'Thalas, der sich auf seine Seite schlägt, bringt ihn einen Schritt näher an den Sieg. Und das bedeutet das Gegenteil für uns.\n\nBald werden uns jedoch die Rekruten ausgehen und es wird darauf hinauslaufen, wer den anderen schneller tötet. Beweist Euch gegenüber den Sehern und bringt mir die Siegel des Sonnenzorns der höherrangigen Blutelfen, die im Bunde mit Illidan und Kael'thas stehen. Ihr findet sie bei der Stätte der Mondfinsternis im Westen und in den Ruinen von Karabor im Nordosten.", sourceObjective = "Kampfmagierin Vyara beim Sanktum der Sterne möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.\n\nDas Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor.", progress = "Los, {name}. Sprecht.", completion = "Kaels Armee des Sonnenzorns ist sehr gut ausgebildet. Ausgezeichnete Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10825] = { id = 10825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kugellose Wahrheit", description = "Diese merkwürdige, magische Kugel fällt aus dem Federkleid des Arakkoa.\n\nSie ist von einem unheimlichen violetten Leuchten umgeben und pulsiert zu einem unhörbaren Takt. Sie in der Hand zu halten gibt Euch ein unangenehmes Gefühl, daher packt Ihr sie schnell in Eure Tasche.\n\nVielleicht würde Baumhüter Chawn im Ruuanwald im Westen, jenseits des Tunnels und der Brücke des Wyrmschädels, sie gerne untersuchen?", sourceObjective = "Bringt die Kugel der Grishna zu Baumhüter Chawn in den Ewigen Hain im Schergrat.", progress = "{class}, könnt Ihr das spüren? Ich fühle, dass etwas Unnatürliches und Böses in der Nähe ist.", completion = "Ja, es ist die Kugel, die Ihr da habt! Merkwürdig, sie scheint von den Arakkoa zu stammen. Wart Ihr kürzlich in Grishnath?\n\nAh, das erklärt das Ganze. Aber ich frage mich, welchem teuflischen Zweck dieses Objekt dient. Obwohl das Böse eindeutig darin schlummert, scheint sie doch mit der Natur verbunden zu sein.\n\nBitte erlaubt mir zu versuchen, sie zu aktivieren. Das Böse darin ist so stark, es erinnert mich an etwas...", sourceObjectiveStatus = "unverified-source-field" }
quests[10826] = { id = 10826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Male des Sargeras", description = "Inzwischen sollte Euch klar geworden sein, dass wir der Brennenden Legion und ihren Dienern feindlich gesonnen sind.\n\nWenn Ihr Euch den Aldor gegenüber beweisen wollt, dann bringt mir die Insignien der hochrangigen Mitglieder der Legion und ihrer Anhänger des Schattenrats. Hier im Schattenmondtal könnt Ihr eine große Ansammlung der Legion weit im Westen in der Feste der Legion und der Todesschmiede finden.", sourceObjective = "Bringt 10 Male des Sargeras zu Herold Saronen im Schattenmondtal.\n\nDas Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern.", progress = "Tragt Ihr irgendwelche Insignien des Feindes bei Euch, {name}?", completion = "Ihr seid sehr mutig, Freund. Mögen alle wissen, dass Ihr ein wahrer Freund der Priesterschaft seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[10827] = { id = 10827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Male des Sargeras", progress = "Tragt Ihr noch mehr Insignien des Feindes bei Euch, {name}? Wir bekämpfen die Legion, bis das Licht siegt!", completion = "Besiegt die Feinde des Lichts, wo immer Ihr sie findet, {name}." }
quests[10828] = { id = 10828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelne Male des Sargeras", progress = "Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben.", completion = "Ihr beweist auch weiterhin Euren Wert, {name}." }
quests[10829] = { id = 10829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baumriese muss es wissen", description = "Das ist erschütternd! Die Arakkoa bewirken, dass die Urtume und Beschützer von bösen Geistern besessen werden!\n\nEs gibt jedoch ein Urtum, das auf gar keinen Fall davon betroffen sein kann. Sein Name ist Baumriese. Wenn wir die Bäume des Rabenwaldes retten wollen, müsst Ihr sofort zu ihm gehen!\n\nBegebt Euch in den Rabenwald. Ihr findet ihn an der Weggabelung kurz hinter Grishnath.", sourceObjective = "Sprecht mit Baumriese, ein Urtum der Lehren, das im Rabenwald im Schergrat lebt.", completion = "Grüße, kleiner {race}. Die Vögel in meinen Zweigen haben mir zugeflüstert, dass Ihr kommen würdet.\n\nIhr seid hier, um die Bäume des Waldes von ihrer Besessenheit zu heilen?", sourceObjectiveStatus = "unverified-source-field" }
quests[10830] = { id = 10830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Exorzismus der Bäume", description = "Die Grishna sind dafür verantwortlich, dass die Laubbärte und Steinborken von bösen Koikoigeistern übernommen werden.\n\nWir müssen die Bäume retten, sonst ist der Rabenwald bald verloren!\n\nKombiniert die Macht einer Kugel von Grishnath, die überall in Grishnath zu finden sind, mit einem Terrorfederkiel eines Terrorraben.\n\nBenutzt die dadurch entstandene Exorzismusfeder, um die Koikoigeister hervorzulocken und so schnell wie möglich umzubringen. Die Steinborken sind für dieses Ritual zu stark, aber wenn Ihr genügend Laubbärte befreit, werden auch sie frei sein.", sourceObjective = "Sammelt 5 Kugeln von Grishnath und 5 Terrorfederkiele und stellt daraus Exorzismusfedern her. Benutzt die Federn, um 5 Koikoigeister von den Laubbärten des Rabenwaldes zu exorzieren und zu töten.", progress = "Das Böse, das den Bäumen innewohnt, breitet sich auf die gesamte Natur des Waldes aus.\n\nIhr müsst schnell handeln, {name}, bevor es zu spät ist!", completion = "Das Böse verschwindet aus dem Rabenwald! Könnt Ihr es fühlen, {name}?\n\nIhr habt uns und alle Wildtiere hier vor der unweigerlichen Zerstörung gerettet, kleines Wesen!\n\nFür solche Gelegenheiten trage ich vier magische Ringe in meinen Zweigen und verschenke sie, wenn ein Held sich erhebt, um eine große Tat zu vollbringen.\n\nIhr seid solch ein Held! Im Namen des gesamten Rabenwaldes danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[10831] = { id = 10831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Mondstoffschneider wird", description = "Ich kann Euch die Kunst des Mondstoffschneiderns beibringen, wenn Ihr möchtet. Wenn Ihr Euch auf die Mondstoffschneiderei spezialisiert, werdet Ihr bei der Herstellung von Urmondstoff den doppelten Ertrag erhalten und Zugang zu mehreren exklusiven Mustern bekommen. Dazu müsst Ihr nur einen einfachen Test bestehen.\n\nDer Test besteht darin, eine kleine Probe Urmondstoff im Mondbrunnen der Zuflucht des Cenarius herzustellen. Ich werde Euch alle Materialien, die Ihr dafür benötigt, zur Verfügung stellen. Bringt mir die Probe, wenn Ihr sie fertig gestellt habt, damit ich sie beurteilen kann.", sourceObjective = "Benutzt das magieerfüllte Netherstoffstück während Ihr im Mondbrunnen der Zuflucht des Cenarius steht, um eine Urmondstoffprobe herzustellen. Bringt die fertige Urmondstoffprobe zu Nasmara Mondweise im Unteren Viertel von Shattrath.\n\nACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen.", progress = "Habt Ihr die Urmondstoffprobe hergestellt?", completion = "<Nasmara untersucht den Stoff und dreht ihn in den Händen hin und her.>\n\nDas ist eine hervorragende Probe, {name}. Ihr werdet einen ausgezeichneten Mondstoffschneider abgeben.", sourceObjectiveStatus = "unverified-source-field" }
